window.TURATH_JK(56,{"2":["أي: أن الله أخفاها عن جميع المخلوقين، من الملائكة والأنبياء والمرسلين وغيرهم. ولا يعلمها إلا الله عزوجل."],"3":["قوله: إِذْ تَمْشِي أُخْتُكَ اسمها مريم، وكانت تنظر من بعيد عسى ما يكون؟، فلما نزلتْ امرأةُ فرعون لتغتسلَ في نهر النيل، ورأت الولدَ في التابوت، رقَّ له قلبُها، وقالت: إنه لا بد من أولاد العبرانيين، ولما استقرَّ عند آل فرعون، عرضوا عليه المراضع، فأباها، قال الله عزوجل: ﴿وَحَرَّمْنَا عَلَيْهِ الْمَرَاضِعَ مِنْ قَبْلُ فجا﴾ءتْ أختُه مريم، ﴿هَلْ أَدُلُّكُمْ عَلَى أَهْلِ بَيْتٍ يَكْفُلُونَهُ لَكُمْ وَهُمْ لَهُ نَاصِحُونَ﴾ [القصص: ١٢] فقيل لها: اذهبي، فذهبتْ ودعتْ أمَّها وأمَّ موسى، فصارتْ أمُّه مرضعةً بأجرةٍ، فقرَّتْ عينُها، وذهبَ حزنُها. قال تعالى: فَرَجَعْنَاكَ ﴿إِلَى أُمِّكَ كَيْ تَقَرَّ عَيْنُهَا﴾ [طه: ٤٠]","قوله: ﴿وَقَتَلْتَ نَفْسًا فَنَجَّيْنَاكَ مِنَ الْغَمِّ وَفَتَنَّاكَ فُتُونًا﴾","لم يبيّن اللهُ تعالى جنس النفس، وثبت في التراث الإسرائيلي أن المقتول كان مصريّاً من آل فرعون، وصحَّ عندنا أيضا كما في الحديث الآتي:"],"5":["قوله: وَالسَّلَامُ ﴿عَلَى مَنِ اتَّبَعَ الْهُدَى أي﴾: السلام عليك إن اتبعت الهدى، وهكذا كان النبي صلى الله عليه وسلم يكتب في رسائله إلى الملوك، يدعوهم إلى الإسلام، فيقول:"],"9":["قوله: ﴿بَصُرْتُ بِمَا لَمْ يَبْصُرُوا بِهِ﴾ أي: رأيتُ جبريلَ حين جاء لهلاك فرعون.","وقوله: ﴿فَقَبَضْتُ قَبْضَةً مِنْ أَثَرِ الرَّسُولِ﴾ أي: من أثر فرسه، والرسولُ هو جبريل.","هذا قولُ أكثر المفسّرين إلا أن سياق الآية يدلّ على أن المرادَ بالرسول هو موسى عليه السلام نفسه، لأنه لما ذهب موسى عليه السلام إلى الوادي المقدّس، أمرَه اللهُ تعالى أن يخلعَ نعلَيْه، فاكتسبَ أثرُه من هذا ما لم يره غيرُ السامري، فأخذَ قبضةً من ترابٍ من آثاره، وألقاه في فم العجل، فصار له خوارٌ، فأخبرَ اللهُ موسى بذلك: ﴿قَالَ فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ مِنْ بَعْدِكَ وَأَضَلَّهُمُ السَّامِرِيُّ﴾ [سورة طه: ٨٥]"],"14":["قوله: ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا﴾ يعني: صلاة الفجر وصلاة العصر، كما جاء في الصحيح:"],"16":["قوله: وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا"],"17":["وهذه البينة هي القرآن وهو مصدق لما في الكتب السابقة من أخبار الأنبياء ومن المواعظ والخطب، وأصول التشريع، والنبي الذي جاء به هو أمي لا يقرأ ولا يكتب، ولا من أهل الكتاب، ومع ذلك فقد جاء بهذا الكتاب العظيم."],"19":["قوله: ﴿وَمَنْ عِنْدَهُ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِ﴾ أي: الملائكة دائبون في طاعة الله عزوجل وعبادته ليلا ونهارا دون انقطاع، كما جاء في الحديث."],"24":["هذه الأرض المباركة هي أرض الشام، وإبراهيم ولوط عليهما السلام كانا بأرض العراق، وبعد امتحان إبراهيم عليه السلام خرج من العراق، ومعه زوجته سارة، وابن أخيه لوط، وهو أول هجرة في تاريخ الأديان من أجل المحافظة على العقيدة والدين، وحكى الله على لسان إبراهيم ﴿وَقَالَ إِنِّي مُهَاجِرٌ إِلَى رَبِّي إِنَّهُ هُوَ الْعَزِيزُ الْحَكِيمُ﴾ [العنكبوت: ٢٦]","وقوله: بَارَكْنَا فِيهَا أي أنها أرض خصب، ورخاء، وكثرة الأنهار، ومنها سيبعث الله الأنبياء والرسل."],"25":["قوله: مِنْ قَبْلُ أي من قبل إبراهيم ولوط.","وقوله: وَأَهْلَهُ أي أهل بيته غير ابنه الذي كفر به.","وقوله: الْكَرْبِ الْعَظِيمِ وهو الطوفان الذي أغرق من في الأرض جميعا، ووصف بكونه \"العظيم\" لشدة هوله وأنه يلاحق الناس بمواقع هروبهم حتى أغرقهم."],"26":["قوله: ﴿إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ﴾ نفش نفشا ونفوشا تفرق وانتشر، ويقال: نفشت الماشية في الزرع انتشرت فيه ورعتْه ليلا.","وخلاصة القصة كما رُوي عن ابن عباس وغيره من الصحابة والتابعين أن رجلين دخلا على داود، أحدهما صاحب حرث، والآخر صاحب غنم، فقال: صاحب الحرث: إن هذا أرسل غنمه في حرثي، فلم يبقِ من حرثي شيئا، فقال له داود: اذهب فإن الغنم كلها لك، فقضى بذلك داود. ومرَّ صاحب الغنم بسليمان فأخبره بالذي قضى به داود، فدخل سليمان على داود فقال: يا نبي الله إن القضاء سوى الذي قضيت، فقال: كيف؟ قال سليمان: إن الحرث لا يخفى على صاحبه ما يخرج منه في كل عام، فله من صاحب الغنم أن يبيع من أولادها وأصوافها وأشعارها حتى يستوفى ثمن الحرث، فإن الغنم لها نسل في كل عام.","فقال داود: قد أصبت، القضاء كما قضيت ففهمها الله سليمان.","روي عن ابن مسعود، في قوله: وَدَاوُ﴿ودَ وَسُلَيْمَانَ إِذْ يَحْكُمَانِ فِي الْحَرْثِ إِذْ نَفَشَتْ فِيهِ غَنَمُ الْقَوْمِ﴾ قال: \"كرم قد أنبتت عناقيده، فأفسدته، قال: فقضى داود بالغنم لصاحب الكرم، فقال سليمان: غير هذا يا نبيّ الله، قال: وما ذاك؟ قال: يدفع الكرم إلى صاحب الغنم، فيقوم عليه حتى يعود كما كان، وتدفع الغنم إلى صاحب الكرم، فيصيب منها، حتى إذا كان الكرم كما كان دَفعت الكرم إلى صاحبه، ودَفعت الغنم إلى صاحبها، فذلك قوله: فَفَهَّمْنَاهَا سُلَيْمَانَ رواه ابن جرير (16/322)، والحاكم (2/588) كلاهما من طريق عبدالرحمن بن محمد المحاربيّ، عن أشعث، عن أبي إسحاق، عن مرّة، عن ابن مسعود، فذكره.","وفي الإسناد أشعث وهو ابن سوار الكندي، وهو ضعيف.","ومن جملة ما فُهِّم سليمانُ قصة المرأتين كما جاء في الصحيح."],"27":["هذا الضر على نوعين:","الأول: ضر في متاع الدنيا من الأموال والمواشي والخدم، فقد ذكر أهل التفسير أن له كذا وكذا من الأموال، وكذا من البنين والبنات فهلكت الأموال ومات الأولاد.","والثاني: ما أصيب من الأمراض في جسمه، وفي سفر أيوب من التوراة كثير من التفاصيل من هذا الابتلاء، وأنه رجل صالح مستقيم يتقي الله ويحيد عن الشر، فلما دعا الله عز وجل كشف الله عنه الضر الذي أصابه في ماله وأولاده وجسمه، وصار أيوب فيما بعد يُضرب به المثَلُ في الصبر.","فإنْ قيل: ﴿إن الله سمّاه صابرا، وقد أظهر الشكوى والجزع بقوله: أَنِّي مَسَّنِيَ الضُّرُّ قيل: ليس هذا شكاية، إنما هو دعاء بدليل قوله تعالى: فَاسْتَجَبْنَا لَهُ فَكَشَفْنَا مَا بِهِ مِنْ ضُرٍّ على أن الجزع إنما هو الشكوى إلى الخلق، فأما الشكوى إلى الله عزوجل فلا يكون جزعا ولا ترك صبر كما قال يعقوب: إِنَّمَا أَشْكُو بَثِّي وَحُزْنِي إِلَى اللَّهِ﴾ [سورة يوسف: ٨٦]","وقوله: وَآتَيْنَاهُ ﴿أَهْلَهُ وَمِثْلَهُمْ مَعَهُمْ رَحْمَةً مِنْ عِنْدِنَا﴾","ظاهر الآية يدل على أن الله ردَّ عليه ماله وولده عيانا، ومثلهم معهم. وبه قال ابن عباس، وابن مسعود، وقتادة، والحسن، وأكثر المفسرين.","وقال غيرهم: آتى الله أيوب في الدنيا مثل أهله الذين هلكوا، فأما الذين هلكوا فإنهم لم يردوا عليه في الدنيا."],"28":["قوله: وَذَا النُّونِ أي صاحب الحوت لقب به يونس بن متى عليه السلام للقصة التي وقعت له مع الحوت.","وقوله: مُغَاضِبًا أي من قومه أهل نينوى إذ أبوا أن يؤمنوا بما أرسل به.","قوله: فَنَادَى فِي الظُّلُمَاتِ أي: ظلمة بطن الحوت، وظلمة البحر، وظلمة الليل.","وقوله: ﴿لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ﴾"],"29":["قوله: ﴿وَالَّتِي أَحْصَنَتْ فَرْجَهَا﴾ هي بنت عمران كما جاء في قوله تعالى: ﴿وَمَرْيَمَ ابْنَتَ عِمْرَانَ الَّتِي أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِنْ رُوحِنَا وَصَدَّقَتْ بِكَلِمَاتِ رَبِّهَا وَكُتُبِهِ وَكَانَتْ مِنَ الْقَانِتِينَ﴾ [سورة التحريم: ١٢]."],"30":["قوله: ﴿حَتَّى إِذَا فُتِحَتْ يَأْجُوجُ وَمَأْجُوجُ﴾ أي السدّ وفيه يقدر المضاف، وهو أمة يأجوج ومأجوج، فإنهما قبيلتان، فيكتسب التأنيث من المضاف إليه.","وقوله: مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ أي نشز وتل، والحدب هو المكان المرتفع.","ويأجوج ومأجوج هم من سلالة آدم عليه السلام، وقد جاء ذكرهم في سورة الكهف [94] ويكون ظهورهم قبل يوم القيامة كما جاء في الصحيح."],"32":["قوله: ﴿يَوْمَ نَطْوِي السَّمَاءَ كَطَيِّ السِّجِلِّ لِلْكُتُبِ﴾ هذا يكون يوم القيامة، كما قال تعالى: ﴿وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ وَالْأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّمَاوَاتُ﴾ مَطْوِيَّاتٌ بِيَمِينِهِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ [سورة الزمر: ٦٧]، وقد جاء في ذلك أحاديث، منها:"],"33":["قوله: الزَّبُورِ إذا أطلق فالمقصود منه زبور داود عليه السلام، وعمّمَ بعضهم فقال: هو كل كتاب مسطور ومنه القرآن أيضا.","وقوله: الْأَرْضَ أي أرض الجنة.","وقوله: عِبَادِيَ الصَّالِحُونَ هم من أمة محمد صلى الله عليه وسلم، وكذلك الأنبياء السابقون والمؤمنون بهم، وهو شبيه بقوله تعالى: ﴿وَقَالُوا الْحَمْدُ لِلَّهِ الَّذِي صَدَقَنَا وَعْدَهُ وَأَوْرَثَنَا الْأَرْضَ نَتَبَوَّأُ مِنَ الْجَنَّةِ حَيْثُ نَشَاءُ فَنِعْمَ أَجْرُ الْعَامِلِينَ﴾ [ الزمر: 74]"],"34":["قوله: لِلْعَالَمِينَ شامل للإنس والجن والبهائم، فكان النبي صلى الله عليه وسلم رحمة للجميع."],"36":["قوله: زَلْزَلَةَ السَّاعَةِ أي يوم القيامة، والأحاديث في أهوال يوم القيامة كثيرة، منها:"],"37":["يذكر الله تعالى الدليل على قدرته على المعاد فإن من خلق الإنسان من نطفة أمشاج وجعله سميعا بصيرا، قادرٌ على أن يبعثه يوم القيامة، وقد جاء في الحديث ذكر المراحل التي يمر بها خلق الإنسان فمنها:"],"39":["قوله: ﴿أَلَمْ تَرَ أَنَّ اللَّهَ يَسْجُدُ لَهُ مَنْ فِي السَّمَاوَاتِ﴾ وَمَنْ فِي الْأَرْضِ أي: أن الله يسجد له كل شيء طوعا وكرها، وسجود كل شيء له سبحانه يكون على وجه خاص به، علّمه الله تعالى، كما قال سبحانه: ﴿أَوَلَمْ يَرَوْا إِلَى مَا خَلَقَ اللَّهُ مِنْ شَيْءٍ يَتَفَيَّأُ﴾ ظِلَالُ﴿هُ عَنِ الْيَمِينِ وَالشَّمَائِلِ سُجَّدًا لِلَّهِ وَهُمْ دَاخِرُونَ﴾ [سورة النحل: ٤٨]، وقال تعالى: ﴿أَلَمْ تَرَ أَنَّ اللَّهَ يُسَبِّحُ لَهُ مَنْ فِي السَّمَاوَاتِ﴾ وَالْأَرْضِ وَالطَّيْرُ صَافَّاتٍ ﴿كُلٌّ قَدْ عَلِمَ صَلَاتَهُ وَتَسْبِيحَهُ وَاللَّهُ عَلِيمٌ بِمَا يَفْعَلُونَ﴾ (41) [سورة النور: ٤١].","وقد جاء في الحديث الصحيح أن الشمس تجري حتى تنتهي إلى مستقرها تحت العرش، فتخر ساجدة لله عزوجل."],"40":["وقوله: ﴿هَذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ﴾"],"41":["قوله: ﴿يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِنْ ذَهَبٍ وَلُؤْلُؤًا﴾ أي يسورون في أيديهم رجالهم ونسائهم أساور الذهب واللؤلؤ، وقد جاء في الحديث:"],"43":["قوله: وَإِذْ بَوَّأْنَا لِإِبْرَاهِيمَ مَكَانَ الْبَيْتِ أي: أرشدناه إليه، وأسكناه عنده."],"44":["قوله: ﴿يَأْتُوكَ رِجَالًا وَعَلَى كُلِّ ضَامِرٍ﴾ أي ماشيا وراكبا من أنحاء المعمورة، وقد حجّ النبي صلى الله عليه وسلم من المدينة راكبا، وحج معه أناس ماشين."],"45":["وقوله: ﴿وَيَذْكُرُوا اسْمَ اللَّهِ فِي أَيَّامٍ مَعْلُومَاتٍ﴾ الأيام المعلومات أيام العشر من ذي الحجة. قاله ابن عباس وغيره."],"46":["قوله: ﴿وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ﴾ والمراد منه: طواف الإفاضة."],"49":["قوله: شَعَائِرَ اللَّهِ هي أعلام الدين الظاهرة التي تعبد الله الخلق بها، ومنها مناسك الحج والعمرة، فكل مايتعلق بها من الطواف بالبيت والسعي بين الصفا والمروة وسوق الهدي وغيرها من الأعمال والأحكام الواردة في الكتاب والسنة، من الإحرام إلى الإحلال، هذه كلها من الشعائر التي أمر الله بتعظيمها."],"50":["قوله: لَكُمْ فِيهَا مَنَافِعُ أي: لكم في البدن منافع من اللبن والركوب وغيرها، فقد جاء في الصحيح."],"51":["قوله: ﴿وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنْسَكًا﴾ أي كل أمة مؤمنة لهم منسك واحد فقط وهو ما ذكر في هذه السورة يعني الحج إلى بيت الله العتيق.","والمقصود من هذه الآية الكريمة الرد على المشركين الذين جعلوا لكل معبودهم مناسك، فيخرّون مرة للعزى، وأخرى للات، وثالثة لمعبود آخر إلى ما لا نهاية له.","فالتنكير في قوله تعالى: مَنْسَكًا للإفراد أي واحدا لا متعددا؛ لأن الله تعالى قال بعده: ﴿لِيَذْكُرُوا اسْمَ اللَّهِ عَلَى مَا رَزَقَهُمْ﴾ يبين هذا المعنى بأن يكون هذا المنسك لله عز وجل فقط."],"52":["قوله: ﴿فَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا صَوَافَّ﴾ الصواف: من الصف وهو أن تجعل الشيء على خط مستو، فتكون البدن مصطفة مربوطة القوائم ليسهل نحرها، وقد ثبت أن النبي صلى الله عليه وسلم نحر بيده ثلاثا وستين بدنة، جعل يطعنها بحربة في يده، ثم أعطى الحربة عليّا فنحر ما غبر، وكانت مائة بدنة، وهذا يقتضي أن تكون مصفوفة متقاربة."],"53":["فيه ردّ على ما يفعله المشركون أنهم إذا ذبحوا أو نحروا لطخوا الكعبة بدمائها قربةً إلى الله تعالى، وكذلك يشرحون لحوم الهدايا وينصبونها حول الكعبة فنفى الله ذلك وقال: ﴿وَلَكِنْ يَنَالُهُ التَّقْوَى مِنْكُمْ﴾ وجاء في الصحيح:"],"55":["أي: ما أرسل الله قبل النبي صلى الله عليه وسلم من رسول ولا نبي إلا إذا تلا كتاب الله، وقرأ أو حدّث وتكلم ألقى الشيطان في كتاب الله الذي تلاه وقرأه أو في حديثه الذي حدّث وتكلم، فيذهب الله ما يلقي الشيطان من ذلك ويزيله ويبطله، ويحكم آياته ويحفظها فتبقى خالصة من مخالطة إلقاء الشيطان.","وهذه من خصوصيات الأنبياء والمرسلين، فإن الشيطان لا ينجح في كيده لهم بالإلقاء فيما يتلون ويحدثون بخلاف غيرهم.","وأما ما ذكره كثير من المفسرين وغيرهم من قصة الغرانيق فهي غير صحيحة."],"56":["أي: أن علم الله محيط بكل ما في السموات والأرض، وأن ذلك كله مكتوب في كتاب عنده، كما جاء في الحديث."],"57":["أي: لو اجتمع جميع ما تعبدونه من دون الله عز وجل لن يقدروا أن يخلقوا ذبابا واحدا، بل لن يستطيعوا أن يخلقوا ذرة، كما جاء في الصحيح."],"58":["قوله: ﴿وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ﴾ أي أن الله عز وجل لم يكلف ما لا يطاق، بل جعل هذا الدين سهلا، خاليا من العسر والحرج والضيق والشدة."],"60":["قوله تعالى: ﴿الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ﴾ الخشوع هو الخضوع لله ويكون ذلك في حالة الصلاة وفي غيرها لأن محله القلب، وخصت الصلاة بالذكر لأن الشيطان يحاول يوسوس غالبا في الصلاة."],"61":["أي: الموصوفون بالصفات المذكورة هم الذين يدخلون الجنة، ويرثونها."],"64":["وقوله: سَبْعَ طَرَائِقَ أي: سبع سماوات، وهذا مثل قوله تعالى: ﴿أَلَمْ تَرَوْا كَيْفَ خَلَقَ اللَّهُ سَبْعَ سَمَاوَاتٍ﴾ طِبَاقًا [سورة نوح: ١٥]."],"65":["قوله: ﴿وَشَجَرَةً تَخْرُجُ مِنْ طُورِ سَيْنَا﴾ءَ أي: شجرة الزيتون، فإنها شجرة مباركة، يؤكل زيته، ويدّهن به، وقد جاء في الحديث."],"69":["أي: إن عاقبتهم بما تعدهم من العذاب، وإني شاهد ذلك، فلا تجعلني فيهم، وهذا كما جاء في الحديث الدعاء بالوفاة قبل الفتنة."],"71":["قوله: فَلَا أَنْسَابَ بَيْنَهُمْ أي: لا يتفاخرون بالأنساب يومئذ كما كانوا يتفاخرون في الدنيا، ولا يتساءلون سوال تواصل كما كانوا يتساءلون في الدنيا، من أنت ومن أيّ قبيلة أنت؟ ولم يرد أن الأسباب تنقطع. قاله البغوي.","فالأنساب لاتنتهي يوم القيامة، بل كل يدعون بأسمائهم وأسماء آبائهم. ولكنها لا تنفع في ذلك اليوم العظيم."],"74":["هذا الحكم في الزاني والزانية البكرين، وأما الثيب فقد دلت السنة على أن حده الرجم كما جاء في الصحيح:"],"83":["أي: أمر الله عباده المؤمنين ألا يدخلوا بيوتا غير بيوتهم إلا بعد الاستئذان، وقد جاء في بيان شرعية الإستئذان وآدابه أحاديث كثيرة، منها:"],"84":["قوله: ﴿قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ﴾ أي: أن الله أمر عباده بغض البصر وعدم النظر إلى المحارم، فإن وقع البصر على محرم من غير قصد، فيجب أن يصرفه عنه، كما جاء في الصحيح."],"85":["قوله: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ أي: أمر الله النساء المؤمنات بِغضِّ البصر عن نظرة الإعجاب والشهوة والفتنة دون نظر الحاجة والضرورة والرؤية العامة.","وأما ما روي عن أم سلمة قالت: كنت عند رسول الله صلى الله عليه وسلم، وعنده ميمونة، فأقبل ابن أم مكتوم، وذلك بعد أن أمرنا بالحجاب، فقال النبي صلى الله عليه وسلم: ((احتجبا منه)). فقلنا: يا رسول الله، أليس أعمى، لا يُبصِرنا، ولا يعرفنا؟ فقال النبي صلى الله عليه وسلم: ((أفعمياوان أنتما، ألستما تبصرانه؟)). فهو ضعيف.","رواه أبو داود (4112)، والترمذي (2778)، والنسائي في الكبرى (9197-9198)، وأحمد (26537)، وابن حبان (5576) كلهم من طريق الزهري، قال: حدثنى نبهان مولى أم سلمة، عن أم سلمة، قالت: فذكرته.","ونبهان مولى أم سلمة في عداد المجهولين، ولا يعلم له متابع. وقال أحمد: \"نبهان روي حديثين عجيبين\". وذكر هذا الحديث منهما.","وهو حديث مخالف لأحاديث أخرى صحيحة، منها حديث فاطمة بنت قيس عند مسلم (1480) أن النبي صلى الله عليه وسلم قال لها في حديث طويل: ((اعتدى عند ابن أم مكتوم فإنه رجل أعمى تضعين ثيابك فإذا حللت فآذنينى ...)). الحديث.","ولا يصح تخصيص هذا الحديث بأمهات المؤمنين؛ لأنهن أيضا كن ينظرن إلى الرجال عند الخروج من البيت، وفي المسجد، وفي السفر، والحج غيرها.","وقوله: ﴿وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ﴾"],"87":["قوله: ﴿وَلْيَسْتَعْفِفِ الَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِهِ﴾ أي: أمرهم الله تعالى بالتعفف والكف عن المحرم، وقد أرشدهم النبي صلى الله عليه وسلم إلى الصوم، كما جاء في الصحيح."],"88":["قوله: اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ الحسي والمعنوي.","وذلك أنه تعالى بذاته نور، وحجابه نور، وبه استنار العرش والكرسي، والشمس والقمر وغيرها. وكذلك النور المعنوي يرجع إلى الله، فكتابه نور، وشرعه نور، والإيمان والهدي والمعرفة في قلوب رسله وعباده المؤمنين نور، فلولا نوره لتراكمت الظلمات.","قاله الشيخ السعدي."],"89":["قوله: ﴿فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ﴾ أي: أمر الله ببناء المساجد ورفعها وعمارتها بذكرالله عزوجل والصلاة وقراءة القرآن فيها.","وقد جاء في ذلك أحاديث منها:"],"90":["قوله: ﴿أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ﴾ أي: أمر الله بطاعة الله وطاعة الرسول صلى الله عليه وسلم، وقد جاء في ذلك أحاديث كثيرة منها:"],"93":["قوله: ﴿وَإِذَا كَانُوا مَعَهُ عَلَى أَمْرٍ جَامِعٍ لَمْ يَذْهَبُوا حَتَّى يَسْتَأْذِنُوهُ﴾ أي: من آداب المجلس ألا يخرجوه منه إلا بعد الاستئذان.","ويكون ذلك بالسلام كما جاء في الحديث."],"94":["قوله: ﴿لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضًا﴾ فيه بيان للأدب مع الرسول صلى الله عليه وسلم إذا دعاه أحد فلا يقول: \" يا محمد \" إعظاماً له ولكن فخموه وشرّفوه وقولوا : يا رسول الله، يا نبي الله.","وله معنى آخر وهو: أن دعاءه على غيره ليس كدعاء أحدكم على أحدكم، لأنه مستجاب الدعاء فاحذروا أن يدعو عليكم. يعني احذروا الأسباب التي تقتضي أن يدعو عليكم.","وقوله: ﴿فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ﴾ يعني يخالفون ما أمر به فلا يأتمرون به بعد ما ثبت بإسناد صحيح في العقيدة والأحكام، وكذلك لا ينتهون عن نواهيه بعد ما تبين لهم.","قوله: أَنْ تُصِيبَهُمْ فِتْنَةٌ في الدنيا في المال والأولاد.","وقوله: ﴿أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيمٌ﴾ في الآخرة."],"96":["قوله: لِيَكُونَ لِلْعَالَمِينَ نَذِيرًا أي: النبي صلى الله عليه وسلم الذي أنزل عليه هذا القرآن نذير للعالمين كلهم، وهذا من خصائص النبي صلى الله عليه وسلم، كما جاء في الصحيح."],"97":["قوله: ﴿وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أي﴾: ابتلي الله الرسل بالناس، فأمرهم بدعوة الناس والصبر على ذلك، وكذلك ابتلي الناس بالرسل، فأمرهم بالإيمان بهم ليختبر المطيعين من العاصين، والمؤمنين من المكذبين."],"98":["أي: الملك الحق يوم القيامة يكون لله عزوجل فقط، ويومئذ تبطل ممالك ملوك الدنيا، ولا يبقى سوى ملكه عزوجل، وقد جاء في الصحيح."],"99":["يخبر الله تعالى عن رسول الله صلى الله عليه وسلم بأنه صلى الله عليه وسلم يشكو قومَه من الكفار إلى الله تعالى فيقول: ﴿وَقَالَ الرَّسُولُ يَا رَبِّ إِنَّ قَوْمِي اتَّخَذُوا هَذَا الْقُرْآنَ مَهْجُورًا﴾.","هجران الكفّار والمشركين أنهم هجروا القرآن، ولم يؤمنوا به، بل قد منعوا من استماع القرآن كما أخبر الله تعالى عنهم: ﴿وَقَالَ الَّذِينَ كَفَرُوا لَا تَسْمَعُوا لِهَذَا الْقُرْآنِ وَالْغَوْا فِيهِ لَعَلَّكُمْ تَغْلِبُونَ﴾[فصلت: ٢٦] فعزاه الله حبيبَه صلى الله عليه وسلم فقال: ﴿وَكَذَلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوًّا مِنَ الْمُجْرِمِينَ وَكَفَى بِرَبِّكَ هَادِيًا وَنَصِيرًا﴾ [الفرقان: ٣١]","يعني كما جعلنا لك أعداء من مشركي قومك، كذلك جعلنا لكل نبيّ عدوًّا من قومه، فاصبرْ كما صبروا، فإني ناصرُك وهاديك.","والمسلمون أيضا هجروا القرآن الكريم بعد النبي صلى الله عليه وسلم، وهجرانهم أنواع:","أحدها: هجرُ تلاوته، والقيامِ به آناء الليل أطراف النهار.","وثانيها: هجرُ العمل بالقرآن في الحلال والحرام.","وثالثها: هجرُ تحكيمه إليه في أصول الدين وفروعه، وقد قال تعالى: فَإِنْ تَنَازَ﴿عْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا﴾[النساء: ٥٩] والقرآن فيه حكم الله، وقد يكون هذا الحكم مجملا، فيفسّره الحديث.","ورابعها: ﴿هجرُ تدبّره وتفقّهه، وقد قال تعالى: كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ﴾ [سورة ص: ٢٩]","وقد قال بعضُ أهل العلم: التدبّر بالقرآن ساعةً خيرٌ من قيام الليل كلها، لأنّ القرآن رسالةٌ من الله تعالى إلى الإنس والجنّ، فيجب على المُرْسَلِ إليهم أن يتدبّروه ويفهموه، ثم يعملوا بما فيه.","وخامسها: هجرُ الاستشفاء والتداوي والرُّقْية به في أمراض القلوب والأبدان، وقد قال الله تعالى: ﴿وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِلْمُؤْمِنِينَ وَلَا يَزِيدُ الظَّالِمِينَ إِلَّا خَسَارًا﴾ [الإسراء: ٨٢]","وسادسها: هجرُ العبرة بقصص القرآن، وقد قال الله تعالى: ﴿لَقَدْ كَانَ فِي قَصَصِهِمْ عِبْرَةٌ لِأُولِي الْأَلْبَابِ﴾ [يوسف: ١١١] والقرآنُ كله حِكَم وموعظة، يتّعظ به العاقل دون غيره.","وإنْ كان بعضُ الهجرِ أهونُ من بعضٍ.","بعضُ هذه الفوائد ذكرها الحافظ ابنُ القيّم في الفوائد (1/82)","فقصرُ الهجرِ على قراءة القرآن فقط خطأٌ، لأنّ الله تعالى أنزلَ القرآنَ للعمل به، لا لمجرّد تلاوته، وإنْ كانتْ تلاوتُه لا تخلو من أجرٍ وثوابٍ، وأثرُ القرآن على القلوب يكون بمقدار طهارتها."],"102":["وقوله: ﴿فَأَبَى أَكْثَرُ النَّاسِ إِلَّا كُفُورًا﴾ أي: نسبوا نِعَم الله إلى غيره، فقالوا: مُطِرنا بنوء كذا وكذا، كما جاء في الصحيح."],"103":["أي: أنهم كانوا ينكرون أن يُسمَى الله باسمه الرحمن، كما أنكروا ذلك يوم الحديبية، وقد جاء في الصحيح."],"104":["أي: أن الله عزوجل جعلهما يتعاقبان. فمن فاته عمل في الليل فليستدركه في النهار، ومن فاته عمل في النهار فليستدركه في الليل، وقد جاء في الصحيح."],"105":["قوله: ﴿يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا﴾ أي: من غير استكبار ولا بطر، بل يمشون بالسكينة والوقار، هذا كما جاء في الصحيح."],"108":["أي: يكون خرورهم وسجودهم عند سماعهم لآيات الله مع العلم والبصيرة، ولا يكون خرورهم خرور الأصم والأعمى من غير فهم لها ولا تدبر فيها.","وقد سئل الشعبي، فقيل له: الرجل يرى القوم سجودا ولم يسمع ما سجدوا، أيسجد معهم؟. فتلا هذه الآية: ﴿وَالَّذِينَ إِذَا ذُكِّرُوا بِآيَاتِ رَبِّهِمْ لَمْ يَخِرُّوا عَلَيْهَا صُمًّا وَعُمْيَانًا﴾ يعني: أنه لا يسجد معهم؛ لأنه لم يتدبر آية السجدة.","وله وجه آخرمن التفسير، فقوله تعالى: ﴿لَمْ يَخِرُّوا عَلَيْهَا صُمًّا وَعُمْيَانًا أي: لم يكونوا مثل الكفار الذين أعمى الله بصيرتهم، وأصم آذانهم عن قبول الحق، بل المؤمنون يسارعون إلى التصديق والإيمان به كما قال الله تعالى: إِنَّمَا يُؤْمِنُ بِآيَاتِنَا الَّذِينَ إِذَا ذُكِّرُوا بِهَا خَرُّوا سُجَّدًا وَسَبَّحُوا بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ﴾ [سورة السجدة: ١٥]"],"110":["أي إن ربي لا يبالي بكم لولا دعاؤكم إياه دعاء العبادة والمسألة.","وقوله: فَقَدْ كَذَّبْتُمْ أيها الكافرون من أهل مكة، إن الله دعاكم إلى التوحيد وعبادته وحده فكذبتم الرسول الذي جاء إليكم بهذه الدعوة.","وقوله: لِزَامًا أي حصل لهم يوم بدر فقُتِلَ منهم سبعون وأُسِرَ سبعون، ويكون لهم عذاب الآخرة لزاما."],"112":["قوله: وَفَعَلْتَ فَعْلَتَكَ هو قتله القبطي من قوم فرعون.","وقوله: وَأَنْتَ مِنَ الْكَافِرِينَ أي الجاحدين لنعمتي وحق تربيتي في قصري لأن فرعون لم يكن يعرف ما الكفر بالله لأنه ادعى الربوبية والألوهية لنفسه، والمعنى الآخر: كنت كافرا بربوبيتي مع كل هذه النعم.","وقوله: ﴿قَالَ فَعَلْتُهَا إِذًا وَأَنَا مِنَ الضَّالِّينَ﴾ أي قال موسى: الذي فعلت حينئذ كان من غير قصد، وكنت مخطئا في هذا فإني لم أصبر على الخصومة التي وقعت بين القبطي وبين الرجل الذي كان من بني إسرائيل.","وقوله: ﴿وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَيَّ أَنْ عَبَّدْتَ بَنِي إِسْرَائِيلَ﴾ فيه إنكار من موسى عليه السلام على فرعون الذي يعُدُّ نعمته عليه، فقال له: لو لا عبدتَ بني إسرائيل وقتلت أولادهم ما كانت أمي ترميني في البحر؛ فإن الذي حصل هو من أجل استعبادك بني إسرائيل وقتلك أولادهم. فأي نعمة لك عليّ حتى تمنّها؛ لأن المقام مقام المناظرة، فلو اعترف موسى عليه السلام بالنعم التي يعدها فرعون لضعف موقفه، وأثّر ذلك في تبليغ رسالته؛ لأن فرعون قال بعد ذلك: وَمَا رَبُّ الْعَالَمِينَ (23) قَالَ رَبُّ السَّمَاوَاتِ ﴿وَالْأَرْضِ وَمَا بَيْنَهُمَا إِنْ كُنْتُمْ مُوقِنِينَ﴾ (24) [الشعراء: ٢٣ – ٢٤]","واستمرت هذه المناظرة، وما حدثَ بعد خروج موسى مع بني إسرائيل من مصر من الحوادث من غرق فرعون وجنوده، ثم وصول موسى مع بين إسرائيل إلى أرض سيناء إلى الآيات رقم (68)."],"113":["أي: أن الله تعالى أخرج فرعون وجنوده مما كانوا فيه من النعيم والخيرات، وأعطى الله بني إسرائيل خيرات مثلها لم تكن لهم من قبل في مصر، فأورثهم أرض الشام المباركة، قال تعالى: ﴿وَأَوْرَثْنَا الْقَوْمَ الَّذِينَ كَانُوا يُسْتَضْعَفُونَ مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا الَّتِي بَارَكْنَا فِيهَا وَتَمَّتْ كَلِمَتُ رَبِّكَ الْحُسْنَى عَلَى بَنِي إِسْرَائِيلَ بِمَا صَبَرُوا وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُ وَمَا كَانُوا يَعْرِشُونَ﴾ [سورة الأعراف: ١٣٧].","وليس المراد أن بني إسرائيل أعطوا ما كان بيد فرعون وقومه من الجنات والعيون والكنوز؛ لأن بني إسرائيل بعد خروجهم من مصر لم يرجعوا إليها أبدا.","وكذلك يدل عليه قوله تعالى: كَذَلِكَ وَأَوْرَثْنَاهَا قَوْمًا آخَرِينَ [سورة الدخان: ٢٨] قوما آخرين أي من أهل مصر، وقد يكون هذا القوم من غير آل فرعون الّذي غرق."],"114":["أي: نجّى الله موسى عليه السلام ومن معه، وأهلك فرعون ومن معه، وكان ذلك يوم عاشوراء، كما جاء في الصحيح."],"115":["قوله: وَأَلْحِقْنِي بِالصَّالِحِينَ أي: اجعلني مع الصالحين، وقد جاء في الحديث أيضا الدعاء بلحوق الصالحين."],"117":["أي: لما جاء هم عذاب الله الذي كانوا يوعدون عند تمردهم وعصيانهم لم تغن أموالهم وأولادهم وغيرها من النعم عنهم شيئا، وهذا كقوله تعالى: ﴿وَمَا يُغْنِي عَنْهُ مَالُهُ إِذَا تَرَدَّى﴾ [سورة الليل: ١١]، وقوله تعالى: ﴿مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ﴾[سورة المسد: ٢]. وقد جاء في الصحيح:"],"118":["قوله: ﴿إِنَّهُمْ عَنِ السَّمْعِ لَمَعْزُولُونَ﴾ أي: الشياطين كانوا بمعزل عن استماع القرآن حال نزوله؛ لأن السماء كانت ملئت بالشهب والحرس الشديد مدة نزول القرآن."],"123":["قوله: وَوَرِثَ سُلَيْمَانُ دَاوُودَ أي: خلفه الله عز وجل في النبوة والحكم، وليس المراد وراثة الأموال والأملاك، فإن الأنبياء لا تورث أموالهم كما جاء في الصحيح:"],"124":["قوله: فَإِنَّ رَبِّي غَنِيٌّ كَرِيمٌ فهو سبحانه غني عن العباد كلهم، وليس مفتقرا إليهم في شيء، والخلق كلهم يحتاجون إليه، وقد جاء في الصحيح:"],"126":["ذكر الله المشركين الشاكّين في البعث وقيام الساعة من باب التنديد وإلا فالناس كلهم عاجزون عن معرفة ذلك كما جاء في الصحيح:"],"127":["وكذلك قوله تعالى في سورة الروم: ﴿فَإِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ﴾","وكذلك قوله تعالى في سورة فاطر: ﴿وَمَا يَسْتَوِي الْأَحْيَاءُ وَلَا الْأَمْوَاتُ إِنَّ اللَّهَ يُسْمِعُ مَنْ يَشَاءُ وَمَا أَنْتَ بِمُسْمِعٍ مَنْ فِي الْقُبُورِ﴾","ظاهر الآيات تدُلُّ على أن الموتى لا يسمعون، ومن لا يسمع لا ينفع.","ولكنْ كيف نجمع بين هذه الآيات وبين الأحاديث الواردة في سماع الموتى.","ومن هذه الأحاديث:"],"128":["هذه الدابة تخرج في آخر الزمان، وهي من أشراط الساعة كما جاء في الصحيح:"],"129":["قوله: ﴿وَيَوْمَ يُنْفَخُ فِي الصُّورِ﴾: الصور هو القرن كما جاء في الحديث الصحيح:"],"130":["قوله: ﴿هَذِهِ الْبَلْدَةِ الَّذِي حَرَّمَهَا﴾ هي مكة كما جاء في الصحيح:"],"132":["قوله: وَأَبُونَا شَيْخٌ كَبِيرٌ اختلفوا في اسم هذا الشيخ الكبير، فذهب كثير من المفسرين إلى أنه شعيب النبي صلى الله عليه وسلم.","وقال الآخرون: هو شيخ صالح آخر، وإلى هذا القول ذهب ابن عباس، وقتادة، وأبو عبيدة، والحسن البصري في أحد قوليه. وأما شعيب فكان قبل زمان موسى بمدة، لأنه قال لقومه: ﴿وَمَا قَوْمُ لُوطٍ مِنْكُمْ بِبَعِيدٍ وكان﴾ هلاك قوم لوط في زمن الخليل عليه السلام، وبين موسى والخليل عليهما السلام مدة طويلة تزيد على أربعمائة سنة.","لأن شعيبا عليه السلام من الجيل الخامس من الخليل إذ هو شعيب بن فلان بن فلان بن مدين بن إبراهيم، وموسى عليه السلام من الجيل السابع، إذْ هو موسى بن عمران بن قاهت بن لاوي بن يعقوب بن إسحاق بن إبراهيم. ثم إن شعيبا لم يبق في مدين بعد أن أصابتْهم الصيحة قال الله تعالى: ﴿وَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا شُعَيْبًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَةٍ مِنَّا وَأَخَذَتِ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ﴾ جَاثِمِينَ [هود: ٩٤]","وفي كتب التاريخ أن شعيبا خرج إلى اليمن، وتوفي في حضرموت، وفيها قبر يقال: إنه قبر شعيب والله أعلم بالصواب. ثم لو كان هو شعيب لنصَّ في القرآن ههنا، وعاش معه موسى عليه السلام عشر سنين، ولم يُنقل شيء من علمه من الوحي وعلم النبوة، فالظاهر أنه رجل صالح لعله من أتباع شعيب عليه السلام من الجيل الجديد."],"133":["لم يَرِدْ تعيين إحدى الابنتين هل تزوج الكبرى أم الصغرى، وأما المدة التي قضاها موسى فهي أكثرها كما جاء في الصحيح:"],"134":["قوله تعالى فَأَوْقِدْ لِي يَا هَامَانُ عَلَى الطِّينِ","إن علماء الآثار منذ آلاف السنين متحيرون في بناء أهرامات مصر، التي يبلغ ارتفاعها نحو 146 متراً، وأبدوا الاستحالةَ في رفع الأحجار التي وزنها يزيدُ أكثر من خمسة طن (5000 كيلو جرام) إلى هذا الارتفاع، ووضعها منسّقًا، فلما أخذوا العينات من الأحجار، وذهبوا بها إلى الولايات المتحدة، وحلَّلوها، فوجدوا أنها ليستْ من الأحجار الصخرية الجبلية، وإنما هي تُرابٌ وماءٌ، أُسخنتْ بدرجة معينة، فصارتْ كالصخر في الظاهر.","وعلى هذا فِإنهم حوَّضوا في كل طبقة حوضا، ثم وضعوا فيه التراب والماء، وسخّنوها بدرجة معينة، فصارت كالصخرة، هكذا بَنَوْا الأهرامَ إلى أعلاها.","فلما قرأتُ هذا الخبر قلتُ: سبحانَ اللهِ ما كشفَه علماءُ الآثار اليوم بعد تحليلات دقيقة كشفها القرآنُ قبل ألف وأربعمائة سنة في قوله: فَأَوْقِدْ لِي يَا هَامَانُ ﴿عَلَى الطِّينِ فَاجْعَلْ لِي صَرْحًا﴾ وهذا يدلُّ أيضا على تاريخ بناء أهرامات الذي لا يزال مجهولاً، فإنه يرجع إلى عهود بني إسرائيل في مصر في عهد موسى عليه السلام، وإنْ كانَ بعض الأهرامات قد بُنِيَتْ من قبلُ. وقوله: صَرْحًا لعله أراد به الأهرام الموجودة الآن، لأنه لا يوجد من آثار فرعون غير هذا."],"135":["قوله: ﴿وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ مِنْ بَعْدِ مَا أَهْلَكْنَا الْقُرُونَ الْأُولَى﴾ أي: أن الله عز وجل بعد إنزال التوراة لم يعذب قوما بعامّة."],"137":["في الآية الكريمة دليل على أن الهداية بيد الله سبحانه وحده، وقد جاء في الصحيح أن النبي صلى الله عليه وسلم أحبّ أن يُسلم عمُّه أبو طالب، ولكنه لم يُسلم."],"139":["قارون كان ابن عم موسى عليه السلام، وهو: قارون بن بصهار بن قهات بن لاوي بن يعقوب. وموسى هو: ابن عمران بن قهات بن لاوي بن يعقوب.","وقارون بالعبرية \"قورح\" تمَّ تغييرُ بعض حروفه للتخفيف على وزن طالوت وجالوت. وجاء ذكره في سفر العدد – الإصحاح السادس عشر-. والغالب أن قصته وقعت على أبواب أريحا قبل فتحها لأن فتحها كان بعد موت موسى عليه السلام.","قال بعض المفسرين: إن فرعون جعل قارون رئيسا على بني إسرائيل للاستخبار، فجمع أموالا كثيرة كما ذكر في القرآن الكريم فخسف اللهُ به وبداره الأرض.","وفي الإصحاح (31-35) المشار إليه: \"انشقت الأرض التي تحتهم، وفتحت الأرض فاها وابتلعتهم وبيوتهم، وكُلّ من كان لقورح مع كل الأموال، فنزلوهم وكلّ ما كان لهم أحياء إلى الهاوية، وانطبقت عليهم الأرض، فبادوا من بين الجماعة، وكلُّ إسرائيل الذين حولهم هربوا من صوتهم؛ لأنهم قالوا: لعل الأرض تبتلعُنا، وخرجتْ نارٌ من عند الرب وأكلت المئتين والخمسين رجلا الذين قربوا البخور\".","وقوله: ﴿إِنَّ مَفَاتِحَهُ لَتَنُوءُ بِالْعُصْبَةِ أُولِي الْقُوَّةِ أي﴾ لتثقلهم، وتميل بهم إذا حملوها لثقلها وما ذكره المفسرون من عدد المفاتيح ووزنها، فلم يثبت فيه شيء مرفوع."],"140":["قوله: ﴿وَابْتَغِ فِيمَا آتَاكَ اللَّهُ الدَّارَ الْآخِرَةَ وَلَا تَنْسَ نَصِيبَكَ مِنَ الدُّنْيَا﴾ أي أنفقْ لآخرتك واستمتعْ في دنياك بحيث لا يثلم دينك ولا يضر آخرتك، وأعط كل ذي حق حقه، وقد جاء في الصحيح:"],"141":["وقد صحّ:"],"143":["قوله: ﴿لَا يُرِيدُونَ عُلُوًّا فِي الْأَرْضِ﴾ أي: إنهم لا يريدون الفخر والتطاول على غيرهم فإنه مذموم، وقد جاء في الصحيح:"],"144":["قوله: فَرَضَ عَلَيْكَ أي أنزل عليك.","وقوله: لَرَادُّكَ إِلَى مَعَادٍ معاد هو اسم مكان العود.","وفيه إشارة إلى خروجه صلى الله عليه وسلم من مكة، ثم العودة إليها، وقد أخبر ورقة بن نوفل إن قومك يُخرجك، فتعجب النبي صلى الله عليه وسلم من هذا.","والآن يخبر الله تعالى بأنه سيعود من حيث خرج، وتحقق ذلك بدخوله صلى الله عليه وسلم فاتحا مكة، قال ابن عباس: عودته إلى مكة كما جاء في الصحيح:"],"145":["ظاهر الخطاب للنبي صلى الله عليه وسلم ولكن المراد به أهل بلده من المشركين والكفار الذين كانوا معترفين بربوبية الله سبحانه وتعالى ولكنهم كانوا يشركونه في ألوهيته.","وقوله: ﴿كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ﴾ إخبار بأنه الدائم الباقي الحي القيوم الذي لايموت، كما قال تعالى: ﴿كُلُّ مَنْ عَلَيْهَا فَانٍ وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ فعبَّر﴾ بالوجه عن الذات.","وقد ثبت في الصحيحين البخاري (3841) ومسلم (2256) عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم : \" أصدق كلمة قالها شاعر كلمة لبيد:","أَلَا كُلُّ شَيْءٍ ما خَلَا اللهَ بَاطِلُ"],"147":["قال الشعبي: إنها نزلت –يعني: ﴿الم أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا الآيتين﴾ في أناس كانوا بمكة أقروا بالإسلام، فكتب إليهم أصحاب رسول الله صلى الله عليه وسلم من المدينة: إنه لا يقبل منكم إقرار بالإسلام حتى تهاجروا، فخرجوا عامدين إلى المدينة، فاتبعهم المشركون فردوهم، فنزلت فيهم هذه الآية، فكتبوا إليهم: إنه قد نزلت فيكم آية كذا وكذا، فقالوا: نخرج، فإن اتبعنا أحد قاتلناه؛ قال: فخرجوا فاتبعهم المشركون فقاتلوهم ثَمَّ، فمنهم من قتل، ومنهم من نجا، فأنزل الله فيهم: ﴿ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُوا مِنْ بَعْدِ مَا فُتِنُوا ثُمَّ جَاهَدُوا وَصَبَرُوا إِنَّ رَبَّكَ مِنْ بَعْدِهَا لَغَفُورٌ رَحِيمٌ﴾ [النحل: ١١٠].","رواه الطبري في تفسيره (18/358)، والواحدي في أسباب النزول (ص 355).","وقال مقاتل: نزلت في مهجع مولى عمر بن الخطاب كان أول قتيل من المسلمين يوم بدر، رماه عمرو بن الحضرمي بسهمٍ فقتله، فقال النبي صلى الله عليه وسلم يومئذ: سيد الشهداء مهجع، وهو أول من يُدعى إلى باب الجنة من هذه الأمة فجزع عليه أبواه وامرأته، فأنزل الله تعالى هذه الآية، وأخبرهم أنه لا بد لهم من البلاء والمشقة في ذات الله. ذكره الواحدي واللفظ له. وقيل: نزلت في عمار بن ياسر إذ كان يُعذّب في الله، وقيل غير ذلك إلا أنه لم يثبت بإسناد صحيح."],"150":["أي أنهم يحملون أوزار أنفسهم، ويحملون أوزار الذين ضلّوا بسببهم، فهم يحملون أوزار الضلال وأوزار الإضلال وقد جاء في الصحيح:"],"151":["هذا إخبار من الله تعالى لنبيه تطييبا له لما يلقاه من قومه من الأذى بأن يصبر على ذلك، لأن الله تعالى أرسل نوحا إلى قومه، فلبثَ فيهم ألف سنة إلا خمسين عاما يدعوهم إلى التوحيد وفراق الآلهة والأوثان ولكنهم لم يقبلوا دعوته، بل تمردوا عليه.","وقوله: ﴿أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًا﴾ الظاهر من الآية الكريمة أن هذه المدة مدة رسالته إلى قومه، لأن هذا هو المقصود، وأما كم كان عمره لما بُعث، ثم كم لبث في الأرض بعد الطوفان فلم يتعرض له في القرآن، ولا جاء ذكره في السنة الصحيحة، وإنما فيه أقوال المفسرين، ذكر بعضها ابن جرير في تفسيره، ولم يثبت فيه شيء مرفوع."],"152":["أي: أن الله عز وجل يعذب من يشاء من خلقه وهو غير ظالم لهم البتة، ويرحم من يشاء من خلقه كرمًا منه وفضلا وقد جاء في الحديث:"],"153":["قوله: ﴿وَقَالَ إِنِّي مُهَاجِرٌ إِلَى رَبِّي﴾ فهاجر إبراهيم عليه السلام من وطنه وأرض مولده وهي العراق إلى الشام، وكان معه لوط عليه السلام أيضا وهو ابن أخيه، وهي أول هجرة في التاريخ من أجل الدين لقوله: مُهَاجِرٌ إِلَى رَبِّي وآخرها هجرة نبينا صلى الله عليه وسلم ولم يسجّل التاريخ غير هاتين الهجرتين من أجل الدين لأحد من الأنبياء."],"154":["قوله: الْفَاحِشَةَ أي الأعمال القبيحة منها: إتيان الرجال كما في قوله: ﴿أَئِنَّكُمْ لَتَأْتُونَ الرِّجَالَ. وقوله: وَتَقْطَعُونَ السَّبِيلَ وذلك﴾ أنهم كانوا يفعلون الفاحشة بمن مرّ بهم من المسافرين، فترك الناس المرور بهم. ويحمل أيضا على قطع النسل بإيثار الرجال على النساء. وقوله: ﴿وَتَأْتُونَ فِي نَادِيكُمُ الْمُنْكَرَ﴾ النادي هو المكان الذي يجتمع فيه الناس نهارا وهو مشتق من الندو، والاجتماع نهارا، وأما مكان الاجتماع ليلا فهو السامر، ثم غلب النادي على جميع الاجتماعات سواء كان نهارا أو ليلا.","وقوله: الْمُنْكَرَ وهو كلمة شاملة لجميع الأعمال القبيحة قولا وفعلا.","وأما ما روي عن أم هانئ قالت: سألت رسول الله صلى الله عليه وسلم عن قوله: ﴿وَتَأْتُونَ فِي نَادِيكُمُ الْمُنْكَرَ﴾ قال: ((كانوا يخذفون أهل الطريق ويسخرون منهم فذاك المنكر الذي كانوا يأتون)) فهو ضعيف. رواه الترمذي (3190)، وأحمد (26891)، والحاكم (2/209) كلهم من طريق حماد بن أسامة، قال: أخبرني حاتم بن أبي صغيرة قال: حدثنا سماك بن حرب، عن أبي صالح مولى أم هانئ، عن أم هانئ فذكرته.","وإسناده ضعيف من أجل أبي صالح واسمه باذام- بالذال- قال النسائي: ليس بثقة، وقال الحاكم: ليس بالقوي، وقال أبو حاتم: يكتب حديثه، ولا يحتج به. وقول الحاكم: \"صحيح على شرط مسلم\". ليس بصحيح، بل هو من رجال السنن فقط."],"155":["قوله: إِنَّا مُهْلِكُو أَهْلِ هَذِهِ الْقَرْيَةِ: فيه إشارة إلى قرية لوط عليه السلام التي كانت واقعة في مكان سهل في الجنوب الشرقي من جبال حبرون أي مدينة الخليل اليوم، وكانت تسمى سدوم."],"156":["قوله: ﴿فَمِنْهُمْ مَنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًا﴾ هم عاد قوم هود عليه السلام. والحاصب هو: الريح الشديدة، وسميت حاصبا لأنها تقلع الحصباء من الأرض.","وقوله: ﴿وَمِنْهُمْ مَنْ أَخَذَتْهُ الصَّيْحَةُ﴾ هم ثمود قوم صالح عليه السلام.","وقوله: ﴿وَمِنْهُمْ مَنْ خَسَفْنَا بِهِ الْأَرْضَ﴾ هو قارون وأصحابه.","وقوله: وَمِنْهُمْ مَنْ أَغْرَقْنَا هو فرعون وجنوده.","وقوله: ﴿وَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ﴾ أي أن الله نفى الظلم عن نفسه لأنه يوصف بالعدل في جميع أعماله. وقوله: ﴿وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ﴾ أي أنهم اختاروا طريق الظلم الذي أدّاهم إلى هلاكهم."],"158":["قوله: بِالَّتِي هِيَ أَحْسَنُ فيه حثّ على تعلّم ما عليه أهل الكتاب لمن نصب نفسه للمناقشة والمناظرة معهم ليكون جدالهم جدالا حسنا ومثمرا على علم وبينة.","قوله: ﴿وَقُولُوا آمَنَّا بِالَّذِي أُنْزِلَ إِلَيْنَا وَأُنْزِلَ إِلَيْكُمْ﴾"],"159":["فيه تاكيد على أمية النبي صلى الله عليه وسلم، وأن ما جاء به من الكتاب -وهو القرآن- لمن أعظم المعجزات، لأنه لم يكن يقرأ كتابا حتى يقول أحد: إن ما جاء كان من قبل. وما كان يكتب كتابا حتى يقول أحد: إنه نسخه من كتب الأولين، ونفي الأمرين –يعني الكتابة والقراءة- يؤكد على أميته صلى الله عليه وسلم.","قوله: الْمُبْطِلُونَ أي كفار مكة، وُصِفَ المكذبون بالمبطلين لأنهم كذّبوا مع انتفاء شبهة الكذب، فكان تكذيبهم باطلا."],"160":["أي هذا القرآن آيات واضحة وهو محفوظ في صدور العلماء، والله عزوجل قد يسّر عليهم تلاوته وحفظه وتفسيره وقد جاء في الصحيح:"],"161":["أي أن هذا القرآن الذي أنزل على النبي صلى الله عليه وسلم وهو يتلوه عليهم مع كونه أمّيا لا يقرأ و لايكتب لآية عظيمة، بل هو أعظم الآيات التي أوتيها النبي صلى الله عليه وسلم كما جاء في الصحيح:"],"163":["من عادة الكفار والمشركين إذا أصابتهم الضراءُ دعوا الله مخلصين له الدين، وإذا أصابتهم السراء نسوه ودعوه شركاءهم من أوثان.","ذكر محمد بن إسحاق، عن عكرمة بن أبي جهل: أنه لما فتح رسول الله صلى الله عليه وسلم مكة ذهب فارًّا منها، فلما ركب في البحر ليذهب إلى الحبشة، اضطربت بهم السفينة، فقال أهلها: يا قوم، أخلصوا لربكم الدعاء، فإنه لا ينجي ههنا إلا هو، فقال عكرمة: والله إن كان لا ينجي في البحر غيره فإنه لا ينجي غيره في البر أيضًا، اللهم لك عليَّ عهد لئن خرجت لأذهبن فلأضعنَّ يدي في يد محمد فلأجدنه رؤوفا رحيما، وكان كذلك.","ذكره ابن كثير في تفسيره."],"165":["قوله: غُلِبَتِ الرُّومُ المراد بالروم أمة مختلطة من اليونانيين واللاطنيين من سكان إيطاليا، وتسمى دولتهم البيزنطية وكان مقرّها الشام، وهي تابعة للإمبراطورية العظمى الرومية وكان مقرها قسطنطينية، وكان هولاء من أهل الكتاب، وكان الفرسُ عُبّادَ الأوثان، فلما غلبَ الفرسُ على الروم، فرح أهلُ مكة لأنهم كانوا مشركين، فحزن المسلمون فبشّرهم الله تعالى بقوله: ﴿وَهُمْ مِنْ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ فِي بِضْعِ سِنِينَ﴾","قوله: فِي أَدْنَى الْأَرْضِ أي أقرب أرض الشام إلى أرض فارس."],"166":["فيه إرشاد من الله عز وجل لعباده إلى تسبيحه وتحميده والمداومة على ذكره تعالى، وقد جاء في الصحيح:"],"167":["أي أن الذي خلقه أولا فإنه لأقدر أن يعيده ثانيا كما جاء في الصحيح."],"169":["أهل الاديان السابقة كلهم اختلفوا فيما بينهم وصاروا فرقا وأحزابا، لكل واحدة منها أهواء وآراء باطلة، وهذه الأمة أيضا حصل فيها الخلاف والفرقة ولكنها معصومة من الاجتماع على الباطل، ولا تزال فيها طائفة ظاهرة على الحق إلى يوم القيامة وهم أهل السنة."],"170":["أي الناس في حال الضر والضيق يدعون الله عز وجل، ولكنهم في حال السعة وحصول النعمة يكفرون بها، وهذه حال عامة الناس، ولا يستثنى من ذلك إلا المؤمنون، الذين يشكرون في السراء ويصبرون في الضراء كما جاء في الصحيح:"],"171":["قوله: مِنْ رِبًا أي الربا في ظاهرها الزيادة وفي الحقيقة هي ماحقةٌ كما قال تعالى: ﴿يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ وَاللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ﴾[البقرة: ٢٧٦]","أي أن البركة ترتفع من الأموال الربوية لأن المعاملة الربوية تنافي المواساة، وقد أدرك الاقتصاديون بعد دراسات تفصيلية أن الفقر الخطير الذي يواجه الإنسان سببه المعاملة الربوية في البنوك والمؤسسات المالية.","قوله: ﴿وَمَا آتَيْتُمْ مِنْ زَكَاةٍ تُرِيدُونَ وَجْهَ اللَّهِ فَأُولَئِكَ هُمُ الْمُضْعِفُونَ أي﴾ أن الله عزوجل يضاعف في ثواب الصدقة التي أريد بها وجه الله عز وجل، وقد جاء في الصحيح:"],"172":["المراد بالفساد- الشرك بالله تعالى.","وقوله: ﴿بِمَا كَسَبَتْ أَيْدِي النَّاسِ﴾ أي من أعمالهم الكفرية والشركية، وأعمالهم الفاسدة والمفسدة، ونتيجةً لذلك أذاقهم الله من الآفات الدنيوية وعذاب الآخرة.","وقوله: وَالْبَحْرِ لعل المراد منه الجزر الواقعة في وسط البحار والمأهولة منها، مثل البر في انتشار الشرك وعبادة الأوثان.","أو يكون المراد من فساد البر والبحر سوء حالهم وهو ضد الصلاح والفلاح، وذلك جزاء بأعمالهم كما جاء في سورة الشورى [30]: وَمَا أَصَابَ﴿كُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَنْ كَثِيرٍ﴾ (30)"],"173":["لأن الله بعث لكل قوم هاد لإقامة الحجة عليهم، فمنهم من آمن بهم، ومنهم من كفر بهم، وأنت يا محمد (رسول الله) لا تحزن من قومك الذين كفروا بك وآذوك، فإنا سوف ننتقم منهم، وقد حصل هذا في غزوة بدرقتل فيها صناديد قريش الذين آذوه في مكة.","قوله: ﴿وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ﴾ يعني أن الله سبحانه وتعالى أوجب على نفسه تكرما وتفضلا نصر المؤمنين في الدنيا بالتمكين، وفي الآخرة بإدخالهم الجنة، فالنصر حاصل في كل حال للمؤمنين."],"175":["قوله: وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ","لقمان اسم رجل صالح حكيم، واشتهر في بلاد العرب والفرس بالحكمة في أقواله وأفعاله، واختلف في أصله فقيل: إنه رجل من أهل الشام كان في عهد داود عليه السلام، وكان قاضيا في بني إسرائيل، وهو من نسل إبراهيم عليه السلام.","وقيل: إنه رجل أسود من سودان مصر وقيل: من الحبشة.","ومن الصعب ترجيح أحد القولين على الآخر.","كما اختلف أهل العلم في كونه حكيما أو نبيا فقال جمهور أهل العلم: إنه كان حكيما لا نبيا لأن القرآن الكريم لم يُشِرْ إلى نبوته.","وكانت حكمتُه معروفة لدى العرب.","فقد ذكر القرطبي في تفسيره (14/61) قول وهب بن منبه: \"قرأت من حكمة لقمان أرجح من عشرة آلاف باب\".","فإن صحّ هذا النقل من وهب بن منبه فيُحمل قوله هذا على المبالغة إذ لايوجد من أقواله وحكمه في القرآن الكريم وفي كتب الحديث والتفاسر والسير والتاريخ أزيد من مائة حكمة. منها ما ذكر في القرآن الكريم.","ومنها: ما ذكره مالك في الموطأ في كتاب الكلام (17) قال: بلغني أنه قيل للقمان: ما بلغ بك ما ترى؟ يريدون الفضل، فقال: صدقُ الحديث، وأداء الأمانة، وترك ما لا يعنيني.","وذكر أيضا في كتاب العلم (1) قال: بلغني أن لقمان الحكيم أوصى ابنه فقال: يا بنيّ: جالسِ العلماء، وزاحمْهم بركبتك، فإن الله يُحيي القلوب بنور الحكمة كما يحيي الله الأرض الميتة بوابل السماء.","ومن حكمه كما ذكره أهل التفسير قوله: يا بني إياك والدَّيْن فإنه ذلّ النهار وهمُّ الليل.","وقوله: من كذبَ ذهبَ ماءُ وجهه، ومن ساء خلقُه كثرَ غمّه.","وقوله: نقل الصخور من مواضعها أيسرُ مِنْ إفهامِ مَنْ لا يفهم.","وقوله: يا بني احضر الجنائزَ، ولا تحضر العرسَ فإن الجنائز تذكّرك الآخرة، والعرس يشهيك الدنيا.","وقوله: يا بني لا تأكل شبعا على شبع فإن إلقاءك إياه للكلب خير من أن تأكله.","وقوله: يا بني لا تكن حلوا فتُبلع، ولا تكن مرًّا فتُلفظ.","وقوله لابنه: لا يأكل طعامك إلا الأتقياء، وشاورْ في أمرك العلماء.","وقوله: يا بني إذا أردتَ أن تواخي رجلا فأغضبه قبل ذلك، فإنْ أنصفك عند غضبه وإلا فاحذرْه.","وقوله: يا بني لا تجالس الفجار، ولا تماشهم، اتق أن ينزل عليهم عذاب من السماء فيصيبك معهم.","وقال: يا بني: جالس العلماء وماشهم عسى أن تنزل عليهم رحمةٌ فتصيبهم معهم.","وقيل: إن لقمان كان يفتي قبل مبعث داود، فلما بعث داود قطع الفتوى، فقيل له: فقال: ألا أكتفي إذا كُفِيْتُ.","وقوله: يا بني إذا امتلأت المعدةُ نامت الفكرةُ وخرست الحكمةُ، وقعدت الأعضاء عن العبادة.","وذكرت أقواله الأخرى في كتب التفسير والتاريخ، ولم أقف على مصنف خاص جمع فيه حكمه ومواعظه، فيا ليت أحدٌ قام بهذا العمل.","ومِنْ حِكَمه ما جاء ذكرُه في حديث ابن عمر:"],"176":["ولهاتين الآيتين سبب نزول وقد ذكر في سورة العنكبوت الآية (8)، وفيهما أمر بالبر بالوالدين وحثٌّ على طاعتهما ولكنْ لا طاعة لهما في معصية الله تعالى والإشراك به سبحانه وتعالى، ومن الأحاديث الدالة على البر بالوالدين ما يلي:"],"177":["روي عن أبي سعيد الخدري عن رسول الله صلى الله عليه وسلم قال: ((لو أن أحدكم يعمل في صخرة صمّاء ليس لها باب و لا كُوّة لخرج عملُه للناس كائنا من كان)).","رواه أحمد (11230/1) –واللفظ له- وأبو يعلى (1378)، وابن حبان (5678) كلهم من طريق درّاج، عن أبي الهيثم، عن أبي سعيد الخدري فذكره.","ودرّاج وهو ابن سمعان أبو السمح وهو ضعيف في أبي الهيثم، وهذه منها."],"178":["أي أمره بإقامة الصلاة والأمر بالمعروف والنهي عن المنكر والصبر على ما يصيبه في سبيل الدعوة، وأكثر من يصيب البلاء في ذلك هم الأنبياء، ثم الأمثل فالأمثل، كما جاء في الحديث:"],"179":["أي نهى الله عز وجل عن الكبر والاستعلاء، وأمر بالتواضع، وقد جاء في الحديث:"],"183":["قوله: يُدَبِّرُ الْأَمْرَ أي يحكم الأمر وينزل القضاء والقدر من السماء إلى الأرض.","وقوله: ثُمَّ يَعْرُجُ أي جبريل يصعد إلى السماء.","وقوله: ﴿فِي يَوْمٍ كَانَ مِقْدَارُهُ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ﴾ أي في يوم واحد من أيام الدنيا، وقدرُه مسيرة ألف سنة. وأما قوله تعالى: ﴿تَعْرُجُ الْمَلَائِكَةُ وَالرُّوحُ إِلَيْهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ﴾ [المعارج: ٤] أراد مدة المسافة بين الأرض وسدرة المنتهى التي هي مقام جبريل، يسير جبريل والملائكة الذين معه من أهل مقامه مسيرة خمسين ألف سنة في يوم واحد من أيام الدنيا.","هذا كله معنى قول مجاهد والضحاك كما قال البغوي في تفسيره (3/518)."],"184":["قوله: ﴿تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ﴾ المضاجع جمع مضجع وهو الذي يضطجع عليه يعني الفراش. وأشهر أقوال أهل العلم أن المراد منه صلاة الليل كما جاء في الحديث:"],"187":["قوله: ﴿فَلَا تَكُنْ فِي مِرْيَةٍ مِنْ لِقَائِهِ﴾ يعني أنك رأيته ليلة الإسراء.","وقوله: وَجَعَلْنَاهُ هُدًى لِبَنِي إِسْرَائِيلَ يعني الكتاب الذي آتيناه موسى فيه هدى لبني إسرائيل فقط، وليس لجميع الناس، وكذلك عيسى عليه السلام الذي كان آخر أنبياء بني إسرائيل كانت دعوته أيضا لبني إسرائيل فحسب، ثم جاء آخر الأنبياء والمرسلين محمد رسول اللهصلى الله عليه وسلم وكانت دعوته للناس أجمعين."],"189":["قوله: ﴿مَا جَعَلَ اللَّهُ لِرَجُلٍ مِنْ قَلْبَيْنِ فِي جَوْفِهِ﴾ النفي هنا بمعنى النهي أي لا ينبغي للمؤمن أن يكون عنده قلبان، قلب فيه إيمان وتوحيد وإخلاص، وقلب فيه كفر وشرك ونفاق، بل يكون خالصا في إيمانه وتوحيده قال تعالى: ﴿لَا تَجِدُ قَوْمًا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ يُوَادُّونَ مَنْ حَادَّ اللَّهَ وَرَسُولَهُ وَلَوْ كَانُوا آبَاءَهُمْ أَوْ أَبْنَاءَهُمْ أَوْ إِخْوَانَهُمْ أَوْ عَشِيرَتَهُمْ أُولَئِكَ كَتَبَ فِي قُلُوبِهِمُ الْإِيمَانَ وَأَيَّدَهُمْ بِرُوحٍ مِنْهُ وَيُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ أُولَئِكَ حِزْبُ اللَّهِ أَلَا إِنَّ حِزْبَ اللَّهِ هُمُ الْمُفْلِحُونَ﴾ [المجادلة: ٢٢]","وأما ما روي عن عبدالله بن عباس قال: قام نبي الله صلى الله عليه وسلم يوما يصلي، فخطر خطرة فقال المنافقون الذين يصلون معه: ألا ترى أن له قلبين: قلبا معكم، وقلبا معهم؟ فأنزل الله تعالى: ﴿مَا جَعَلَ اللَّهُ لِرَجُلٍ مِنْ قَلْبَيْنِ فِي جَوْفِهِ﴾ فهو ضعيف.","رواه الترمذي (3199)، وابن خزيمة (865)، والحاكم (2/415) كلهم من طريق زهير بن معاوية، عن قابوس بن أبي ظبيان، عن أبيه، عن ابن عباس فذكره.","وفي الإسناد قابوس بن أبي ظبيان وهو ضعيف.","وفي المتن نكارة شديدة فإن النبي صلى الله عليه وسلم لم يكن في قلبه مكان للمنافقين.","وأما حمل الآية على الظاهر بأن الله ما جعل لرجل من قلبين فهو خلاف للواقع، فقد وُجد من كان له أكثر من قلب، واحتيج إلى عملية جراحية."],"191":["قوله: ﴿النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ﴾"],"194":["أي: الأحزاب الذين جاؤوا إلى المدينة لحرب المسلمين وإبادتهم، هزمهم الله وردّهم عن بلاد المسلمين، ولم يضطر المسلمون لردهم عن بلادهم إلى القتال والنضال."],"195":["أي: بنو قريظة وذلك في غزوة الأحزاب."],"196":["اجتمعت نساء رسول الله صلى الله عليه وسلم وطلبن منه زيادةً في النفقة والكسوة، وهو بمعنى زينة الدنيا كما في التنزيل أي الكماليات، وشق ذلك على رسول الله صلى الله عليه وسلم فآلى شهرا، ثم خيّر أزواجه، وقد جاء ذلك في أحاديث كثيرة منها:"],"197":["قوله: ﴿إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ﴾ أي أزواجه وبناته."],"200":["الذي أنعم الله عليه، وأنعم عليه رسوله صلى الله عليه وسلم، هو زيد بن حارثة مولى رسول الله صلى الله عليه وسلم وكان من جملة إنعام الله عليه أن الله عز وجل هداه للإسلام ووفقه لمتابعة الرسول صلى الله عليه وسلم، وكان من جملة إنعام الرسول صلى الله عليه وسلم أنه أعتقه من الرق."],"204":["قوله: ﴿هُوَ الَّذِي يُصَلِّي عَلَيْكُمْ وَمَلَائِكَتُهُ﴾ الصلاة من الله تعالى: الرحمة، والصلاة من الملائكة: الاستغفار للمؤمنين.","وقيل: الصلاة من الله على العبد هي إشاعة الذكر الجميل له في عباده.","وقوله: ﴿وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا﴾ المؤمنون أولى برحمة الله وإلا فهي وسعت كل مخلوق، وبها يتراحمون فيما بينهم."],"207":["هبة المرأة نفسها بدون صداق كانت خاصة بالنبي صلى الله عليه وسلم، ولا يجوز للمرأة أن تهب نفسها بغير صداق لغير النبي صلى الله عليه وسلم."],"209":["قوله: ﴿لَا يَحِلُّ لَكَ النِّسَاءُ مِنْ بَعْدُ﴾ اختلف في معنى الآية على أقوال:","فمنها: نهى اللهُ عز وجل رسولَه أن يتزوج بعد نسائه الأُول امرأة أخرى كما قال ابن عباس لأنهن لما خيّرهن اخترن الله ورسوله والدار الآخرة فقصر عليهن بقوله: ﴿لَا يَحِلُّ لَكَ النِّسَاءُ مِنْ بَعْدُ وَلَا أَنْ تَبَدَّلَ بِهِنَّ مِنْ أَزْوَاجٍ﴾ وهن التسع اللاتي اخترن الله ورسوله. قاله قتادة.","ومنها: لا يحل لك النساء بعد التي أحللنا لك بقولنا ﴿يَا أَيُّهَا النَّبِيُّ إِنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ﴾ [الأحزاب: ٥٠] إلى آخر الآية يعني: كل امرأة آتى أجرها، وما ملكت يمينُه مما أفاء الله عليه، وبنات عمه، وبنات عماته، وبنات خاله، وبنات خالاته، وكل امرأة وهبتْ نفسها له إن أراد أن يستنكحها، خالصة من دون المؤمنين. قال به أبي بن كعب وقال نحوه عكرمة والضحاك.","ومنها: أن الحرام عليه أن يتزوج من اليهوديات والنصرانيات بعد نزول هذه الآية، ورُوي نحو هذا عن مجاهد.","وأولى الأقوال كما قال ابن جرير قول من قال: لا يحل لك النساء من بعد اللوائي أحللتُهن لك بقولي: ﴿يَا أَيُّهَا النَّبِيُّ إِنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ﴾ اللَّاتِي آتَيْتَ أُجُورَهُنَّ إلى آخر الآية.","قلت: ويُحمل عليه قول عائشة:"],"212":["قال أبو العالية: \"صلاة الله: ثناؤه عليه عند الملائكة، وصلاة الملائكة: الدعاء\". ذكره البخاري في ترجمة الباب في كتاب التفسير (4797).","وقال الترمذي: \"روي عن سفيان الثوري وغير واحد من أهل العلم قالوا: صلاة الرب: الرحمة، وصلاة الملائكة: الاستغفار\". ذكره تحت حديث (485).","وقوله: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا﴾","فيه أمر للمؤمنين أن يصلوا على النبي صلى الله عليه وسلم، ووردتْ أحاديث كثيرة في الصلاة على النبيصلى الله عليه وسلم منها:"],"214":["الإيذاء الذي جاءَ ذكرُه في هذه الآية الكريمة هي قولهم: إنه آدرُ، فبرَّأه اللهُ منه كما جاء في الأحاديث الآتية:"],"215":["إن الله عز وجل عرض الأمانة –وهي التكليف الاختياري بامتثال الأوامر واجتناب النواهي- على السموات والأرض والجبال عرض تخيير بأنها إنْ قبلت وتحمّلتْ فأحسنتْ وقامتْ بأدائها على وجهها أثيبتْ عليها وجوزيتْ، وإنْ ضيّعتْ ولم تؤدّ ما تحمّلتْ والتزمت عوقبت على ذلك، فخافت السموات والأرض والجبال مع عظمتها أن لايقمن بأدائها فأبين عن حملها، ولكنْ حمَلها الإنسانُ مع ضعفه وجهله، وأما الانقياد الكوني فالسموات والارض والجبال وجميع ما في السموات والأرض فكلها منقادة لأمر الله عز وجل.","وفي هذه الآية الكريمة دليل على أن الإنسان وحده يقوم بإعمار الأرض؛ لأنه تحمل هذه المسؤولية، ولكنه وصف بالظلوم؛ لأنه إذا لم يراقب الله في السرّ والعلن، ولم يأتمر بأمره فلا يؤمن أن لا يحصل منه الظلم للآخرين، لذا أرسل الله الأنبياء لتذكيره وإصلاحه وتهذيبه.","وكذلك وصف الإنسان بالجهل لأن العلم لا نهاية له، فمهما بلغ الإنسان من العلم، فإن وراءه علم لا يزال يجهله، وفيه حثّ على استمرار بزيادة العلم، والنبيصلى الله عليه وسلم كونه يُوحى إليه ومع ذلك أمر أن يقول: وَقُلْ رَبِّ زِدْنِي عِلْمًا [طه: ١١٤]"],"217":["بعد أن ذكر الله ما تفضل به على داود، ذكر ابنه سليمان وما امتن به عليه وحصرها في ثلاثة أمور في هذه الآية الكريمة:","أولها: تسخير الريح له في شواطئ فلسطين فجعل شهرا تبدأ مشرقة لتجوال سفنه في البحر المتوسط شواطئ شمال إفريقيا، وشهرا مغربة للعودة إلى شواطئ فلسطين كما قال في سورة الأنبياء [8١] ﴿وَلِسُلَيْمَانَ الرِّيحَ عَاصِفَةً تَجْرِي بِأَمْرِهِ إِلَى الْأَرْضِ الَّتِي بَارَكْنَا فِيهَا وَكُنَّا بِكُلِّ شَيْءٍ عَالِمِينَ﴾.","وقوله: غُدُوُّهَا شَهْرٌ أي انطلاقُها.","وقوله: وَرَوَاحُهَا شَهْرٌ أي رجوعها بعد انتهاء مهمتها التي انطلق لها.","وقال بعض المفسرين: غدوها شهر ورواحها شهر كان في يوم واحد مسيرة شهرين، فتخرج سفنه من البحر المتوسط وتجول في البحار الواقعة في شرق إفريقيا وجنوبها حتى تصل سواحل اليمن في يوم واحد.","الثاني: جعل اللهُ النحاسَ له سائلا وهو قوله: ﴿وَأَسَلْنَا لَهُ عَيْنَ الْقِطْرِ﴾ القِطْر- بكسر القاف: النحاس المـُذاب. والإسالة: جعل الشيء سائلا أي مائعا. أي إن الله جعل النحاس سائلا له مثل الماء الذي يخرج من العين ليصنع منه أسلحة ودروعا وتماثيل ومحاريب وقدورا وغيرها مما يحتاج إليه.","والثالث: إن الله جعل الجن مطيعا له وهو قوله: ﴿وَمِنَ الْجِنِّ مَنْ يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِ ومع﴾ الجن حشرَ اللهُ له أيضا من الإنس والطير كما في قوله تعالى: ﴿وَحُشِرَ لِسُلَيْمَانَ جُنُودُهُ مِنَ الْجِنِّ وَالْإِنْسِ وَالطَّيْرِ فَهُمْ يُوزَعُونَ﴾"],"218":["روي عن ابن عباس عن النبي صلى الله عليه وسلم قال: ((كَانَ سُلَيمانُ نبيُّ اللهِ إذَا صَلَّى رأى شجرة نابتة بين يديه فيقول لها ما اسمك؟ فتقول كذا، فيقول لأي شيء أنت؟ فإن كانت تُغْرَسُ غُرسَت، وإن كان لدواءٍ كُتبتْ، فبينما هو يصلي ذاتَ يَومٍ إذ رأى شجرةً بين يديه، فقال لها: ما اسمك؟ قالت: الخروب، قال: لأي شيء أنت؟ قالت: لخراب هذا البيت، فقال سليمان: اللهم عمِّ على الجن موتي؛ حتى يعلم الإنس أن الجن لا يعلمون الغيب، فنَحَتَها عصا فتوكَّأ عليها حولا ميتًا، والجن تعمل، فأكلتها الأرضة، فسقط، فتبينت الإنس أن الجن لو كانوا يعلمون الغيب ما لبثوا حولا في العذاب المهين)). قال: وكان ابن عباس يقرؤها كذلك، قال: فشكرت الجن للأرضة فكانت تأتيها بالماء.","رواه البزار (كشف الأستار 2355) عن محمد بن مرزوق بن بكير، ثنا محمد بن مسعود، ثنا إبراهيم بن طهمان، عن عطاء بن السائب، عن سعيد بن جبير، عن ابن عباس فذكره مرفوعا.","ورواه أيضا البزار (2356) من طريق سفيان بن عيينة، عن عطاء بن السائب به موقوفا وهو الصواب، وفي بعض ألفاظه غرابة ونكارة. والكلام عليه مبسوط في كتاب الأنبياء.","بيّنَ الله سبحانه وتعالى بهذه الآية أن الجن لا يعلمون الغيب كما كانوا يزعمون لجهلهم، وقد اشتهر بين المشركين أن الجن يعلمون الغيب فكانوا يذهبون إلى الكهان ظنا منهم أن لكل كاهن جنّيا يأتيه بأخبار الغيب فردّ الله على الجميع بأنهم لو كانوا يعلمون الغيب لعلموا وفاة سليمان وهو أهون عليهم."],"219":["كانت سبأ ملوك اليمن وأهلها، وسبأ رجل ولدَ عشرةً، فسكنَ ستة منهم في اليمن، وأربعة منهم في الشام كما جاء في الحديث:"],"220":["قوله: ﴿وَبَيْنَ الْقُرَى الَّتِي بَارَكْنَا فِيهَا﴾ أي قرى الشام.","قوله: قُرًى ظَاهِرَةً أي بلد بعد بلد، فإذا خرجوا من مملكة سبأ التي كانت في اليمن للتجارة مروا على القرى المتواصلة بعضها ببعض، ولذلك ما كانوا يحملون الزاد والماء. والظاهر أن هذه القرى بناها ملوك هذه البلاد لراحة القوافل، أو بناها الناس نظرا لورود القوافل إليهم من اليمن إلى الشام، ومن الشام إلى اليمن.","قوله: ﴿وَقَدَّرْنَا فِيهَا السَّيْرَ سِيرُوا فِيهَا لَيَالِيَ وَأَيَّامًا آمِنِينَ﴾ أي لهم أن يسيروا ليلا أو نهارا فلا يعترضهم أحد بسوء، ولا يجدون المشقة في حصول الطعام والماء.","وهذه النعمة العظيمة التي وهبهم الله لم يقدروها، فقالوا: رَبَّنَا بَاعِدْ بَيْنَ أَسْفَارِنَا لعل قولهم هذا كان على سبيل الاستهزاء لدعوة الأنبياء والعلماء إلى التوحيد والعمل الصالح، وقد كفروا بالله بعد سليمان عليه السلام.","وقال مجاهد: بطروا النعمة، وسئموا الراحة.","قوله: فَجَعَلْنَاهُمْ أَحَادِيثَ أي عاقبناهم على كفرهم وشركهم بعد أن كانوا في نعمة من الله تعالى، وفي بحبوحة من العيش، فصار وجودهم في الأخبار والقصص عبرةً لمن بعدهم بخلاف المؤمن كما جاء في الصحيح:"],"223":["أي أن الله عز وجل يعطي ويبسط من الدنيا لمن يحب ولمن لا يحب، وأطيبهم في الدنيا من وُفّقَ للإسلام ورُزقَ الكفاف والقناعة بما أعطي، كما جاء في الصحيح:"],"226":["قوله: ﴿إِنْ هُوَ إِلَّا نَذِيرٌ لَكُمْ﴾ أسند إلى النبي صلى الله عليه وسلم مهمة النذارة فقام بها خير قيام."],"227":["أي يهلكه ويبطله تماما فلا تبقى منه بادئة ولا عائدة كما يقال: فلان ما يبدئ وما يعيد- أي ما يتكلم ببادئة ولا عائدة وهذا يقال للميت الذي لا يرتجل كلاما، ولا يجيب عن كلام غيره. وقد عبّر الله عنه بالزهوق، فقال: جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا وقال أيضا: ﴿بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ فَإِذَا هُوَ زَاهِقٌ﴾ [سورة الأنبياء: 18] وقد جاء في الحديث:"],"229":["قوله: فَلَا فَوْتَ أي لا مفر لهم ولا نجاة.","وقوله: ﴿وَأُخِذُوا مِنْ مَكَانٍ قَرِيبٍ﴾ أي لا يتمكنون من الهروب، بل يؤخذون من أول وهلة.","وقوله ﴿وَأَنَّى لَهُمُ التَّنَاوُشُ مِنْ مَكَانٍ بَعِيدٍ﴾ التناوش معناه التناول، يعني أنى لهم تناول الإيمان وهم في الدار الآخرة دار الجزاء، ليس بدار الإيمان والعمل.","وقوله: بِأَشْيَاعِهِمْ أي بأمثالهم من الأمم السابقة المكذبة للرسل."],"231":["قوله: ﴿جَاعِلِ الْمَلَائِكَةِ رُسُلًا أُولِي أَجْنِحَةٍ مَثْنَى وَثُلَاثَ وَرُبَاعَ يَزِيدُ فِي الْخَلْقِ مَا يَشَاءُ أي﴾ أن الله خلق الملائكة لبعضهم جناحان، ولبعضهم ثلاثة أجنحة، ولبعضهم أكثر من ذلك لقوله تعالى: ﴿فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى﴾ وقد جاء في الصحيح:"],"232":["أي: ما شاء الله كان، وما لم يشأ لم يكن، فلا مانع لما أعطى، ولا معطي لما منع، وقد جاء في الصحيح."],"233":["قوله: ﴿فَإِنَّ اللَّهَ يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَا﴾ءُ أي: بالقدر، وقد جاء في الحديث."],"234":["قوله: ﴿إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ﴾"],"235":["قوله: ﴿وَاللَّهُ خَلَقَكُمْ مِنْ تُرَابٍ ثُمَّ مِنْ نُطْفَةٍ﴾ أي: أن الله عز وجل ابتدأ خلق أبيكم آدم عليه السلام من تراب، ثم جعل نسله من سلالة من ماء مهين."],"237":["أي: الناس والدواب والأنعام كذلك مختلفة أيضا في ألوانها، فالناس منهم من هو في غاية السواد مثل الحبشة، ومنهم من هو في غاية البياض مثل الروم، ومنهم من هو بين ذلك مثل العرب. والهنود دون العرب في ذلك، وهذا كله من آيات الله عز وجل في خلقه، قال تعالى: وَاخْتِلَافُ أَلْسِنَتِكُمْ وَأَلْوَانِكُمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِلْعَالِمِينَ [سورة الروم: ٢٢]. من إفادات الحافظ ابن كثير.","وقوله: ﴿كَذَلِكَ إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَا﴾ءُ","أي: إنما يخشاه حق خشيته العلماء الذين يعرفون سبحانه بأسمائه الحسنى وصفاته العلى، ويعرفون حلاله وحرامه وأوامره ونواهيه، وما يحب ويرضى وما يكرهه ويغضب منه، ولا يُعلَم ذلك على الوجه الصحيح إلا بتعلم الكتاب والسنة وفهمهما وفق منهج السلف الصالح من الصحابة والتابعين، فمن بعدهم من أئمة الدين، ويقابلهم الجهال من المشركين والكفار، وكذلك من المسلمين الذين يتعلمون العلوم العصرية، وليس لديهم علمٌ كافٍ من الكتاب والسنة فيُخشى عليهم الزيغ والضلال، فقصر الله الخشية على العلماء العارفين بالكتاب والسنة، وعلى الذين يجعلون العلوم العصرية خاضعة لهما، ولذا وجب الاهتمام بتعليم الكتاب والسنة للعلماء العصريين."],"238":["قوله: ﴿يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِنْ ذَهَبٍ وَلُؤْلُؤًا﴾ أي: يُسوّرون في أيديهم رجالهم ونساؤهم أساور الذهب واللؤلؤ، وقد جاء في الحديث."],"239":["قوله: ﴿الَّذِي أَحَلَّنَا دَارَ الْمُقَامَةِ مِنْ فَضْلِهِ﴾"],"241":["قوله: ﴿أَوَلَمْ نُعَمِّرْكُمْ مَا يَتَذَكَّرُ فِيهِ مَنْ تَذَكَّرَ﴾ التعمير: هو تطويل العمر، ومنه قوله تعالى: ﴿يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ﴾ [سورة البقرة: 96] فإن العمر الذي منحه الله للإنسان من ستين إلى سبعين سنة كافٍ للتذكر والعمل بموجبه، وقد جاء في الصحيح."],"242":["قوله: إِنْ أَمْسَكَهُمَا إنْ نافية أي لا يمسكهما أحدٌ من بعده. لأن الله تعالى جعل السماوات والأرض وما فيهما من الكواكب والسيارات باتزان حيث لا يتصادم بعضه ببعض، فإذا أراد يوم القيامة أن يصطدم بعضه ببعض رفع هذا الاتزان، فتتغير السماوات والأرض، لقوله تعالى: ﴿يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ﴾ وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ [سورة إبراهيم: ٤٨] أي يقع الانقلاب العظيم في الكائنات كلها لا يعلم هيئتها ووسعتها إلا الله سبحانه و تعالى."],"243":["يحث الله على السير في الأرض للاعتبار، وأن ينظروا إلى عاقبة الذين من قبلهم ممن كذبوا الرسل، وكانوا أكثر منهم أموالا وأولادا وأشد منهم قوة وبأسا، فلما جاءهم العذاب لم تنفع قوتهم وأموالهم وأولادهم من الله شيئًا."],"245":["قوله: ﴿وَنَكْتُبُ مَا قَدَّمُوا وَآثَارَهُمْ﴾ أي: نكتب أعمالهم التي باشروها بأنفسهم في حياتهم، وكذلك نكتب آثار أعمالهم في حياتهم وبعد وفاتهم سواء كانت هذه الأعمال والآثار من باب الخير أو من باب الشر، كلها يسجل ويكتب لهم أو عليهم."],"247":["إن شهادة الجوارح يوم القيامة جاء ذكرها أيضا في آيات أخرى من القرآن الكريم، قال تعالى: ﴿يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُمْ بِمَا كَانُوا يَعْمَلُونَ﴾ (24) [سورة النور:24]، وقال تعالى: ﴿حَتَّى إِذَا مَا جَاءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَارُهُمْ وَجُلُودُهُمْ بِمَا كَانُوا يَعْمَلُونَ وَقَالُوا لِجُلُودِهِمْ لِمَ شَهِدْتُمْ عَلَيْنَا قَالُوا أَنْطَقَنَا اللَّهُ الَّذِي أَنْطَقَ كُلَّ شَيْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ﴾ (21) [سورة فصلت:20-21].","وذلك لأن الكفار والمنافقين يوم القيامة يكذبون، ويخفون شركهم ومعاصيهم بل ينكرونها، قال تعالى عنهم: ﴿ثُمَّ لَمْ تَكُنْ فِتْنَتُهُمْ إِلَّا أَنْ قَالُوا وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ﴾ [سورة الأنعام:23]، وقال تعالى: مَا كُنَّا نَعْمَلُ مِنْ سُوءٍ [سورة النحل: ٢٨]، وقال تعالى: ﴿ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنْتُمْ تُشْرِكُونَ مِنْ دُونِ اللَّهِ قَالُوا ضَلُّوا عَنَّا بَلْ لَمْ نَكُنْ نَدْعُو مِنْ قَبْلُ شَيْئًا كَذَلِكَ يُضِلُّ اللَّهُ الْكَافِرِينَ﴾ (74) [سورة غافر: ٧٣ – ٧٤].","فمن أجل إخفائهم وإنكارهم لشركهم ومعاصيهم، ومن أجل إظهار الله لعدله وإقامة الحجة عليهم يختم على ألسنتهم وأفواههم، ويشهد عليهم أيديهم وأرجلهم وجلودهم وغيرها من أعضاء الجسم وأركانه، وإليه يشير قوله تعالى في الآية المذكورة: ﴿الْيَوْمَ نَخْتِمُ عَلَى أَفْوَاهِهِمْ﴾... وقد جاءت الأحاديث في معناها."],"248":["أخبر الله تعالى أنه ما علّم النبي صلى الله عليه وسلم الشعر، وأنه لا يليق بمقام النبوة ولا يناسب له، وذلك حتى لا يختلط الوحي بالشعر، وكونه جرى على لسانه بعض الأشعار من غير قصد فلا يدل على كونه شاعرا، ومن ذلك ما جاء في الصحيح."],"251":["أي: أقسم الله عز وجل بالملائكة الذين يقفون لعبادة ربهم في صفوف متراصّة، وقد جاء في الصحيح."],"256":["قوله: فَبَشَّرْنَاهُ بِغُلَامٍ حَلِيمٍ","هذا الغلام هو إسماعيل بن إبراهيم عليهما السلام، وقد ذهبت طائفة من أهل العلم إلى أن الذبيح هو إسحاق بن إبراهيم، ولكن الصواب أنه إسماعيل، وليس بإسحاق، وهو الذي يدل عليه النظم القرآني من وجوه كثيرة، وفيما يلي ذكرها:","1- أن الملائكة لما بشّروا إبراهيم بإسحاق قالوا: ﴿قَالُوا لَا تَوْجَلْ إِنَّا نُبَشِّرُكَ بِغُلَامٍ﴾ عَلِيمٍ [سورة الحجر: ٥٣]، وإسماعيل وصف بالحلم في الآية الكريمة، وهذا هو الوصف المناسب لهذا المقام.","2- قال تعالى: ﴿فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ﴾ أي: كبر هذا الغلام وترعرع وصار يذهب ويمشي مع أبيه، وهذا يدل على أن ذلك الغلام الحليم الذبيح لم يكن كبيرا، وقد اتفق أهل الكتاب والمسلمون أن إسماعيل كان أكبر من إسحاق، وجاء في سفر التكوين ما يدل على ولادة إسماعيل قبل إسحاق بأربع عشرة سنة، فالظاهر أنها لما وقعت قصة الذبح لم يكن إسحاق ولد بعد.","3- قال تعالى: إِنَّ هَذَا لَهُوَ الْبَلَاءُ الْمُبِينُ ولا شك أن الأمر بذبح الإبن الأكبر الوحيد البكر أبلغ في الإبتلاء والإختبار، وعزم إبراهيم على تنفيذه أبلغ في الإمتثال والطاعة، وإسماعيل كان هو الأكبر والبكر من أولاد إبراهيم.","4- قال تعالى: وَبَشَّرْنَاهُ بِإِسْحَاقَ ﴿نَبِيًّا مِنَ الصَّالِحِينَ وَبَارَكْنَا عَلَيْهِ وَعَلَى إِسْحَاقَ﴾ وقال تعالى: فَبَشَّرْنَاهَا بِإِسْحَاقَ وَمِنْ وَرَاءِ إِسْحَاقَ يَعْقُوبَ [سورة هود: ٧١]، فالله عز وجل بشر إبراهيم بإسحاق، وذكر أنه يبارك عليهما، وأنه يولد في حياتهما ولد لإسحاق يكون اسمه يعقوب. فليس من المعقول أن يأمر الله بذبح إسحاق وهو صغير؛ لأن الله تعالى كان قد وعد إبراهيم بأن ابنه إسحاق سيكون له ولد ونسل وذرية.","5- إن إسماعيل عليه السلام سكن في مكة، وشارك أباه في بناء الكعبة، قال تعالى: وَإِذْ يَرْفَعُ إِبْرَاهِيمُ ﴿الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ﴾ [سورة البقرة: ١٢٧]. وقصة الذبح هذه كانت في منى كما أخبر النبي صلى الله عليه وسلم في أحاديثه، وأجمع على ذلك أهل الإسلام قاطبة.","وأما إسحاق فلم يرد في الكتاب والسنة ما يدل على مجيئه إلى مكة، وكذلك لم يذكر المؤرخون من المسلمين ومن أهل الكتاب وغيرهم مجيء إسحاق إلى مكة طول حياته ولو مرة واحدة. ولذا من المستبعد جدا أن يكون الذبيح إسحاق، بل هو إسماعيل قطعا بلا ريب للوجوه المذكورة، وقد بسطت هذه المسألة في مقالة مستقلة في كتابي: \"دراسات في اليهود والمسيحية\" ولا مانع من إيرادها هنا لأهميتها.","الذبيح هو إسماعيل: إن اليهود كعادتهم حرفوا حادثة الذبح ووضعوا اسم إسحاق عليه السلام في مكان الذبيح مع أن القرائن تدل على أنه إسماعيل.","وإليكم ما جاء في الإصحاح الثاني والعشرين من سفر التكوين: \"وحدث بعد هذه الأمور أن الله امتحن إبراهيم، فقال له: يا إبراهيم، فقال: هأنذا، فقال: خذ ابنك وحيدك الذي تحبه إسحاق، واذهب إلى أرض المريا، وأسعده، هناك محرقة على أحد الجبال الذي أقول لك، فبكر إبراهيم صباحا، وشد على حماره، وأخذ اثنين من غلمانه معه، وإسحاق ابنه وشقق حطبا لمحرقة، وقام، وذهب إلى الموضع الذي قال الله له، وفي اليوم الثالث رفع إبراهيم عينيه، وأبصر الموضع من بعيد، فقال إبراهيم لغلاميه: اجلسا أنتما ههنا مع الحمار، وأما أنا والغلام فنذهب إلى هناك، ونسجد ثم نرجع إليكما، فأخذ إبراهيم حطب المحرقة، ووضعه على إسحاق ابنه، وأخذ بيده النار والسكين، فذهبا كلاهما معا، وكلّم إسحاق إبراهيم أباه، وقال: يا أبي! فقال: هأنذا يا بني، فقال: هو ذا النار والحطب، ولكن أين الخروف للمحرقة؟ فقال إبراهيم: الله يرى له الخروف للمحرقة يا بني! فذهبا كلاهما معا، فلما أتيا إلى الموضع الذي قال له الله بنى إبراهيم هنا المذبح، ورتب الحطب وربط إسحاق ابنه، ووضعه على المذبح فوق الحطب، ثم مدّ إبراهيم يده، وأخذ السكين ليذبح ابنه، فناداه ملاك الرب من السماء، وقال: إبراهيم! إبراهيم! فقال: هأنذا، فقال: لا تمد يدك إلى الغلام ولا تفعل به شيئا، لأني الآن علمت أنك خائف الله، فلم تمسك ابنك وحيدك عني، فرفع إبراهيم عينيه، ونظر وإذا كبش وراءه ممسكا في الغابة بقرنيه، فذهب إبراهيم وأخذ الكبش وأصعقه محرقة عوضا عن ابنه، فدعا إبراهيم اسم ذلك الموضع \"يهوه يراه\" حتى أنه يقال اليوم في جبل الرب \"يرى\" ثم ذهب إبراهيم إلى بئر سبع وسكن فيه \".","هذه هي قصة الذبح في التوراة المزعومة، وتستخرج من هذه القصة الأمور التالية:","1- إن الله أمره أن يذبح ابنه الوحيد.","2- إن هذا الابن كان محبوبا لإبراهيم.","3- إن إبراهيم كان سكن بئر سبع قبل الذبح، وبعد الذبح.","4- يبعد المذبح \"مريا\" من بئر سبع مسافة ثلاثة أيام.","وفي ضوء هذه النقاط إذا نظرنا إلى آل إبراهيم اتضح لنا بوضوح أن الابن الوحيد لإبراهيم هو \"إسماعيل\"، لأنه ولد قبل أخيه بأربعة عشر عاما كما جاء في التكوين: \"فولدت هاجر لإبراهيم ابنا، ودعا إبرام اسم ابنه الذي ولدته هاجر إسماعيل، وكان إبرام ابن ست وثمانين سنة لما ولدت هاجر إسماعيل لإبرام، (16/15)، \" وكان إبرام ابن مائة سنة حين ولد له إسحاق ابنه\". (21/4).","فيفهم من هذا أن قصة الذبح كانت قبل ولادة إسحاق؛ لأن ابنه الوحيد البكر هو إسماعيل عليه السلام. وأن التوراة تنص على أن البكر هو الذي يقدم للذبائح سواء كان من الإنسان أو الحيوان، وهي شريعة مستمرة من آدم إلى موسى عليهما السلام، ففي سفر التكوين (4/4): \"وقدم هابيل أيضا من أبكار غنمه ومن سمانها فنظر الرب إلى هابيل وقربانه\".","هذا بموجب شريعة آدم وأولاده، وبقي هذا الحكم مستمرا إلى موسى عليه السلام، فإن البكر هو الذي يخصّص لله، ويقدس كما جاء في سفر الخروج (13/1-2): \"وحكم الرب موسى قائلا: قدس لي كل بكر، وكل فاتح رحم، من بني إسرائيل من الناس ومن البهائم، إنه لي\".","ولا شك أن نبي الله إسماعيل بكر أبيه هو الذي استحق هذا الشرف ليكون في خدمة الله.","الأمر الثاني: قوله: ابنك الوحيد الذي تحبه.","وهذا واضح وضوح الشمس فإن حبّ إبراهيم لإسماعيل لا يحتاج إلى إقامة دليل، لأنه ولد بعد ما بلغ من العمر ستا وثمانين سنة، وكان من نتيجة دعائه، ولذا سماه \"إسماعيل\" من استجابة الله دعاءه – أو \"سمع الله\".","ولذلك لما بشّر بالابن الثاني وهو إسحاق عليه السلام لم يزد على قوله: \"لله ليت إسماعيل يعيش أمامك\". سفر التكوين (17/18).","ولما طلبت سارة من إبراهيم أن يفارق ابنه إسماعيل وأمه حزن إبراهيم من هذا الطلب: \"ورأت سارة ابن هاجر المصرية الذي ولدته لإبراهيم نمزح. فقالت لإبراهيم: اطرد هذه الجارية وابنها؛ لأن ابن هذه الجارية لا يرث مع ابني إسحاق، فقبح الكلام جدا في عيني إبراهيم لسب ابنه. فقال الله لإبراهيم: لا تقبح في عينيك من أجل الغلام، ومن أجل جاريتك في كل ما تقول لك سارة اسمع قولها؛ لأنه لإسحاق يدعى لك نسل. وابن الجارية أيضا سأجعله أمة؛ لأنه نسلك\". سفر التكوين (21/9-13).","كأن الله هدّأ فؤاد إبراهيم بقوله: إنه سيجعل منه أمة وقد كان محزونا من طلب سارة مفارقة ابنه، وهو دليل على حبه له.","الأمر الثالث: إن إبراهيم كان يسكن بئر سبع عند ما أمر بذبح ابنه، ومنه أخذ ابنه، وذهب إلى \"مريا\".","تنص التوراة على أن إبراهيم أخذ هاجر وابنها إسماعيل، وتركهما في بئر سبع (التكوين:21/14) وسكن إسماعيل مع أمه في برية فاران (التكوين: 21/21). إن صح ما تقول التوراة فإن إبراهيم أخذ ابنه إسماعيل من بئر سبع، وذهب إلى \"مريا\".","ويبدو أن محرري التوراة لم يلاحظوا هذه الأمور، فاستعجلوا في إقحام اسم إسحاق عليه السلام في حادثة الذبح.","الأمر الرابع: ذهابه إلى \"مريا\" إذا نظرنا إلى موضع \"مريا\" واشتقاقه فهو في أصله \"مروة\" وأن التوراة تنص على أوصاف هذا الجبل بأنه بلوطة مورة (التكوين: 12/6). وفي النسخة العبرانية: \"برية مورة\" ولا شك أن المترجمين غيرو هذا الفظ من أصله \"مروة\" إلى \"مرية\" و\"مريا\" و \"موريا\" و \"مورة\" و \"مورءياه\" إلى غير ذلك.","والأمر الذي لا خلاف فيه بين اليهود والنصارى أن الذبيح كان جنب المعبد.","وهذه الأمور كلها تدل على أن ذلك كان في جوار بيت الله الحرام الذي يسمى الآن \"مروة\" والقرآن يقطع هذا النـزاع بقوله: ﴿رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ فَبَشَّرْنَاهُ بِغُلَامٍ حَلِيمٍ فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ قَالَ يَا بُنَيَّ إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ فَانْظُرْ مَاذَا تَرَى قَالَ يَا أَبَتِ افْعَلْ مَا تُؤْمَرُ سَتَجِدُنِي إِنْ شَاءَ اللَّهُ مِنَ الصَّابِرِينَ. فَلَمَّا أَسْلَمَا وَتَلَّهُ لِلْجَبِينِ وَنَادَيْنَاهُ﴾ أَنْ يَا إِبْرَاهِ﴿يمُ قَدْ صَدَّقْتَ الرُّؤْيَا إِنَّا كَذَلِكَ نَجْزِي الْمُحْسِنِينَ إِنَّ هَذَا لَهُوَ الْبَلَاءُ الْمُبِينُ وَفَدَيْنَاهُ بِذِبْحٍ عَظِيمٍ وَتَرَكْنَا عَلَيْهِ فِي الْآخِرِينَ سَلَامٌ عَلَى إِبْرَاهِيمَ كَذَلِكَ نَجْزِي الْمُحْسِنِينَ إِنَّهُ مِنْ عِبَادِنَا الْمُؤْمِنِينَ وَبَشَّرْنَاهُ بِإِسْحَاقَ نَبِيًّا مِنَ الصَّالِحِينَ وَبَارَكْنَا عَلَيْهِ وَعَلَى إِسْحَاقَ وَمِنْ ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِنَفْسِهِ مُبِينٌ﴾ (113)","لأن البشارة الأولى كانت لإسماعيل كما أن البشارة الثانية هي لإسحاق. والموضع الذي حدثت فيه قصة الذبح كان بجوار بيت الله الحرام الذي يسمى \"واديا غير ذي زرع\". وتتعارض نصوص التوراة بأن يكون إسحاق عليه السلام هو الذبيح، وذلك أن الله بشر إبراهيم بإسحاق، وذكر عقبه أن يباركه كما جاء في سفر التكوين (17/19): \"ولكن عهدي أقيمه مع إسحاق الذي تلده لك سارة في هذا الوقت في السنة الآتية\".","فهل من الممكن أن يخبر الله تعالى بأنه يقيم عهده مع إسحاق وهو لم يولد بعد، ثم يأمره بذبحه بعد ولادته، أو ليس فيه تناقض ظاهر؟ وأين يكون امتحان إبراهيم وقد علم سابقا أن إسحاق يكون أبا أمة عظيمة. بينما لم يعلم هذا عن إسماعيل إلا بعد ولادة إسحاق – أي بعد حادثة الذبح.","ولا يقال: قد يكون إسماعيل توفي في حياة إبراهيم، فلم يبق من ولده الذي وصف بأنه \"الوحيد\" إلا إسحاق، لأن إبراهيم مات عن إسماعيل وإسحاق، واشتركا في دفن أبيهما كما جاء في سفر التكوين (25/7-9): \"عاش إبراهيم مائة سنة وخمسة وسبعين سنة، وأسلم روحه، ومات بشيبة صالحة، وشيخا وشبعان أياما، وانضم إلى قومه ودفنه إسحاق وإسماعيل في مغارة المكفيلة\".","وأرى هذا القدر يكفي للتحقيق في الموضوع، والله الهادي إلى سواء السبيل.","وقوله: قَالَ يَا ﴿بُنَيَّ إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ﴾ وفيه دليل على أن رؤيا الأنبياء وحي، ولذا جاء العمل بها، بخلاف غيرهم من الناس فإنه لا يجوز الإقدام على شيء بمجرد الرؤيا."],"257":["يونس هو ابن متى وهو بالعبرية: يونان بن أمتائ وباسمه سفر في العهد القديم، وخلاصته أنه من أنبياء بني إسرائيل، وُلِدَ في فلسطين بعد غزو بنوخدنصر بيت المقدس، وأمر بالذهاب إلى مدينة نينوى في العراق التي تقع شرق دجلة بمقابل مدينة موصل لأن فيها أكثر من مائة ألف يهود بقوا أسرى في أيدي الأشوريين، ولكنه خرج منهم غاضبا قبل أن يؤذن له فوقع له ما وقع كما ذكر في القرآن في سورة النساء والأنعام ويونس والصافات.","فالتقمه الحوتُ في بحر الروم في ميناء يافا، لما أراد يونس عليه السلام الذهاب إلى ترشوش؛ لأن الحوت من أسماك البحر، وليس من أسماك النهر، فمن الخطأ الشائع أن هذه القصة وقعت في نهر دجلة."],"258":["أي: الملائكة يسبحون الله عز و جل، وقد جاء في الصحيح."],"259":["أي: إذا نزل العذاب في دارهم، فبئس ما يكون صباحهم، ولذا لما أغار النبي صلى الله عليه وسلم على خيبر وصبّحهم، فكان بئس الصباح صباحهم."],"262":["قوله: أَنَّمَا فَتَنَّاهُ في سياق فتنة داود عليه السلام قصص كثيرة ذكرت في كتب التفاسير نقلا من العهد القديم والجديد ما يخدش عصمة الأنبياء، وليس فيها شيء على شرط الجامع الكامل، فلذا أعرضت عنها.","وقوله: وَخَرَّ رَاكِعًا وَأَنَابَ أي: سجد لله، وأناب إليه."],"263":["قوله: إِنَّهُ أَوَّابٌ أي كثير الطاعة والعبادة والإنابة إلى الله.","قوله: الصَّافِنَاتُ الْجِيَادُ أي: الخيل الجياد السراع.","وقوله: ﴿إِذْ عُرِضَ عَلَيْهِ بِالْعَشِيِّ الصَّافِنَاتُ﴾ الْجِيَادُ أي قدم له الجياد الصافنات لاطلاعه على ما أعد من رباط الخيل لملاقاة العدو.","والصافنات من صفن الفرسُ صفونا أي قام على ثلاث قوائم، وطرف حافر الرابعة.","فانشغل سليمان برؤية الجياد الصافنات حتى توارت عن الأنظار، ونسي ذكر ربه أثناء عرضها عليه، ولم يكن ذلك من عادته؛ لأن الله وصفه بالأوّاب، فطلب من الحراس إعادة الجياد، وكاد أن يذبحهن من شدة غضبه، فلما سكن غضبه بدأ يمسح أعراف الخيل وعراقيبها شفقة بهن، وهو قوله تعالى: ﴿فَطَفِقَ مَسْحًا بِالسُّوقِ وَالْأَعْنَاقِ﴾.","وأما كونه بدأ يعقرهن فهو بعيد؛ لأنه لم يكن ليُعذّب الحيوان بسبب انشغاله بها عن ذكرالله، والله أعلم.","وقد روي أن سليمان عليه السلام كانت له خيل لها أجنحة.","عن عائشة قالت: قدم رسول الله صلى الله عليه وسلم من غزوة تبوك أو خيبر وفي سهوتها ستر، فهبت ريح، فكشفت ناحية الستر عن بنات لعائشة لعب، فقال: ((ما هذا، يا عائشة؟!)). قالت: بناتي. ورأى بينهن فرسا له جناحان من رقاع، فقال: ((ما هذا الذي أرى وسطهن؟)). قالت: فرس. قال: ((ما هذا الذي عليه؟)). قالت: جناحان. قال: ((فرس له جناحان!)). قالت: أما سمعت أن لسليمان خيلا لها أجنحة؟. قالت: فضحك النبي صلى الله عليه وسلم حتى رأيت نواجذه.","رواه أبو داود (4932)، والنسائي في الكبرى (4901)، وابن حبان (5864)، والبيهقي (10/219) كلهم من طريق يحيى بن أيوب، قال: حدثني عمارة بن غزية أن محمد بن إبراهيم حدثه عن أبي سلمة بن عبد الرحمن، عن عائشة، فذكرته.","ويحيى بن أيوب الغافقي المصري رمي بالوهم والخطأ.","وقولها: \"إن لسليمان خيلا لها أجنحة\" تفرد به يحيى بن أيوب هذا، ولم أجد له متابعا ولا شاهدا، وهو خارج عن المعتاد، فالله أعلم بصحته."],"265":["قوله: مُفَتَّحَةً لَهُمُ الْأَبْوَابُ فيها ثمانية أبواب، وتكون مفتوحة لأهل الإيمان والتقوى والعمل الصالح، كما جاء في الصحيح."],"266":["أي: أن الله عز وجل خلق إبليس من نار، وخلق آدم عليه السلام من طين، كما جاء في الصحيح."],"269":["قوله: ﴿إِنْ تَكْفُرُوا فَإِنَّ اللَّهَ غَنِيٌّ عَنْكُمْ﴾","أي: أن الله عز وجل غني عن جميع المخلوقات، وليس مفتقرا إليهم في شيء، وهم محتاجون إليه في كل شيء، وقد جاء في الصحيح."],"270":["قوله: أَمَّنْ هُوَ قَانِتٌ آنَاءَ اللَّيْلِ سَاجِدًا وَقَائِمًا أي: الّذي يعبد الله تعالى ويقضي ساعات الليل في القيام والسجود له سبحانه، لا يكون كالذي ليس كذلك، وقد جاءت أحاديث كثيرة في الحث على عبادة الله تعالى في آناء الليل، منها:"],"272":["قوله: ﴿إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ﴾ في هذه الآية الكريمة إخبار من الله عز و جل بأن النبيصلى الله عليه وسلم سيموت كما يموت غيره من الناس، وهي من الآيات التي استدل بها أبو بكر الصديق على موت رسول الله صلى الله عليه وسلم عند ما شك عمر في ذلك كما في الصحيح."],"273":["يعني أن المشركبن كانوا يعترفون بأن الله هو الذي خلق السماوات والأرض، وأنه هو الخالق وحده، ولكنهم كانوا يشركون في عبادة الله تعالى، فكانوا يعبدون الله، ويعبدون غيره مما لا يملك لهم ضرا ولا نفعا، فهم كانوا مقرين بتوحيد الربوبية، ولكنهم كانوا مشركين في توحيد الألوهية."],"275":["هذه الآية فيها دعوة لجميع أصحاب الذنوب والمعاصي من الشرك والقتل والزنا والظلم والربا وغيرها من الذنوب أن يبادروا بالتوبة والإنابة إلى الله عز وجل، وأن لا يقنطوا من رحمته تعالى، فهو سبحانه يقيل العثرة، ويقبل التوبة، ويغفر الذنوب جميعا لمن تاب منها ورجع عنها."],"280":["قوله: وَفُتِحَتْ أَبْوَابُهَ أي الجنة فيها أبواب تفتح وتغلق، ولها أسماء، وقد جاء في الحديث أن عددها ثمانية."],"281":["يخبر الله سبحانه وتعالى عن المؤمنين أنهم إذا دخلوا الجنة ورأوا فيها من نعيمها تنطلق لسانهم بحمد الله وشكره الذي أنجز ما وعدهم على لسان رسله من نعيم الجنة وسعتها، وجعلهم ينزلون منها حيث يشاؤون.","وقوله: وَأَوْرَثَنَا الْأَرْضَ أي أرض الجنة."],"283":["قوله: ﴿وَيَسْتَغْفِرُونَ لِلَّذِينَ آمَنُوا﴾","أي: الملائكة يدعون للمؤمنين، ويستغفرون لهم، ومن ذلك أنهم يؤمنون على دعاء المؤمن لأخيه المؤمن بظهر الغيب."],"285":["أي: استجرت بالله، وعذت به من شر الأشرار والمتكبرين والجبابرة، وكذلك كان النبي صلى الله عليه وسلم يستعيذ بالله من شر الأعداء."],"286":["قوله: ﴿أَتَقْتُلُونَ رَجُلًا أَنْ يَقُولَ رَبِّيَ اللَّهُ وَقَدْ جَاءَكُمْ بِالْبَيِّنَاتِ مِنْ رَبِّكُمْ﴾ أي: على ربوبية الله تعالى وألوهيته بخلاف قوم فرعون الذين اتخذوه ربا وإلها من دون الله.","وكان النبي صلى الله عليه وسلم يذكر أهل مكة بربوبية الله عز وجل لإفراد الله وحده بالعبادة، ومن أجل ذلك عاداه أهل مكة، وآذوه أشد الإيذاء، كما جاء ذلك في أحاديث كثيرة، منها."],"287":["قوله: ﴿قَالَ فِرْعَوْنُ مَا أُرِيكُمْ إِلَّا مَا أَرَى وَمَا أَهْدِيكُمْ إِلَّا سَبِيلَ الرَّشَادِ﴾","هذا كذب من فرعون وتضليل منه لأتباعه، قال تعالى: ﴿وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدَى﴾ [سورة طه:79]","وقال تعالى: ﴿فَاتَّبَعُوا أَمْرَ فِرْعَوْنَ وَمَا أَمْرُ فِرْعَوْنَ بِرَشِيدٍ﴾ [سورة هود:97]","فهو غشّ قومه، ولم يرشدهم إلى الصراط المستقيم ولم ينصح لهم، وقد جاء في الحديث أن الإمام الذي لا ينصح رعيته لا يجد رائحة الجنة."],"288":["قوله: ﴿النَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا﴾ فيه إثبات عذاب القبر، وقد وردت أحاديث كثيرة في عذاب القبر منها:"],"289":["قوله: إِنَّا لَنَنْصُرُ رُسُلَنَا أي: بالحجة والبرهان، فإن دعوة الأنبياء بقيت واستمرت، وغلبت على دعاوي من خالفهم.","وقيل: المراد به بعض الأنبياء والمرسلين وليسوا كلهم؛ لأن بعضهم قتلهم قومهم، كما قال تعالى: ﴿ذَلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ الْحَقِّ﴾ [سورة البقرة:61]. وإطلاق الكل وإرادة البعض سائغ في لغة العرب.","وقوله: وَالَّذِينَ آمَنُوا أي: أن الله ينصر المؤمنين فإنهم أولياؤه، وقد جاء في الصحيح."],"291":["قوله: بَأْسَنَا أي عذابنا.","قوله: ﴿قَالُوا آمَنَّا بِاللَّهِ ولكن﴾ الآن انتهى وقت الإيمان، وهذا كما قال فرعون حين أدركه الغرق: ﴿آمَنْتُ أَنَّهُ لَا إِلَهَ إِلَّا الَّذِي آمَنَتْ بِهِ بَنُو إِسْرَائِيلَ وَأَنَا مِنَ الْمُسْلِمِينَ﴾ (يونس: ٩٠) قال الله تعالى: آلْآنَ ﴿وَقَدْ عَصَيْتَ قَبْلُ وَكُنْتَ مِنَ الْمُفْسِدِينَ﴾ (يونس: ٩١). فلم يقبل الله منه إيمانه.","وقوله: ﴿سُنَّتَ اللَّهِ الَّتِي قَدْ خَلَتْ فِي عِبَادِهِ﴾ هذه سنة الله في جميع من تاب عند معاينة العذاب أنه لا يقبل، ولهذا قال: وَخَسِرَ هُنَالِكَ الْكَافِرُونَ أي لا ينفع إيمانهم بعد معاينة العذاب."],"293":["قال المنهال، عن سعيد بن جبير قال: قال رجل لابن عباس: إني أجد في القرآن أشياء تختلف عليّ، قال: ﴿فَلَا أَنْسَابَ بَيْنَهُمْ يَوْمَئِذٍ وَلَا يَتَسَاءَلُونَ﴾ [المؤمنون: ١٠١]، ﴿وَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ يَتَسَاءَلُونَ﴾ [سورة الصافات: ٢٧]، ﴿وَلَا يَكْتُمُونَ اللَّهَ حَدِيثًا﴾ [النساء: ٤٢]، ﴿وَاللَّهِ رَبِّنَا مَا كُنَّا مُشْرِكِينَ﴾ [سورة الأنعام: ٢٣]، فقد كتموا في هذه الآية؟. وقال: أَمِ السَّمَاءُ بَنَاهَا إلى قوله دَحَاهَا [سورة النازعات: ٢٧ – ٣٠]، فذكر خلق السماء قبل خلق الأرض، ثم قال: ﴿قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِالَّذِي خَلَقَ الْأَرْضَ فِي يَوْمَيْنِ﴾ إلى قوله طَائِعِينَ [سورة فصلت: 10-11]، فذكر في هذه خلق الأرض قبل السماء. وقال: ﴿وَكَانَ اللَّهُ غَفُورًا رَحِيمًا﴾[سورة النساء: ٩٦]، عَزِيزًا حَكِيمًا [سورة النساء: ٥٦]، سَمِيعًا بَصِيرًا [سورة النساء: ٥٨]، فكأنه كان ثم مضى؟","فقال: فَلَا أَنْسَابَ بَيْنَهُمْ [سورة المؤمنون: ١٠١] في النفخة الأولى، ثم ينفخ ﴿في الصور: فَصَعِقَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ﴾ [سورة الزمر: ٦٨]، فلا أنساب بينهم عند ذلك ولا يتساءلون، ثم في النفخة الآخرة: ﴿وَأَقْبَلَ بَعْضُهُمْ عَلَى بَعْضٍ يَتَسَاءَلُونَ﴾ [سورة الصافات: ٢٧]، وأما قوله: مَا كُنَّا مُشْرِكِينَ [سورة الأنعام: ٢٣]، ﴿وَلَا يَكْتُمُونَ اللَّهَ حَدِيثًا﴾ [سورة النساء: ٤٢]، فإن الله يغفر لأهل الإخلاص ذنوبهم، وقال المشركون: تعالوا نقول لم نكن مشركين، فخُتم على أفواههم، فتنطق أيديهم، فعند ذلك عُرِف أن الله لا يُكتَم حديثا، وعنده: يَوَدُّ الَّذِينَ كَفَرُوا [سورة النساء:٤٢] الآية. وخلق الأرض في يومين، ثم خلق السماء، ثم استوى إلى السماء، فسواهن في يومين آخرين، ثم دحا الأرض، ودحوها أن أخرج منها الماء والمرعى، وخلق الجبال والجمال والآكام وما بينهما في يومين آخرين، فذلك قوله دَحَاهَا، وقوله: ﴿خَلَقَ الْأَرْضَ فِي يَوْمَيْنِ﴾، فجُعلت الأرض وما فيها من شيء في أربعة أيام، وخُلقت السموات في يومين: ﴿وَكَانَ اللَّهُ غَفُورًا رَحِيمًا﴾[سورة النساء: ٩٦]، سمَّى نفسه بذلك، وذلك قوله أي لم يزل كذلك، فإن الله لم يرد شيئا إلا أصاب به الذي أراد، فلا يختلف عليك القرآن، فإن كلا من عند الله.","هكذا ذكره الإمام البخاري معلقا في كتاب التفسير.","وجاء في بعض نسخ البخاري:","\"قال أبو عبد الله: حدثنيه يوسف بن عدي، حدثنا عبيد الله بن عمرو، عن زيد بن أبي أنيسة، عن المنهال، بهذا\". هكذا جاء أيضا في فتح الباري.","قوله: ﴿خَلَقَ الْأَرْضَ فِي يَوْمَيْنِ﴾ قيل: هما الأحد والإثنين.","قوله: وَجَعَلَ فِيهَا رَوَاسِيَ مِنْ فَوْقِهَا أي جبالا ثابتا.","قوله: وَقَدَّرَ فِيهَا أَقْوَاتَهَا أي أرزاق العباد والبهائم.","وقوله: أَرْبَعَةِ أَيَّامٍ تكملة لمجموع مدة خلق الأرض والجبال وتقدير الأرزاق، فدخل في هذه الأربعة الأيام اليومان اللذان في قوله: فِي يَوْمَيْنِ فكأنه قيل في يومين آخرين فتلك أربعة أيام، وقيل: هما الثلاثاء والأربعاء.","وفيه ردّ الآخر على الأول في الذكر كما يقال: تزوجت أمس امرأة، واليوم ثنتين، وإحداهما هي التي تزوجتُها بالأمس.","وقوله: سَوَاءً لِلسَّائِلِينَ أي جوابا لمن سأل في كم خلقت الأرض والأقوات.","وقوله: ﴿ثُمَّ اسْتَوَى إِلَى السَّمَا﴾ءِ أي عمد وقصد إلى خلق السماء.","وقوله: فَقَضَاهُنَّ سَبْعَ سَمَاوَاتٍ فِي يَوْمَيْنِ أي فرغ من خلقهن. قيل: هما الخميس والجمعة، فتلك ستة أيام كما أخبر الله تعالى في آيات كثيرة أنه خلق السموات والأرض في ستة أيام ثم استوى على العرش.","وقد ثبت في الأحاديث الصحيحة أن آدم خلق يوم الجمعة.","وفي رواية مسلم (2789): وخلق آدم بعد العصر من يوم الجمعة في آخر الخلق، في آخر ساعة من ساعة الجمعة فيما بين العصر إلى الليل.","وسبق الكلام على رواية مسلم هذه التي فيها أن عدد أيام الخلق سبعة، بأنها مخالفة لصريح القرآن في كتاب بدء الخلق."],"296":["قوله: ﴿إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا﴾ أصل الاستقامة هو السير على الطريق القويم وعدم الاعوجاج عنه."],"297":["قوله: ﴿إِلَيْهِ يُرَدُّ عِلْمُ السَّاعَةِ﴾ أي: لا يعلم ذلك أحد غير الله عز وجل، كما قال النبي صلى الله عليه وسلم لجبرئيل حين سأله عن الساعة."],"299":["أخبر الله في هذه الآية بأنه هو الذي أوحى إلى النبي صلى الله عليه وسلم كما أوحى إلى من قبله من الأنبياء والمرسلين،","وقال تعالى في آية أخرى: ﴿وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ﴾ (65) [سورة الزمر: ٦٥].","والنبي صلى الله عليه وسلم كان يأتيه الوحي في صور مختلفة وكيفيات متعددة، منها ما جاء ذكرها في الحديث الآتي."],"300":["قوله: لِتُنْذِرَ أُمَّ الْقُرَى أم القرى: هي مكة المكرمة، لأنها أعظم وأقدس قرية في الجزيرة، ومن ثم في العالم كله. وهي خير أرض الله كما جاء في الحديث."],"301":["قوله: ﴿وَالَّذِينَ آمَنُوا مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا الْحَقُّ أي﴾: أن أهل الإيمان يخافون من الساعة، ويجلون من وقوعها، ويعلمون أنها واقعة لا محالة، ولذا يعملون من أجلها ويستعدون لها، وإليه أرشد النبي صلى الله عليه وسلم الصحابي لما سأله عن وقت الساعة."],"302":["قوله: ﴿وَمَنْ كَانَ يُرِيدُ حَرْثَ الدُّنْيَا نُؤْتِهِ مِنْهَا وَمَا لَهُ فِي الْآخِرَةِ مِنْ نَصِيبٍ أي﴾: من كانت الدنيا هي غاية مطلوبه ومقصوده، ولم يكن له في الآخرة همة البتة، حرمه الله الآخرة وأعطاه نصيبه من الدنيا إن شاء، قال تعالى: ﴿مَنْ كَانَ يُرِيدُ الْعَاجِلَةَ عَجَّلْنَا لَهُ فِيهَا مَا نَشَاءُ لِمَنْ نُرِيدُ ثُمَّ جَعَلْنَا لَهُ جَهَنَّمَ يَصْلَاهَا مَذْمُومًا مَدْحُورًا﴾ [سورة الإسراء: ١٨]."],"303":["قوله: ﴿قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَى﴾ أي: أني لا أسألكم على هذا البلاغ والنصح لكم شيئا من دنياكم وأموالكم، وإنما أطلب منكم أن تكفوا شركم وإيذاءكم، لما بيني وبينكم من الرحم والقرابة، وقد جاء هذا المعنى عن ابن عباس ."],"304":["قوله: ﴿وَهُوَ الَّذِي يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَعْفُو عَنِ السَّيِّئَاتِ﴾ أي: أن الله عز وجل يعفو عن عباده ما اقترفوه من السيئات، ويغفر لهم، ويقبل توبتهم إذا تابوا إليه، بل هو سبحانه يفرح من ذلك، كما جاء في الصحيح."],"305":["قوله: ﴿وَهُوَ عَلَى جَمْعِهِمْ إِذَا يَشَاءُ قَدِيرٌ﴾ أي: أن الله عز وجل بعد خلقهم وبثهم يجمعهم للحساب والجزاء إذا شاء، والله عز وجل قادر على كل شيء، قال تعالى: ﴿قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ أَوْ مِنْ تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُمْ بَأْسَ بَعْضٍ﴾ [سورة الأنعام: ٦٥]. وقال تعالى: ﴿وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُقْتَدِرًا﴾ [سورة الكهف: ٤٥]، وقال تعالى: ﴿وَلَوْ شَاءَ اللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَارِهِمْ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾ [سورة البقرة: ٢٠]، وقال تعالى: ﴿يُعَذِّبُ مَنْ يَشَاءُ وَيَغْفِرُ لِمَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾ [سورة المائدة: ٤٠]، وقال تعالى: ﴿يَخْلُقُ اللَّهُ مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾ [سورة النور: ٤٥] ونحوها من الآيات، فالمشيئة فيها متعلقة بالأفعال المذكورة فيها من إذهاب السمع، والبصر، والتعذيب، والمغفرة، والخلق، وأما القدرة فهي مطلقة عامة.","فما شاع في بعض الأوساط من قول: \"والله على ما يشاء قدير\" خطأ واضح، لأن قدرة الله عز وجل ليست مقصورة على ما شاء فقط، بل قدرته سبحانه مطلقة عامة شاملة كاملة، فالصحيح أن يقال: والله على كل شيء قدير، كما جاءت به النصوص القرآنية."],"306":["قوله: ﴿وَإِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَ﴾ أي: لا ينتقمون لأنفسهم بل يغضبون ويغفرون، وهذا هو ديدنهم وسجيتهم، حتى إنهم إذا أغضبهم أحد بشيء من قوله أو فعله كظموا ذلك الغضب، ولم يقابلوا المسيء إلا بالإحسان والعفو والصفح، والنبي صلى الله عليه وسلم هو أفضل من ينطبق عليه ذلك."],"309":["أي: لو أن الناس صاروا كلهم كفارا، وصارتْ هذه الأبواب والدرج والسرر والسقف والبيوت من ذهب وفضة؛ فإنها من متاع الدنيا الفانية الزائلة الحقيرة عند الله تعالى، ولكن الآخرة هي الباقية والتي تدوم ولا تزول، ونعمها لا تكون إلا لأهل الإيمان والتقوى، لا يشاركهم فيها أحد غيرهم، وقد جاء في ذلك أحاديث منها."],"310":["أي: أن هذا القرآن تذكير لك ولقومك لتبدأ الدعوة بهم، قال تعالى: ﴿وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ﴾ [سورة الشعراء: ٢١٤]. وتخصيص عشيرة النبي صلى الله عليه وسلم وقومه بالذكر لا ينفي غيرهم، إنما جاء ذكرهم في الآية المذكورة لأنهم أول المخاطبين، وإلا فالقرآن أنزل هدى ورحمة للناس كافة، قال تعالى: ﴿شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ هُدًى لِلنَّاسِ وَبَيِّنَاتٍ مِنَ الْهُدَى وَالْفُرْقَانِ﴾ [سورة البقرة: ١٨٥]، والرسول الذي أنزل عليه هذا القرآن أرسل إلى الناس كافة، قال تعالى: ﴿وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا﴾ [سورة سبأ: ٢٨]."],"311":["قوله: يَصِدُّونَ أي: يضجون، وذلك لما ضُرِبَ ابن مريم مثلا ضجَّ أهل مكة، وقالوا: ما يريد محمد منا إلا أن نعبده ونتخذه إلها كما عبدت النصارى ابنَ مريم.","قوله تعالى: وَقَالُوا ﴿أَآلِهَتُنَا خَيْرٌ أَمْ هُوَ﴾ يعنون محمدا، فنطيعه ونعبده ونترك آلهتنا. وبه قال قتادة.","وقوله تعالى: ﴿مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًا﴾ يعني هذا المثل جدلا وخصومة بالباطل وإلا متى دعا محمد إلى عبادته، وقد جاء في الحديث:"],"312":["أي: أعمالكم الصالحة كانت سببا لشمول رحمة الله إياكم، وإذنه لكم بدخول الجنة، فإنه لا يُدخل أحدا عمله الجنة، ولكن بفضل الله ورحمته."],"315":["قوله: وَالْكِتَابِ الْمُبِينِ أي القرآن الكريم.","وقوله: إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ أي: في ليلة القدر، كما قال تعالى: إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ [القدر:١]، وكان ذلك في شهر رمضان، كما قال تعالى: ﴿شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ﴾ [البقرة:١٨٥].","وليلة القدر تكون في الوتر من العشر الأواخر من رمضان كما جاء في الصحيح."],"316":["قوله: ﴿فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ﴾ فيه قولان عند المفسرين: الأول: إن هذا الدخان المذكور في الآية والذي سلَّى الله به نبيه وتوعَّد به الكفار قد وقع، وكان ذلك حين تمردت قريش واستعصت، فدعا عليهم النبي صلى الله عليه وسلم بالقحط والجدب، ويدل على ذلك من الأحاديث ما يأتي:"],"317":["أي: أن الله تعالى أعطى ما كان بيد فرعون وقومه من الجنات والعيون وغيرها من النعم قوما آخرين من أهل مصر، وليسوا هم بني إسرائيل، لأنهم بعد خروجهم من مصر لم يرجعوا إليها قط."],"318":["قوله: ﴿إِلَّا الْمَوْتَةَ الْأُولَى﴾ أي سوى الموتة التي ذاقوها في الدنيا، وأما في الآخرة فلا يذوقون الموت أبدا، كما جاء في الصحيح."],"320":["قوله: مَنِ اتَّخَذَ إِلَهَهُ هَوَاهُ أي: يتخذ الشجر والحجر وغيرهما معبودا له حسب رغبته."],"321":["قوله: الدَّهْرُ الدهر هو الزمان، وكون الله هو الدهر- أي أنه متصرف هذا الزمان، قال الشافعي وأبو عبيد وغيرهما من الأئمة: كانت العرب في جاهليتها إذا أصابهم شدة وبلاء قالوا: يا خيبة الدهر، فيسندون تلك الأفعال إلى الدهر ويسبونه، وإنما فاعلها هو الله عز وجل، فكأنهم إنما سبوا الله عز وجل؛ لأنه فاعل ذلك في الحقيقة، فلهذا نهي عن سب الدهر بهذا الاعتبار."],"322":["أي: يدخلهم الله الجنة يوم القيامة، وهذا كله من رحمة الله، فقد جاء في الصحيح."],"327":["قوله: ﴿مَا كُنْتُ بِدْعًا مِنَ الرُّسُلِ﴾ أي: بديعا مثل نصف ونصيف، وجمْع البدْع أبداع، ومعناه لستُ بأول مرسل، فقد بعث قبلي كثير من الأنبياء فكيف تنكرون نبوتي.","وقوله: ﴿وَمَا أَدْرِي مَا يُفْعَلُ بِي وَلَا بِكُمْ﴾"],"329":["قوله: وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ إِحْسَانًا فيها وصية من الله تعالى بالبر بالوالدين والإحسان إليهما والحنو عليهما والشكر والتقدير لهما، وطاعتهما في غير معصية الله ورسوله، والأحاديث في هذا المعنى كثيرة، وللآية سبب نزول، وهي كلها مذكورة بالتفصيل في تفسير سورة العنكبوت الآية (8) وفي سورة لقمان الآية (14-15).","قوله: وَحَمْلُهُ وَفِصَالُهُ ثَلَاثُونَ شَهْرًا يعني إذا كان أقل مدة الحمل ستة أشهر فيكون أكثر مدة الرضاع أربعة وعشرين شهرا، وإنْ كانتْ مدة الحمل تسعة أشهر فتكون مدة الرضاع واحدا وعشرين شهرا.","وقوله: ﴿حَتَّى إِذَا بَلَغَ أَشُدَّهُ وَبَلَغَ أَرْبَعِينَ سَنَةً﴾ إلى آخر الآية، يقال: إنها نزلتْ في أبي بكر الصديق فإنه أسلم هو، وأبواه، وذريته عبد الرحمن بن أبي بكر وابن عبد الرحمن أبو عتيق كلهم أدركوا النبي صلى الله عليه وسلم فآمنوا به، ولم يكن ذلك لأحد من الصحابة، وقد استجاب الله دعاءه في والديه وذريته.","وقوله: قَالَ رَبِّ أَوْزِعْنِي أي ألهمني."],"330":["هذه الآية نزلت في شخص كانت أم المؤمنين عائشة رضي الله عنها تعرفه، ولكنها لم تخبر عنه، ولما قال مروان بن الحكم بأنها نزلت في عبد الرحمن بن أبي بكر الصديق كذَّبته عائشة في ذلك وأنكرته عليه، كما جاء في الصحيح."],"331":["قوله: ﴿فَلَمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ﴾ أي: معترضا كالسحاب، قد أقبل على أوديتهم التي تسيل عليهم وترويهم، فظنوه سحابا ممطرا، فإذا هو عذاب أليم، ولذلك كان النبي صلى الله عليه وسلم إذا رأى الغيم عرف في وجهه الكراهية مخافة أن يكون فيه عذاب، كما جاء في الصحيح."],"332":["الجن جاؤوا إلى النبي صلى الله عليه وسلم، واستمعوا القرآن فآمنوا، ثم عادوا إلى قومهم منذرين ودعاة إلى الله عز وجل، ووفادتهم على النبي صلى الله عليه وسلم واستماعهم القرآن منه قد تكرر عدة مرات، يدل على ذلك أحاديث، منها ما يلي:"],"334":["قوله: ﴿حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا﴾ أي: أن ضرب الرقاب وشد الوثاق يكون في حالة الحرب فقط، فإذا لم تكن حرب لسبب من الأسباب فلا قتل، ولا أسر.","وإلى هذا الحكم ذهب جمهور أهل العلم من الصحابة والتابعين وهو قول الشافعي وأحمد وإسحاق فقالوا: الإمام بالخيار في الكفار الذين وقعوا في الأسر بين أن يقتلهم، أو يسترقّهم، أو يمنّ عليهم فيطلقهم بلا عوض، أو يفاديهم بالمال.","وذهب بعض أهل العلم منهم الأوزاعي إلى أن هذه الآية منسوخة بقوله تعالى: ﴿فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ﴾ [التوبة: ٥] وبه قال أصحاب الرأي.","وقوله: ﴿حَتَّى تَضَعَ الْحَرْبُ أَوْزَارَهَا﴾ أي أثقالها وأحمالها، وأصل الوزر: ما يحتمل الإنسان فسمى الأسلحة أوزارا لأنها تحمل.","وقوله: ﴿وَالَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ فَلَنْ يُضِلَّ أَعْمَالَهُمْ﴾ أي: أن الله عز وجل لا يضيع أعمال الشهداء بل يجزيهم عليها الجزاء الأوفى، ومن ذلك ما جاء في الحديث."],"335":["أي: أن الله عز وجل يهديهم إلى الجنة، ويصلح حالهم، ويُهَذِّبهم، ويُنَقِّيهم، ويُعَرِّفهم منازلهم في الجنة، ويهديهم إليها، ويدلهم عليها، كما كانوا يعرفون منازلهم في الدنيا، ويذهبون إليها ويدخلونها ويقيمون فيها، كما جاء في الصحيح."],"337":["قوله: ﴿وَالَّذِينَ كَفَرُوا يَتَمَتَّعُونَ وَيَأْكُلُونَ كَمَا تَأْكُلُ الْأَنْعَامُ﴾ أي: يكون جل همهم التمتع بلذات الدنيا وشهواتها والإكثار من الأكل والشرب فيها، وقد جاء في الحديث أن من صفات الكافر أنه يأكل ويشرب في سبعة أمعاء."],"339":["قوله: فَقَدْ جَاءَ أَشْرَاطُهَا أي: أماراتها وعلاماتها الدالة على قربها، وقد أخبر النبي صلى الله عليه وسلم عن أمارات الساعة وأشراطها، ومن ذلك بعثة النبي صلى الله عليه وسلم."],"340":["إن الله عز وجل أمر نبيه صلى الله عليه وسلم بالاستغفار، والنبي صلى الله عليه وسلم كان يستغفر كثيرا، مع أنه مغفور له، كما قال تعالى: ﴿لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ﴾ [الفتح: 2]، وفي ذلك حث للأمة على كثرة الاستغفار والمداومة عليه."],"341":["قوله: ﴿وَتُقَطِّعُوا أَرْحَامَكُمْ﴾ فيه تحذير من الله عز وجل عن قطيعة الرحم، وقد جاءت أحاديث كثيرة فيها نهي عن قطعية الرحم وأمر بصلته، وحث على البر والإحسان إلى الأقارب، ومنها."],"342":["رُويَ عن ابن عمر قال: كنا معشر أصحاب رسول الله صلى الله عليه وسلم نرى أنه ليس شيء من حسناتنا إلا مقبول حتى نزلت: ﴿أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَلَا تُبْطِلُوا أَعْمَالَكُمْ﴾ فقلنا: ما هذا الذي يبطل أعمالنا؟! فقلنا: الكبائر الموجبات والفواحش حتى نزلت: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَا﴾ءُ [النساء: ٤٨]، فلما نزلت كففنا عن القول في ذلك، فكنا نخاف على من أصاب الكبائر والفواحش، ونرجو لمن لم يصبها.","رواه محمد بن نصر المروزي في تعظيم قدر الصلاة (699) عن محمد بن عبدالله بن القهزاد، قال: حدثني ابن وهب، قال: حدثني أبو جميل، ثنا عبد الله بن المبارك، أنا بكير بن معروف، عن مقاتل بن حيان، عن نافع، عن ابن عمرفذكره.","ورجاله ثقات غير أبي جميل فلم أقف على ترجمته."],"348":["قوله: ﴿لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ﴾ أي: أن هذا الفتح المبين ينتج منه ويترتب عليه أمور، وهي كما ذكر الله تعالى في هذه الآية الكريمة:","1- مغفرة الله لنبيه مغفرة تامة، ما تقدم من ذنبه وما تأخر.","2- إتمام الله نعمته عليه.","3- هداية الله له الصراط المستقيم.","4- نصر الله له نصرا عزيزا، فكان هذا الصلح المبين سببا لفتح مكة."],"351":["قوله: ﴿قَوْمٍ أُولِي بَأْسٍ شَدِيدٍ﴾ هم فارس والروم ومن نحا نحوهم، وقد قاتلهم المسلمون في عهد الخلفاء الراشدين، فدخلوا في الإسلام، وقيل غير ذلك."],"355":["قوله: ﴿لَقَدْ صَدَقَ اللَّهُ رَسُولَهُ الرُّؤْيَا بِالْحَقِّ لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ أري﴾ رسول الله صلى الله عليه وسلم في المنام أنه دخل مكة وطاف بالبيت، فأخبر بها أصحابه، وخرج معهم لأداء العمرة ولكن صدَّهم المشركون، وحالوا بينهم وبين البيت، فكانت صلح الحديبية، ولذلك نحر النبي صلى الله عليه وسلم هديه، وحلق رأسه، وعاد إلى مكة في العام المقبل لأداء العمرة حسب الصلح، فدخل مكة هو والمسلمون، وطافوا بالبيت وأدوا العمرة، وهي معروفة بعمرة القضاء، وبها تحققت رؤيا النبي صلى الله عليه وسلم."],"356":["هذه الآية من الآيات التي مدح الله فيها الصحابة، وأخبر عما كانوا عليه من الصفات والأحوال الجميلة الجليلة، وقد وردت في فضائلهم والنهي عن التعرض لهم بالإساءة أحاديث كثيرة، منها."],"359":["قوله: لَا يَعْقِلُونَ أي لا يعرفون منـزلة النبي صلى الله عليه وسلم والتأدب معه."],"360":["إن إلقاء الله عز وجل في قلب عبد من عباده محبة الإيمان وكراهية الكفر والفسوق والعصيان نعمة كبيرة وفضل عظيم من الله عز وجل على ذلك العبد، وقد دعا النبي صلى الله عليه وسلم والصحابة خلفه أن يُحَبِّبَ الله عز وجل إليهم الإيمان، وأن يُزَيِّنه في قلوبهم، وأن يُكَرِّه إليهم الكفر والفسوق والعصيان."],"362":["قوله: ﴿وَلَا تَلْمِزُوا أَنْفُسَكُمْ﴾ أي: لا يعب بعضكم على بعض، ولا يطعن بعضكم على بعض، واللمز يكون بالقول في بيان العيوب، والهمز يكون بالفعل كالإشارة باليد وطرف العين ونحو ذلك، وكلاهما محرم، متوعد عليه بالنار. قال تعالى: وَيْلٌ لِكُلِّ هُمَزَةٍ لُمَزَةٍ","وقوله: ﴿وَلَا تَنَابَزُوا بِالْأَلْقَابِ﴾ أي: لا ينادي بعضكم بعضا بالألقاب التي لا يرضاها صاحبها."],"363":["حذر الله في هذه الآية من سوء الظن، ونهى عن البحث عن عورات الناس وتتبعها، ونهى عن اغتيابهم وذكر مساويهم، والأحاديث النبوية في ذلك كثيرة، منها."],"365":["قوله: ﴿قَالَتِ الْأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا﴾","أي: أن الإيمان أعلى درجة من الإسلام، وأخص منه، ويدل على ذلك أيضا الحديث الآتي."],"368":["قوله: ﴿أَفَعَيِينَا بِالْخَلْقِ الْأَوَّلِ﴾ أي: أن الله عز وجل لم يعجز من ابتداء الخلق، والإعادة أسهل منه، قال تعالى: ﴿وَهُوَ الَّذِي يَبْدَأُ الْخَلْقَ ثُمَّ يُعِيدُهُ وَهُوَ أَهْوَنُ عَلَيْهِ﴾ [الروم: ٢٧]"],"369":["قوله: ﴿وَنَعْلَمُ مَا تُوَسْوِسُ بِهِ نَفْسُهُ﴾ أي: أن علم الله عز وجل شامل ومحيط بجميع الأمور، حتى إنه تعالى يعلم ما توسوس به نفوس بني آدم، إلا أن الله عز وجل بفضله ورحمته لا يؤاخذ على وسوسة النفوس، كما جاء في الصحيح."],"370":["أي: كل ما يتكلم به الإنسان ويتلفظ به يكتب له أو عليه، فينبغي التنبه لذلك، ويجب حفظ اللسان عما لا يعنيه ولا خير فيه، وقد جاءت أحاديث كثيرة في ذلك، منها:"],"372":["قوله: ﴿لَقَدْ كُنْتَ فِي غَفْلَةٍ مِنْ هَذَا﴾ أي: من يوم القيامة والاستعداد له.","وقوله: ﴿فَبَصَرُكَ الْيَوْمَ حَدِيدٌ﴾ أي: قوي؛ لأن كل واحد يوم القيامة يرى كل شيء بعينه ويؤمن، ولكن لا ينفعهم ذلك، قال تعالى: ﴿أَسْمِعْ بِهِمْ وَأَبْصِرْ يَوْمَ يَأْتُونَنَا﴾ [مريم: ٣٨] وقال تعالى: ﴿وَلَوْ تَرَى إِذِ الْمُجْرِمُونَ نَاكِسُو رُءُوسِهِمْ عِنْدَ رَبِّهِمْ رَبَّنَا أَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَالِحًا إِنَّا مُوقِنُونَ﴾ [السجدة:١٢]."],"375":["قوله: ﴿لَهُمْ مَا يَشَاءُونَ فِيهَا﴾ أي: أنهم يجدون فيها جميع أصناف الملاذ، وكلما طلبوا أحضر لهم، قال تعالى: ﴿وَلَكُمْ فِيهَا مَا تَشْتَهِي أَنْفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ﴾ [فصلت: ٣١]"],"376":["أي: اصبر على مخالفة المشركين وإيذائهم وتكذيبهم لك ولما جئت به، واشتغل بطاعة ربك وعبادته وتسبيحه والصلاة له."],"377":["قوله: ﴿يَوْمَ تَشَقَّقُ الْأَرْضُ عَنْهُمْ سِرَاعًا﴾ أي: تنشق القبور من أصحابها يوم القيامة، فيخرجون منها، وأول من ينشق عنه القبر هو نبينا محمد صلى الله عليه وسلم، كما جاء في الصحيح."],"379":["الهجوع: النوم بالليل دون النهار، أي: كانوا قليلي النوم في الليل ويصلون أكثر الليل، وقد جاءت أحاديث كثيرة في الحث على ذلك."],"380":["أي: يستغفرون الله تعالى من ذنوبهم، وللاستغفار بالأسحار فضيلة وخصوصية ليست لغيرها، وذلك لنزول الرب إلى السماء الدنيا ومغفرته لمن يستغفره في ذلك الوقت كما جاء في الصحيح:"],"381":["أي: أنهم يعطون المحتاجين الذين يسألون الناس ويطلبون منهم، وكذلك هم يعطون المحتاجين الذين يتعففون ولا يسألون الناس، وقد جاء في الصحيح."],"382":["قوله: الرِّيحَ الْعَقِيمَ هي التي لا خير فيها ولا بركة، ولا تلقح شجرا، ولا تحمل مطرا، وقد جاء في الصحيح."],"383":["قوله: إِلَّا لِيَعْبُدُونِ أي: يوحدوني ولا يعبدون غيري. فيه قصر علة خلق الجن والإنس على إرادته الشرعية، وهي عبادة الله وحده ونبذ ما سواه؛ وأما ما جاء في آية أخرى: ﴿وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ الْجِنِّ وَالْإِنْسِ﴾ [سورة الأعراف: ١٧٩] فهذه من الإرادة الكونية دون الشرعية."],"385":["قوله: وَالطُّورِ الطور هو الجبل الذي كلَّم الله عليه موسى عليه السلام بالأرض المقدسة.","وقوله: وَكِتَابٍ مَسْطُورٍ هو اللوح المحفوظ، وقيل: الكتب المنزلة في الألواح مثل التوراة."],"386":["أي: لا يخلو من راكع وساجد من الملائكة، كما لا تخلو الكعبة المشرفة من الطائفين والراكعين والساجدين. وهو في السماء السابعة، يدخله كل يوم سبعون ألف ملك، كما جاء في الصحيح."],"387":["هذا من فضل الله على ذرية المؤمنين أن الله يرفع درجاتهم في الجنة من أجل آبائهم، فيلحقهم بهم وإن لم يبلغوا منازلهم، وجاء في الحديث أن الله يرفع درجات الآباء في الجنة من أجل دعاء الأبناء واستغفارهم لهم."],"390":["قوله: ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ حِينَ تَقُومُ﴾ أي: إلى الصلاة المفروضة وغيرها.","وكان عمر بن الخطاب يجهر بهؤلاء الكلمات يقول: \"سبحانك اللهم وبحمدك، تبارك اسمك، وتعالى جَدُّك، ولا إله غيرك\". رواه مسلم في الصلاة (399) وتلقّاه العلماء بالقبول، والكلام عليه مبسوط في كتاب الصلاة."],"391":["قوله: وَمِنَ اللَّيْلِ فَسَبِّحْهُ أي: صَلِّ له في الليل، وهذا مثل قوله تعالى: وَمِنَ اللَّ﴿يْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ﴾","وقوله: وَإِدْبَارَ النُّجُومِ أي: عند جنوحها للغيبوبة، وهو الوقت الذي يصلى فيه الركعتان اللتان قبل صلاة الفجر، وهاتان الركعتان لهما فضل عظيم، وكان النبي صلى الله عليه وسلم يحرص عليهما أكثر من حرصه على غيرهما من النوافل."],"393":["أي: ما يقول النبي صلى الله عليه وسلم قولا عن هوى، وإنما يقول ما أمر به وأوحي إليه من الحق والهدى، وقد جاءت في ذلك أحاديث منها."],"395":["قوله: اللَّاتَ كان رجلا يلت السويق للحجاج، فلما مات عكفوا على قبره، فعبدوه."],"396":["أي: ليس الأمر تابعا لأمنية الإنسان، ولا كل من ودَّ شيئا حصل عليه، بل ذلك كله راجع إلى الله عز وجل، فبيده سبحانه الأمر كله، ولذلك ينبغي أن تكون أمنية الإنسان طيبة صالحة، خالية من الشرور والأهواء والمعاصي والآثام."],"398":["أي: المعرضون عن ذكر الله من الكفار والمشركين أكبر همهم ومبلغ علمهم وغاية سعيهم هو الدنيا، وأما المسلم فهو يدعو الله عز وجل أن لا يجعل الدنيا أكبر همه، ولا مبلغ علمه، كما أرشد إليه النبي صلى الله عليه وسلم."],"399":["قوله: ﴿الَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ إِلَّا اللَّمَمَ اللمم﴾ هو صغار المعصية كالنظرة والغمزة وما كان دون الزنا."],"402":["قوله: اقْتَرَبَتِ السَّاعَةُ أي: اقترب يوم القيامة، وقد جاءت أحاديث كثيرة تدل على قرب يوم القيامة، ومنها:"],"403":["قوله تعالى: وَلَقَدْ تَرَكْنَاهَا آيَةً فَهَلْ مِنْ مُدَّكِرٍ","وقال تعالى: ﴿فَإِذَا اسْتَوَيْتَ أَنْتَ وَمَنْ مَعَكَ عَلَى الْفُلْكِ فَقُلِ الْحَمْدُ لِلَّهِ الَّذِي نَجَّانَا مِنَ الْقَوْمِ الظَّالِمِينَ وَقُلْ رَبِّ أَنْزِلْنِي مُنْزَلًا مُبَارَكًا وَأَنْتَ خَيْرُ الْمُنْزِلِينَ إِنَّ فِي ذَلِكَ لَآيَاتٍ وَإِنْ كُنَّا لَمُبْتَلِينَ﴾ (30) [المؤمنون: ٢٨ – ٣٠]","وقال تعالى: ﴿فَأَنْجَيْنَاهُ وَأَصْحَابَ السَّفِينَةِ وَجَعَلْنَاهَا آيَةً لِلْعَالَمِينَ﴾ [سورة العنكبوت: ١٥]","وقال تعالى: ﴿فَأَنْجَيْنَاهُ وَمَنْ مَعَهُ فِي الْفُلْكِ الْمَشْحُونِ ثُمَّ أَغْرَقْنَا بَعْدُ الْبَاقِينَ إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُمْ مُؤْمِنِينَ﴾ (121) [الشعراء: ١١٩ – ١٢١]","إذا نظرنا إلى هذه الآيات الكريمة يظهر لنا جليا بأن صنع الفلك من الخشب، وكونه يجري في البحر مع أمواجه، وأن الله نجَّا نوحا ومن آمن معه من الغرق كل ذلك من آيات الله سبحانه وتعالى، لأنه يقول في موضع آخر: ﴿اللَّهُ الَّذِي سَخَّرَ لَكُمُ الْبَحْرَ لِتَجْرِيَ الْفُلْكُ فِيهِ بِأَمْرِهِ وَلِتَبْتَغُوا مِنْ فَضْلِهِ وَلَعَلَّكُمْ تَشْكُرُونَ وَسَخَّرَ لَكُمْ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ جَمِيعًا مِنْهُ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ﴾ (13) [الجاثية: ١٢-13]","وعلى هذا التفسير يكون معنى قوله تعالى: وَلَقَدْ تَرَكْنَاهَا آيَةً فَهَلْ مِنْ مُدَّكِرٍ، أي: جعلنا قصة نوح وصنع السفينة من الخشب وما حدث بعده كله آية من الله سبحانه لمن يأتي بعده.","وقد يكون معناه عند بعض أهل العلم بأن إبقاء السفينة نفسها على جبل جودي آية. وقد روي عن قتادة أنه قال: أبقى الله سفينة نوح حتى أدركها أوائل هذه الأمة.","ذكره البخاري معلقا عنه في كتاب التفسير عقب حديث رقم (4868)","وأخرجه عبد الرزاق في تفسيره (3062) والطبري في التفسير (22/128) كلاهما من طريق معمر عن قتادة، فذكره بنحوه، وزاد فيه: \"على الجودي\" بعد قوله: \"ألقى الله سفينة نوح\".","وأخرج ابن جرير (22/128) وابن أبي حاتم (10/3220) كلاهما من طريقين عن سعيد بن أبي عروبة، عن قتادة، قال: \"أبقاها الله بباقِردَى من أرض الجزيرة عبرة وآية حتى نظرت إليها أوائل هذه الأمة نظرا، وكم من سفينة كانت بعدها قد صارت رمادا\". وهذا لفظ الطبري، وليس عند ابن أبي حاتم قوله: \"بباقِردَى\".","والجزيرة: المقصود بها جزيرة ابن عمر، وهي مدينة كبيرة من أعمال الموصل، والجودي جبل عال مستطيل بالجزيرة في الجانب الشرقي من دجلة.","وجزيرة ابن عمر لا زالت معروفة باسمها هذا، مرسومة به على الخرائط الجغرافية الحديثة على الحدود الشمالية الشرقية السورية.","وهذه الجزيرة تم فتحها في عهد عمر بن الخطاب رضي الله عنه على يد عياض بن غنم.","انظر: معجم الأمكنة الوارد ذكرها في صحيح البخاري (ص: 143-145).","وقتادة سمع من بعض الصحابة، منهم أنس بن مالك وأبو الطفيل، فقوله: \"أدرك سفينة نوح أوائل هذه الأمة\" الظاهر من قوله أنه يقصد الصحابة، فلو كانت هذه القصة صحيحة لتواتر نقلها، كما تواتر نقل الطوفان، لأنها حادثة عظيمة وفيها عبرة لمن بعدهم.","وقتادة مدلس، فأخشى أنه سمع هذه القصة من بعض المجاهيل، ودلَّس فيها.","ولكن لا يمنع ذلك من انكشاف آثار السفينة فيما بعد، فقد تناقلت الصحف العالمية بأن جماعة من الباحثين وجدوا آثار السفينة في جبل الجودي قرب قرية باقردى.","فإن صح هذا فمعنى قوله تعالى: وَلَقَدْ تَرَكْنَاهَا آيَةً، أي: أبقيناها زمنا بعد نوح للعبرة، ولكن ليس فيه دليل أنه يبقى إلى يوم القيامة، ولذا حمل الآية على قصة نوح من كونه صنع سفينة من خشب وأبحرها بحكم الله تعالى، وأن الله نَجَّاهم من الطوفان الذي أغرق كل شيء حي على كرة الأرض أولى من حملها على السفينة نفسها، والله تعالى أعلم.","وقوله: فَهَلْ مِنْ مُدَّكِرٍ"],"404":["هذه الآية مكية، فيها إخبار من الله تعالى أن الجمع سيولون الدبر، فحقق الله هذا الوعد يوم بدر، كما في الحديث الآتي:"],"411":["قوله: كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ أي كل يوم تظهر لخلائقه مظاهر قدرته وعظمته."],"412":["أي: تنشق السماء يوم القيامة، وتتلون كما تتلون الأصباغ التي يدهن بها، فتارة حمراء، وتارة صفراء، وتارة زرقاء، وتارة خضراء، وذلك من شدة الأمر وهول يوم القيامة."],"414":["أي: أغصان أشجار الجنة نضرة حسنة واسعة، تحمل من كل ثمرة نضيجة فائقة."],"415":["قوله: ﴿وَجَنَى الْجَنَّتَيْنِ دَانٍ أي ثمرها قريب إليهم، يتناولونه متى شاؤوا، قال تعالى: قُطُوفُهَا دَانِيَةٌ [الحاقة: ٢٣] وقال تعالى: وَدَانِيَةً عَلَيْهِمْ ظِلَالُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا﴾ [سورة الإنسان: ١٤]"],"416":["أي: في صفائهن وبياضهن وجمالهن وبهائهن، فنساء أهل الجنة يكن في غاية الحسن والجمال والبهاء، وقد جاءت في ذلك أحاديث، منها."],"417":["أي: هاتان الجنتان دون اللتين في الفضيلة والمنزلة، والجنتان الأوليان تكونان من الذهب، والأخريان تكونان من الفضة، كما جاء في الصحيح."],"419":["أي: هو أهل أن يُجَلَّ ويُكْرَم ويُعَظَّم، وفيُذكر ويُشْكَر ويُعْبَد، وقد أمر النبي صلى الله عليه وسلم الداعي أن يُكْثِرَ في دعائـه من قـول: ((يا ذا الجلال والإكرام)) كان النبي صلى الله عليه وسلم يقولها بعد الصلوات، كما في الصحيح."],"421":["أي حركت تحريكا شديدا، فاهتزت واضطربت بكاملها، وهذا كقوله تعالى: ﴿إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا﴾ [الزلزلة: ١]"],"422":["أي يشتهون يقال: \"تخيرت الشيء\" إذا أخذت خيره."],"425":["قوله: فَجَعَلْنَاهُنَّ أَبْكَارًا الضمير عائد إلى غير المذكور، وهو بيان لما يخطر في البال عن صفات الرفيقات فقال: أَبْكَارًا أي: أن بكارتهن تستمر، ولا تنتهي، وهي شاملة لأزواجهم والحور العين.","وقوله: عُرُبًا أَتْرَابًا العُرب جمع عروب وهي صفة خاصة بالمرأة ويقال في تفسيرها: المرأة المتحببة إلى الرجل بصفاتها الجميلة. أَتْرَابًا مستويات في السن، على سِنٍّ واحدٍ. انظر: صفة أهل الجنة."],"426":["أي: جماعة من الأولين، وجماعة من الآخرين، ويكون شطر أهل الجنة من هذه الأمة، كما جاء في الحديث."],"427":["قوله: أَمْ نَحْنُ الزَّارِعُونَ قصر الزرع على الله تعالى المراد منه الإنبات لأن نسبة الزرع إلى غير الله ثابت في كتاب الله. فقوله: أَمْ نَحْنُ الزَّارِعُونَ أي نحن المنبتون.","أما ما روي عن أبي هريرة قال: قال رسول الله صلى الله عليه وسلم: ((لا يقولن أحدكم: زرعت ولكن ليقل: حرثت)) قال أبو هريرة: ألم تسمع إلى قول الله تبارك وتعالى: أَفَرَأَ﴿يْتُمْ مَا تَحْرُثُونَ أَأَنْتُمْ تَزْرَعُونَهُ أَمْ نَحْنُ الزَّارِعُونَ﴾ (64) ففيه نكارة.","رواه البزار (10064) وابن حبان (5723) والبيهقي في الكبرى (6/138) كلهم من طريق مسلم بن أبي مسلم الجرمي، قال: حدثنا مخلد بن حسين، عن هشام بن حسان، عن محمد بن سيرين، عن أبي هريرة، قال: فذكره.","وفي الإسناد مسلم بن أبي مسلم الجرمي، توفي سنة 240هـ، ولم أجد توثيقه عند أحد من الأئمة المتقدمين، وإنما ذكره ابن حبان في الثقات على قاعدته، وقال: \"ربما أخطأ\"، وكذلك وثَّقه الخطيب في تاريخه (13/100)، ولكنه لم يعز توثيقه إلى أحد من الأئمة السابقين.","قال البيهقي بعد أن رواه عن مجاهد قال: لا تقل: زرعتُ، ولكن قل: حرثتُ، إن الله هو الزارع، وقد رُويَ فيه حديث مرفوع غير قوي، ثم ساق حديث أبي هريرة من طريق مسلم الجرمي بإسناده.","وقال ابن حجر في الفتح (5/4) في شرح حديث أنس مرفوعا الآتي ذكرُه: ما من مسلمٍ يغرس غرسًا أو يزرع زرعًا...: \"فيه جواز نسبة الزرع إلى الآدمي، وقد وردَ في المنع منه حديث غير قوي ثم ساق حديث أبي هريرة، وحمل الخطأ على مسلم بن أبي مسلم الجرمي، ونقل فيه قول ابن حبان: ربما أخطأ\" اهـ.","قلت: فإنه أخطأ في نسبة هذا القول إلى رسول الله صلى الله عليه وسلم، وهو قول أحد الرواة مثل مجاهد أو غيره.","والحديث في متنه نكارة، فقد جاء نسبة الزرع إلى غير الله في نصوص كثيرة، منها: قوله في التنزيل في قصة يوسف عليه السلام: ﴿قَالَ تَزْرَعُونَ سَبْعَ سِنِينَ دَأَبًا﴾ [يوسف: ٤٧]"],"428":["قوله: نَحْنُ جَعَلْنَاهَا تَذْكِرَةً أي: أنها تذكر بالنار الكبرى، وقد جاء في الصحيح."],"430":["قوله: فَرَوْحٌ بفتح الراء، وهي قراءة الجمهور، ومعناها الفرح والراحة.","وقرأه رويس (هو محمد بن المتوكل ت 238هـ أحد القراء عن يعقوب) بضم الراء، أي: فَرُوْحٌ ومعناها الحياة والبقاء. وهذه القراءة أيضا متواترة."],"431":["أي: سَبِّح الله عز وجل بأسمائه الحسنى، وقد جاءت أحاديث كثيرة، تحث على تسبيح الرب تعالى وتقديسه وتعظيمه، منها."],"433":["يخبر الله تعالى أن كل ما في السماوات من السيارات والكواكب والحيوانات، وكذلك كل ما في الأرض من الحيوانات والجمادات يسبحن الله تعالى، كما قال تعالى: تُسَبِّحُ لَهُ السَّمَاوَاتُ ﴿السَّبْعُ وَالْأَرْضُ وَمَنْ فِيهِنَّ وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ وَلَكِنْ لَا تَفْقَهُونَ تَسْبِيحَهُمْ إِنَّهُ كَانَ حَلِيمًا غَفُورًا﴾ [الإسراء: 44]"],"434":["قوله: هُوَ الْأَوَّلُ يعني كان هو ولم يكن شيء موجودا.","قوله: وَالْآخِرُ بعد فناء كل شيء بلا انتهاء، تفنى الأشياء ويبقى هو.","قوله: وَالظَّاهِرُ الغالب العالي على كل شيء.","قوله: وَالْبَاطِنُ العالم بكل شيء كما قال ابن عباس. يقال: سأل عمر بن الخطاب كعبا عن هذه الآية فقال: إن علمه بالأول لعلمه بالآخر، وعلمه بالظاهر لعلمه بالباطن."],"435":["قوله: سِتَّةِ أَيَّامٍ","هي: الأحد والاثنين، والثلاثاء، والأربعاء، والخميس، والجمعة، وفيه تم الخلق كله. وأما يوم السبت فلم يقع فيه خلق، والسبت معناه القطع، أي: انقطع فيه التخليق.","وأما ما روي عن أبي هريرة قال: أخذ رسول الله صلى الله عليه وسلم بيدي فقال: ((خلق الله عز وجل التربة يوم السبت، وخلق فيها الجبال يوم الأحد، وخلق الشجر يوم الاثنين، وخلق المكروه يوم الثلاثاء، وخلق النور يوم الأربعاء، وبث فيها الدواب يوم الخميس، وخلق آدم عليه السلام بعد العصر من يوم الجمعة في آخر الخلق في آخر ساعة من ساعات الجمعة فيما بين العصر إلى الليل)).","رواه مسلم في صفة القيامة (2789) ففيه كلام، وقد سبق وهو مخالف للقرآن.","وقوله: ﴿ثُمَّ اسْتَوَى عَلَى الْعَرْشِ يسلك﴾ في هذا المقام مذهب السلف الصالح، مالك والشافعي وأحمد وإسحاق وغيرهم. وهو إمرارها كما جاءت من غير تكييف، ولا تشبيه، ولا تعطيل.","روي عن نعيم بن حماد شيخ البخاري: ((من شبَّه الله بخلقه فقد كفر، ومن جحد ما وصف الله به نفسه فقد كفر))","وقد بسطت الكلام على ذلك في كتاب الإيمان فأغنى عن الإعادة.","وقوله: ﴿وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ﴾ أي: أنتم لا تخرجون من إحاطته."],"436":["يعاتب الله تعالى المؤمنين في هذه الآية ويحذرهم بأنه إذا طال عليهم الزمان، ولم يتعظوا بذكر الله، فإن قلوبهم تكون مثل قلوب أهل الكتاب قلوبا قاسية لا تقبل الموعظة، ولا تلين بوعد، ولا وعيد."],"437":["قال ابن مسعود في قوله تعالى: ﴿أُولَئِكَ هُمُ الصِّدِّيقُونَ وَالشُّهَدَاءُ عِنْدَ رَبِّهِمْ﴾ قال: هم ثلاثة أصناف: يعني المصدقين والصديقين والشهداء. كما قال تعالى: ﴿وَمَنْ يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ﴾ [النساء: ٦٩] والصديق أعلى مقاما من الشهيد، كما جاء في الحديث الصحيح."],"440":["قوله: نُهُوا عَنِ النَّجْوَى هم اليهود، لأن نجواهم كانت بالإثم والعدوان، فلم ينتهوا بل استمروا على نجواهم.","وقوله: ﴿حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ اللَّهُ﴾ أي: إذا حيوا النبي صلى الله عليه وسلم فقالوا: السام عليك يا أبا القاسم، والسام هو الموت، وقد جاء في الصحيح."],"441":["وذلك لتطهير قلوبكم، وتزكية نفوسكم؛ لأنكم تناجون النبي المصطفى صلى الله عليه وسلم، فإن مقامه أعلى وأرفع من أن تناجوه وتطلبون منه التفاته إليكم من دونكم.","يقال: لم يعمل على هذه الآية قبل نسخها إلا علي بن أبي طالب، لمقام ابنتهصلى الله عليه وسلم عنده، روي عن مجاهد قال: قال علي بن أبي طالب: آية في كتاب الله عز وجل لم يعمل بها أحد قبلي، ولا يعمل بها أحد بعدي، كان عندي دينار، فصرفته بعشر دراهم، فكنت إذا ناجيت رسول الله صلى الله عليه وسلم تصدقت بدرهم، فنسخت، ولم يعمل بها أحد قبلي، ولا يعمل بها أحد بعدي. ثم تلا هذه الآية: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نَاجَيْتُمُ الرَّسُولَ فَقَدِّمُوا بَيْنَ يَدَيْ نَجْوَاكُمْ صَدَقَةً﴾"],"443":["قوله: ﴿اسْتَحْوَذَ عَلَيْهِمُ الشَّيْطَانُ فَأَنْسَاهُمْ ذِكْرَ اللَّهِ أي﴾ غلب عليهم الشيطان حتى أنساهم أن يذكروا الله عز وجل، وكذلك يفعل الشيطان بمن يستحوذ عليهم، ومن أسباب غلبة الشيطان واستحواذه على الناس تركهم الأذان والصلاة مع الجماعة إذا كانوا في قرية، كما في الحديث."],"446":["قوله: وَمَا آتَاكُ﴿مُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا﴾"],"447":["قوله: وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ هم الأنصار."],"448":["أي المؤمنون الذين جاؤوا بعد المهاجرين والأنصار يستغفرون الله لأنفسهم ولإخوانهم المؤمنين الذين كانوا قبلهم، ويدعون الله تعالى أن لا يجعل في قلوبهم غلا –وهو الحقد والحسد- لإخوانهم المؤمنين."],"449":["قوله: ﴿وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ﴾ أي: لينظر كل واحد منكم ما الذي ادخره لنفسه من الأعمال الصالحة ليوم القيامة، وقد جاء في الصحيح."],"450":["قوله: هَذَا الْقُرْآنَ أي مقدار ما نزل من القرآن.","وقوله: ﴿لَرَأَيْتَهُ خَاشِعًا مُتَصَدِّعًا مِنْ خَشْيَةِ اللَّهِ﴾ أي لو كان المخاطب بالقرآن جبلا وهو يفهم الخطاب لتأثر من هذا الخطاب خاشعا لله مع صلابته، ولكن الكافر يعرض عليه القرآن فلا يتعظ به، وكأنه لم يسمعه لقساوة قلبه قال تعالى: ﴿وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ﴾ والتصدع هو: التشقق. أي لتزلزل وتشقق من خوف الله تعالى."],"454":["قوله: ﴿لَنْ تَنْفَعَكُمْ أَرْحَامُكُمْ وَلَا أَوْلَادُكُمْ﴾ أي: قراباتكم مع شرككم وكفركم لا تنفعكم عند الله، ولا تغني عنكم من الله شيئا."],"457":["فكان النبي صلى الله عليه وسلم يبايع من جاء إليه مهاجرا رجالا ونساء على هذه ونحوها."],"461":["قوله: ﴿وَإِذْ قَالَ مُوسَى لِقَوْمِهِ يَا قَوْمِ لِمَ تُؤْذُونَنِي﴾ أي: إن موسى عليه السلام أوذي كثيرا لما كان في التيه.","قال تعالى: وَإِذْ وَاعَ﴿دْنَا مُوسَى أَرْبَعِينَ لَيْلَةً ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِهِ وَأَنْتُمْ ظَالِمُونَ ثُمَّ عَفَوْنَا عَنْكُمْ مِنْ بَعْدِ ذَلِكَ لَعَلَّكُمْ تَشْكُرُونَ وَإِذْ آتَيْنَا مُوسَى الْكِتَابَ وَالْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ وَإِذْ قَالَ مُوسَى لِقَوْمِهِ يَا قَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنْفُسَكُمْ بِاتِّخَاذِكُمُ الْعِجْلَ فَتُوبُوا إِلَى بَارِئِكُمْ فَاقْتُلُوا أَنْفُسَكُمْ ذَلِكُمْ خَيْرٌ لَكُمْ عِنْدَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ وَإِذْ قُلْتُمْ يَا مُوسَى لَنْ نُؤْمِنَ لَكَ حَتَّى نَرَى اللَّهَ جَهْرَةً فَأَخَذَتْكُمُ الصَّاعِقَةُ وَأَنْتُمْ تَنْظُرُونَ ثُمَّ بَعَثْنَاكُمْ مِنْ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ﴾ (56) [البقرة:٥١-٥٦]","وقال تعالى: ﴿وَإِذْ قَالَ مُوسَى لِقَوْمِهِ إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً قَالُوا أَتَتَّخِذُنَا هُزُوًا قَالَ أَعُوذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَنَا مَا هِيَ قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ لَا فَارِضٌ وَلَا بِكْرٌ عَوَانٌ بَيْنَ ذَلِكَ فَافْعَلُوا مَا تُؤْمَرُونَ قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَنَا مَا لَوْنُهَا قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَاءُ فَاقِعٌ لَوْنُهَا تَسُرُّ النَّاظِرِينَ قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّنْ لَنَا مَا هِيَ إِنَّ الْبَقَرَ تَشَابَهَ عَلَيْنَا وَإِنَّا إِنْ شَاءَ اللَّهُ لَمُهْتَدُونَ قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ لَا ذَلُولٌ تُثِيرُ الْأَرْضَ وَلَا تَسْقِي الْحَرْثَ مُسَلَّمَةٌ لَا شِيَةَ فِيهَا قَالُوا الْآنَ جِئْتَ بِالْحَقِّ فَذَبَحُوهَا وَمَا كَادُوا يَفْعَلُونَ وَإِذْ قَتَلْتُمْ نَفْسًا فَادَّارَأْتُمْ فِيهَا وَاللَّهُ مُخْرِجٌ مَا كُنْتُمْ تَكْتُمُونَ فَقُلْنَا اضْرِبُوهُ بِبَعْضِهَا كَذَلِكَ يُحْيِ اللَّهُ الْمَوْتَى وَيُرِيكُمْ آيَاتِهِ لَعَلَّكُمْ تَعْقِلُونَ﴾ (73) [البقرة:٦٧-٧٣]","وقال تعالى: ﴿وَلَقَدْ جَاءَكُمْ مُوسَى بِالْبَيِّنَاتِ ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِهِ وَأَنْتُمْ ظَالِمُونَ وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُمْ بِقُوَّةٍ وَاسْمَعُوا قَالُوا سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا فِي قُلُوبِهِمُ الْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَمَا يَأْمُرُكُمْ بِهِ إِيمَانُكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ﴾ (93) [البقرة:٩٢-٩٣]","وقال تعالى: ﴿وَإِذْ قَالَ مُوسَى لِقَوْمِهِ يَا قَوْمِ اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَعَلَ فِيكُمْ أَنْبِيَاءَ وَجَعَلَكُمْ مُلُوكًا وَآتَاكُمْ مَا لَمْ يُؤْتِ أَحَدًا مِنَ الْعَالَمِينَ يَا قَوْمِ ادْخُلُوا الْأَرْضَ الْمُقَدَّسَةَ الَّتِي كَتَبَ اللَّهُ لَكُمْ وَلَا تَرْتَدُّوا عَلَى أَدْبَارِكُمْ فَتَنْقَلِبُوا خَاسِرِينَ قَالُوا يَا مُوسَى إِنَّ فِيهَا قَوْمًا جَبَّارِينَ وَإِنَّا لَنْ نَدْخُلَهَا حَتَّى يَخْرُجُوا مِنْهَا فَإِنْ يَخْرُجُوا مِنْهَا فَإِنَّا دَاخِلُونَ قَالَ رَجُلَانِ مِنَ الَّذِينَ يَخَافُونَ أَنْعَمَ اللَّهُ عَلَيْهِمَا ادْخُلُوا عَلَيْهِمُ الْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّكُمْ غَالِبُونَ وَعَلَى اللَّهِ فَتَوَكَّلُوا إِنْ كُنْتُمْ مُؤْمِنِينَ قَالُوا يَا مُوسَى إِنَّا لَنْ نَدْخُلَهَا أَبَدًا مَا دَامُوا فِيهَا فَاذْهَبْ أَنْتَ وَرَبُّكَ فَقَاتِلَا إِنَّا هَاهُنَا قَاعِدُونَ قَالَ رَبِّ إِنِّي لَا أَمْلِكُ إِلَّا نَفْسِي وَأَخِي فَافْرُقْ بَيْنَنَا وَبَيْنَ الْقَوْمِ الْفَاسِقِينَ قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيْهِمْ أَرْبَعِينَ سَنَةً يَتِيهُونَ فِي الْأَرْضِ فَلَا تَأْسَ عَلَى الْقَوْمِ الْفَاسِقِينَ﴾ (26) [المائدة:٢٠-٢٦] وغيرها من الآيات الكثيرة التي تدل على أن بني إسرائيل لما كانوا في التيه لم يكونوا مستجيبين تمام الاستجابة كما هو شأن المؤمنين مع أنبيائهم، وأنهم كانوا يؤذونه كثيرا.","وكذلك أوذي النبي صلى الله عليه وسلم كثيرا، وهذا أمر مشهور، وقد جاء في الصحيح."],"462":["قوله: ﴿وَإِذْ قَالَ عِيسَى ابْنُ مَرْيَمَ يَا بَنِي إِسْرَائِيلَ إِنِّي رَسُولُ اللَّهِ إِلَيْكُمْ﴾ أي: أن عيسى عليه السلام كان نبيا من أنبياء بني إسرائيل، وكان مرسلا إليهم، ودعوته كانت خاصة بهم، ولم تكن عالمية كما يدعيها النصارى.","وقوله: ﴿وَمُبَشِّرًا بِرَسُولٍ يَأْتِي مِنْ بَعْدِي اسْمُهُ أَحْمَدُ﴾ أي: أن عيسى عليه السلام بشر بعده برسالة نبينا محمد بن عبد الله بن عبد المطلب الهاشمي، وأحمد اسم من أسماء النبي صلى الله عليه وسلم.","وقد جاء اسم النبي صلى الله عليه وسلم على لسان عيسى عليه السلام صراحة في إنجيل برناباس."],"463":["روي عن ابن عباس قال: لما أراد الله أن يرفع عيسى إلى السماء خرج إلى أصحابه -وهم في بيت اثنا عشر رجلا- من عين في البيت ورأسه يقطر ماء؛ قال: فقال: إن منكم من سيكفر بي اثنتي عشرة مرة بعد أن آمن بي؛ قال: ثم قال: أيكم يلقى عليه شبهي فيقتل مكاني، ويكون معي في درجتي؟ قال: فقام شاب من أحدثهم سنا، قال: فقال أنا، فقال له: اجلس؛ ثم أعاد عليهم، فقام الشاب، فقال: أنا؛ قال: نعم أنت ذاك؛ فألقي عليه شبه عيسى، ورفع عيسى من روزنة في البيت إلى السماء؛ قال: وجاء الطلب من اليهود، وأخذوا شبهه. فقتلوه وصلبوه، وكفر به بعضهم اثنتي عشرة مرة بعد أن آمن به، فتفرقوا ثلاث فرق، فقالت فرقة: كان الله فينا ما شاء، ثم صعد إلى السماء، وهؤلاء اليعقوبية.","وقالت فرقة: كان فينا ابن الله ما شاء الله، ثم رفعه إليه، وهؤلاء النسطورية. وقالت فرقة: كان فينا عبد الله ورسوله ما شاء الله، ثم رفعه الله إليه، وهؤلاء المسلمون، فتظاهرت الطائفتان الكافرتان على المسلمة، فقتلوها، فلم يزل الإسلام طامسا حتى بعث الله محمدا صلى الله عليه وسلم. فَآمَنَتْ طَائِفَةٌ من بني إسرائيل، وَكَفَرَتْ طَائِفَةٌ يعني الطائفة التي كفرت من بني إسرائيل في زمن عيسى، والطائفة التي آمنت في زمن عيسى، ﴿فَأَيَّدْنَا الَّذِينَ آمَنُوا عَلَى عَدُوِّهِمْ فَأَصْبَحُوا ظَاهِرِينَ﴾ في إظهار محمد على دينهم دين الكفار، فأصبحوا ظاهرين.","رواه النسائي في الكبرى (11527) وابن جرير في تفسيره (22/622-623) والمقدسي في المختارة (402) كلهم من طريق أبي معاوية، عن الأعمش، عن المنهال بن عمرو، عن سعيد بن جبير، عن ابن عباس، قال: فذكره.","وإسناده حسن من أجل المنهال بن عمرو فإنه حسن الحديث.","ولكن حسب الرواية المشهورة عند أهل الكتاب أن الجنود الروم هم الذين كانوا يبحثون عن عيسى عليه السلام، وهم الذين جاؤوا للقبض عليه، وليس اليهود كما جاء في هذه الرواية، وأن يهوذا الإسخريوطي الذي شبه عليه كان قد تواطأ مع جنود الروم، وكان خائنا، وليس كما جاء في هذه الرواية، وقد بينت ذلك في كتابي: \"دراسات في اليهودية والمسيحية وأديان الهند\" وجاء فيه:","\"لم يرض اليهود بدعوة المسيح، فأغروا عليه الحاكم الروماني واتهموه بأنه يريد أن يرث ملك داود حتى صدر المرسوم الامبراطوري للقبض عليه وإعدامه، فبدأ الجنود الروم يبحثون عنه، حتى تمكنوا من الوصول إليه، ولكن الله ألقى شبهه على يهوذا الإسخريوطي الذي تقول الأناجيل إنه هو الذي دسَّ عليه.","وإليكم ما جاء في إنجيل برنابا في هذا الصدد:","\"ولما دنت الجنود مع يهوذا من المحل الذي كان فيه يسوع، سمع يسوع دنو الجمهور الغفير، فلذلك انسحب الى البيت خائفا، وكان الأحد عشر نياما، فلما رأى الله الخطر على عبده، أمر جبريل وميخائيل وروفائيل وأوريل سفراءه أن يأخذوا يسوع من العالم، فجاء الملائكة الأطهار، وأخذوا يسوع من النافذة المشرفة على الجنوب، فحملوه ووضعوه في السماء الثالثة في صحبة الملائكة التي تسبح الله الى الأبد. ودخل يهوذا بعنف إلي الغرفة التي أصعد منها يسوع، وكان التلاميذ كلهم نياما، فأتى الله العجيب بأمر عجيب، فتغير يهوذا في النطق وفي الوجه، فصار شبها بيسوع، حتى إننا اعتقدنا أنه يسوع.","أما هو فبعد أن أيقظنا أخذ يفتش لينظر أين كان المعلم، لذلك تعجبنا وأجبنا: أنت يا سيد هو معلمنا، أنسيتنا الآن؟، أما هو فقال متبسما: هل أنتم أغبياء حتى لا تعرفوا يهوذا الإسخريوطي. وبينما كان يقول هذا، دخلت الجنود، وألقوا أيديهم على يهوذا الإسخريوطي، لأنه كان شبيها بيسوع من كل وجه\". الفصل الخامس عشر بعد المائتين، والسادس عشر بعد المائتين.","وفي الأناجيل المزعومة إشارة إلى إلقاء شبه عيسى على شخص آخر، فإن الجميع قالوا: \"هل هو أم لا؟ فقال لهم يسوع: كلكم تشكون في هذه الليلة\".","هكذا تجلت قدرة الله، وامتدت يد العناية إلى رسول الله، فأخفاه ربه عن أعين الناظرين، ووقع يهوذا الخائن بأيديهم، فتملكته الدهشة، فلم يستطع الدفاع عن نفسه، والإعلان عن حقيقة أمره، فاستاقوه إلى ساحة القتل، بين الصخب والضجيج، والفرح والتهليل، ومكروا، ومكر الله، والله خير الماكرين، فصلبوه بعد أن جلدوه، وهم يظنون أنهم صلبوا المسيح ﴿وَقَوْلِهِمْ إِنَّا قَتَلْنَا الْمَسِيحَ عِيسَى ابْنَ مَرْيَمَ رَسُولَ اللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَكِنْ شُبِّهَ لَهُمْ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِيهِ لَفِي شَكٍّ مِنْهُ مَا لَهُمْ بِهِ مِنْ عِلْمٍ إِلَّا اتِّبَاعَ الظَّنِّ وَمَا قَتَلُوهُ يَقِينًا بَلْ رَفَعَهُ اللَّهُ إِلَيْهِ وَكَانَ اللَّهُ عَزِيزًا حَكِيمًا﴾ (158) [سورة النساء: ١٥٧ - 158]."],"465":["قوله: الْأُمِّيِّينَ يعني العرب كانت أمة أمية لا تكتب ولا تقرأ.","وقال بعض أهل العلم: ﴿فِي الْأُمِّيِّينَ أي: في غير بني إسرائيل لأنهم كانوا يسمون غيرهم أميين تنقيصا لهم كما حكى الله عنهم قولهم: لَيْسَ عَلَيْنَا فِي الْأُمِّيِّينَ سَبِيلٌ﴾ [سورة آل عمران: ٧٥]","وقوله: وَآخَرِينَ مِنْهُمْ أي: جميع من دخل في الإسلام بعد النبي صلى الله عليه وسلم إلى يوم القيامة، وقد خص النبي صلى الله عليه وسلم منهم العجم، كما جاء في الأحاديث الصحيحة."],"466":["افتخر اليهود بأنهم أهل كتاب، والعرب لا كتاب لهم، فأبطل الله ذلك بتشبيههم بالحمار يحمل أسفارا دون علم وفهم. وقوله: حُمِّلُوا أي كلفوا بما فيها، فلم يفوا بما كلفوا به مثل عدم اتباعهم النبي الذي يأتي لتخليصهم من ربقة الضلال كما حرفوا التوراة حسب أهوائهم وأدخلوا فيها ضلالاتهم. فقوله تعالى: ثُمَّ لَمْ يَحْمِلُوهَا أي فيه دلالة واضحة أنهم لم يقوموا بما يجب نحو كتابهم التوراة."],"467":["أمر الله رسوله صلى الله عليه وسلم أن يقول لليهود: إن كنتم صادقين في زعمكم أنكم على الحق والهدى، وأنكم أولياء الله دون النبي صلى الله عليه وسلم وأصحابه، فتمنوا الموت ولكنهم لعلمهم أنهم على الباطل لا يتمنون الموت أبدا، ولو أنهم قبلوا هذا التحدي وتمنوا الموت لماتوا، ولرأوا مقاعدهم من النار، كما جاء في الحديث."],"468":["لقد أوجب الله تعالى صلاة الجمعة على المسلمين شكرا له إذْ هدانا إليها، وجعل لنا هذا اليوم عيدا كما لكل قوم عيد، وشرع فيه الخطبة تذكيرا لهذا الأمر العظيم، وجعل الخطبتين مقام الركعتين من أربع ركعات الظهر، ولذا أمر الإمام أن يخطب قائما كما يصلي قائما، ونهاه أن يطيل الخطبة كما نهاه أن يطيل الصلاة، وشرع له أن يجلس بين الخطبتين جلسة خفيفة كما يجلس بين الركعتين.","إلا أن من فاتتْه الخطبة وكذا من فاتته ركعة من ركعتي صلاة الجمعة فعليه أن يتم الركعة الثانية فقط على رأي الجمهور.","ورويَ عن عطاء ومجاهد وطاوس: أن من فاتتْه الخطبة يوم الجمعة صلى أربعا صلاة الظهر، وعن عطاء: أن من أدرك ركعة من صلاة الجمعة أضاف إليها ثلاث ركعات إلا أنه قول مرجوح.","وقد جاءت أحاديث كثيرة لبيان فضل يوم الجمعة ولبيان أحكام صلاة الجمعة وآدابها، منها."],"472":["زعم عبد الله بن أُبَيّ ابن سلول أنه هو وإخوانه من المنافقين هم الأعزون، وأن رسول الله صلى الله عليه وسلم وأصحابه هم الأذلون، وليس الأمر كما زعم هذا المنافق، بل بالعكس، ولهذا رد الله عليه مقالته وقال: ﴿وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ﴾ أي إنْ كان الأعز يخرج الأذل فإن المؤمنين هم الأعز لأن الرسول فيهم، وأن الله يؤيد أولياءه فالعزة لله ولرسوله وللمؤمنين ولكن المنافقين لا يعلمون لجهلهم وعداوتهم للمسلمين."],"473":["يعني عند رؤية ملك الموت لا تقبل الأعمال الصالحة، و قد جاء في الحديث."],"475":["جملة القول فيه: أن اللهَ خلقَ الكافرَ، وكُفْرُ الكافرِ من إرادته واختياره وقدرته عليه، وخلقَ اللهُ المؤمنَ، وإيمانُ المؤمنِ من إرادته واختياره وقدرته عليه، فلكل واحدٍ من الفريقين إرادة وقدرة واختيار، وكل ذلك يكون بتقدير الله عز وجل ومشيئته، فالمؤمن بعد خلق الله إياه يختار الإيمان والطاعة، والله تعالى قد علم ذلك منه فقدره عليه، والكافر بعد خلق الله تعالى إياه يختار الكفر، والله تعالى قد علم ذلك منه فقدره عليه، وإرادة العبد واختياره لا تخرج عن إرادة الله الكونية، وهذا هو مسلك أهل السنة والجماعة، ومن سلكه أصاب الحق، وسلِمَ من الجبر والقدر. والله الموفق."],"476":["قوله: إِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ أي: ابتلاء واختبار، وشغل عن الآخرة."],"477":["أي: مهما أنفقتم في سبيل الله وتصدقتم فإن الله عز وجل يخلفه لكم ويجزيكم عليه أوفر الجزاء، ولا ينقص من أجركم شيئا، ولا يظلمكم البتة، وقد جاء في الصحيح."],"480":["قوله: ﴿وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ﴾ أي: أشهدوا على الرجعة إذا عزمتم عليها."],"481":["قوله: وَأُولَاتُ ﴿الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ﴾"],"482":["قوله: خَلَقَ سَبْعَ سَمَاوَاتٍ أي سبع سماوات طباقا كما في سورة الملك (3) أي بعضها فوق بعض.","وقوله: وَمِنَ الْأَرْضِ مِثْلَهُنَّ أي: مثل عدد السماء، وهو رأي جمهور المفسرين فقالوا: إن الأرض سبع طبقات بعضها فوق بعض كالسماء، وقد اكتشف علماء طبقات الأرض هذه الحقيقة بعد ألف وأربعمائة سنة، وهذا المعنى يؤيده ما جاء في الصحيح:"],"484":["ذُكِرَتْ في أسباب نزول هذه الآيات أحاديث، وأصحُّها شرب العسل عند زينب."],"487":["قوله: تَوْبَةً نَصُوحًا هو أن يتوب ثم لا يعود إلى الذنب كما لا يعود اللبن إلى الضرع. قاله عمر، وأبي بن كعب.","قال القرطبي: يجمعها أربعة أشياء: الاستغفار باللسان، والإقلاع بالأبدان، وإضمار ترك العود بالجنان، ومهاجرة سيء الإخوان. ذكره البغوي في تفسيره (4/431)."],"488":["قوله: فَخَانَتَاهُمَا قال ابن عباس: \"ما بَغَتْ امرأةُ نبي قط، وإنما كانت خيانتهما أنهما كانتا على غير دينهما، فكانت امرأة نوح تقول للناس: إنه مجنون، وأما إمرأة لوط فإنها كانت تدلُّ قومه على أضيافه، إذا نزل به ضيفٌ في الليل أوقدت النار، وإذا نزل بالنهار دخّنت ليعلم قومه أنه نزل به ضيفٌ لعمل السوء.","وقال الكلبي: \"أسرّتا النفاق، وأظهرتا الإيمان\". هذا مما ذكره البغوي في تفسيره.","قوله: امْرَأَتَ فِرْعَوْنَ اسمها آسية بنت مزاحم، آمنت بالله، وكفرت بفرعون، وهي من أفضل نساء أهل الجنة، كما جاء في الصحيح."],"491":["قوله: ﴿إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ﴾ أي: إنهم يخافون الله عز وجل في السر والعلانية وفي جميع أحوالهم، فيمتثلون أوامر الله تعالى، ويجتنبون نواهيه حتى في الأحوال التي يخلون فيها بأنفسهم، ولا يطلع عليهم فيها إلا الله عز وجل، وتفيض أعينهم فيها بالدمع خوفا من الله تعالى، وقد امتدحهم النبي صلى الله عليه وسلم وأخبر أنهم من السبعة الذين يظلهم الله في ظله يوم لا ظل إلا ظله، كما جاء في الصحيح."],"492":["قوله: ﴿جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا﴾ أي: سخَّرها وذلَّلها وجعلها سهلة الاستفادة لكم، فأنتم مع شدتها وصلابتها ومع ما فيها من الجبال والبحار تنتفعون بها، وتدركون منها كل ما تعلقت به حاجتكم من الزراعة والحرث والغرس والحفر والعمارة والبناء وتمهيد السبل وإنشاء الطرق وغيرها من أنواع الحاجة وطرق الاستفادة.","وقوله: ﴿فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِنْ رِزْقِهِ﴾ أي: سافروا في أقطارها وأرجائها من أجل المكاسب والتجارات، واطلبوا فضل الله عز وجل ورزقه بذلك، وكلوا مما رزقكم الله عز وجل، والسعي للرزق لا ينافي التوكل على الله عز وجل، كما جاء في الحديث."],"493":["معناه: أرأيتم إنْ أهلكني الله فعذّبني ومن معي، أو رحمنا فغفر لنا، فنحن مع إيماننا خائفون أن يهلكنا بذنوبنا لأن حكمه نافذ فينا فمن يجيركم ويمنعكم من عذابه، وأنتم كافرون. كذا فسّره ابن عباس.","لأن من وقاحة المشركين أن يجهروا بتمني هلاك رسول الله صلى الله عليه وسلم ومن معه من المسلمين، بل كانوا تآمروا على قتله صلى الله عليه وسلم، ولكن الله تعالى أبطل حيلهم، وعصمه من مكرهم."],"495":["هذا ثناء من الله عز وجل على حسن خلق النبي صلى الله عليه وسلم، فقد كان أحسن الناس خلقا، وكان جامعا لجميع صفات الخير وخصال البر التي أمر الله بها عباده في القرآن الكريم ومدحهم عليها، وكان بعيدا عن جميع صفات الذم التي حذر الله منها عباده في القرآن الكريم وتوعَّدهم عليها، فقد كان صلى الله عليه وسلم خلقه القرآن كما في الصحيح."],"496":["قوله: هَمَّازٍ أي: كثير العيب للناس والطعن فيهم بالغيبة والاستهزاء ونحوه.","وقوله: مَشَّاءٍ بِنَمِيمٍ أي: يمشي بين الناس بالنميمة، وينقل حديث بعضهم لبعض ليفسد بينهم ويلقي فيهم العداوة والبغضاء.","وقد جاءت أحاديث كثيرة في التحذير من ذلك، منها:"],"497":["قوله: عُتُلٍّ أي: غليظ الخلق غير منقاد للحق، وقيل: معناه: الشديد في كفره، وكل شديد عند العرب عتل، وأصله من العتل: وهو الدفع بالعنف كما قال تعالى: ﴿خُذُوهُ فَاعْتِلُوهُ إِلَى سَوَاءِ الْجَحِيمِ﴾ [الدخان: ٤٧]","وقوله: زَنِيمٍ أي اللصيق وهو من يدعى أنه من قوم وليس منهم، مأخوذ من الزنمة، وهي قطعة من أذن البعير لا تنزع بل تبقى معلقة بالأذن، ومن معناه أيضا هنة مدلاة في حلق الشاة كالمحلقة بها كما جاء في الصحيح:"],"498":["أي: إن الله عز وجل يكشف عن ساقه يوم القيامة، ويأمر بالسجود، فيسجد المؤمنون، ويريد المنافقون والكفار أن يسجدوا كما سجد المؤمنون، ولكنهم لا يتمكنون من ذلك، كما جاء في الصحيح."],"499":["قوله: ﴿سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لَا يَعْلَمُونَ﴾ أي: إن الله عز وجل قد يمد الكافر وغيره بالأموال والأولاد وغيرها من متاع الدنيا استدراجا لهم، ثم يمسكهم، ولا يفلتونه البتة، كما جاء في الحديث."],"500":["بعد ما ذكر الله أذى المشركين لرسول الله صلى الله عليه وسلم وأخبره أنه سوف يحاسبهم حسابًا شديدًا، وأمر النبيصلى الله عليه وسلم بالصبر؛ لأن الصبر مفتاح النجاح - كما يقال-، وقال له: ﴿وَلَا تَكُنْ كَصَاحِبِ الْحُوتِ﴾ في عدم الصبر، وهو أن نبي الله يونس بن متى الذي لم يصبر على تكذيب قومه له، فخرج من بينهم غاضبا قبل أن يؤذن له بذلك، فكان ما كان، وهو التقام الحوت إياه، ثم إلقاؤه بالعراء بأمر الله إلى آخر ما حدث معه، واجتباء الله إياه وجعله من الصالحين، وكذلك يا محمد أنت تكون غالبًا عليهم في النهاية.","وقوله ﴿وَإِنْ يَكَادُ الَّذِينَ كَفَرُوا لَيُزْلِقُونَكَ بِأَبْصَارِهِمْ﴾ أي أن الكفار عند سماع القرآن ينظرون إليه نظرة حسد وعداوة وغيظ، ويؤذونك بألسنتهم ويقولون إنه مجنون فرد الله عليهم يقول: ﴿وَمَا هُوَ إِلَّا ذِكْرٌ لِلْعَالَمِينَ﴾.","وفي قوله لَيُزْلِقُونَكَ بِأَبْصَارِهِمْ دليل على أن العين حق ولولا وقاية الله لك. وفي الآية الكريمة دليل على أن العين حق بأمر الله تعالى، ووردت بذلك أحاديث سبق ذكرها في كتاب الرقية."],"502":["قوله: الْحَاقَّةُ فاعل من حقَّ الشيء إذا ثبت وقوعه، والمراد بها يوم القيامة لأنه يوم محقَّق وقوعُه كما قال تعالى: ﴿وَتُنْذِرَ يَوْمَ الْجَمْعِ لَا رَيْبَ فِيهِ فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ﴾ [الشورى: ٧]","وقوله: ﴿كَذَّبَتْ ثَمُودُ وَعَادٌ بِالْقَارِعَةِ﴾ أنهم كذبوا بالحاقة، والقارعة بمعنى الحاقة من قرع إذا ضربه ضربا قويا أي التي تصيب الناس بالأهوال والأفزاع.","وقوله: ﴿فَأَمَّا ثَمُودُ فَأُهْلِكُوا بِالطَّاغِيَةِ والطاغية هي القارعة والصاعقة وسميت في بعض الأيات بـ\"الصيحة\". ومنازل ثمود كانت بين المدينة وتبوك في طريق الشام، وكانت قريش ترى آثارهم في رحلتهم قال تعالى: فَتِلْكَ بُيُوتُهُمْ خَاوِيَةً بِمَا ظَلَمُوا﴾ [سورة النمل: ٥٢]","وهي تسمى اليوم بـ\"مدائن صالح\" لأن نبي الله صالح عليه السلام بعث إليهم ﴿وَإِلَى ثَمُودَ أَخَاهُمْ صَالِحًا﴾ [سورة الأعراف: ٧٣]"],"503":["قوله: بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ أي: ريح شديد الهبوب، وكانت جاءت عليهم من جهة الغرب، وهي التي يقال لها الدبور، وقد جاء في الصحيح."],"504":["قوله: ﴿بِمَا أَسْلَفْتُمْ فِي الْأَيَّامِ الْخَالِيَةِ﴾ أي: بسبب أعمالكم الصالحة في الدنيا، مع فضل الله عز وجل ورحمته، فإنه لا يدخل الجنة أحد إلا بفضل الله ورحمته، ولذلك أهل الجنة بعد دخولهم الجنة يقولون: ﴿أَحَلَّنَا دَارَ الْمُقَامَةِ مِنْ فَضْلِهِ﴾ [فاطر: 35] وقد جاء في الصحيح."],"505":["أي رفيعة؛ لأن الجنة لها درجات بعضها أعلى من بعض، وقد جاء في الصحيح."],"506":["قوله: فَاسْلُكُوهُ أي: شُدُّوه في السلسلة وجُرُّوه على وجهه فيها، وقد جاء في الحديث."],"507":["أي إنه ما كان يؤدّي حق الله، وهو الإيمان به، وعبادته وحده دون غيره، كما أنه ما كان يؤدّي حق غيره من الفقراء والمساكين، ولا يحض غيره على إطعامهم، فمثل هذا عدمه خير من وجوده.","قوله: فَلَيْسَ لَهُ الْيَوْمَ هَاهُنَا حَمِيمٌ الحميم هو القريب الذي لا تنفع شفاعته اليوم لتنجو من عذاب الله.","قوله: ﴿وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ﴾ غسلين: هو صديد أهل النار الذي يكون في غاية الحرارة، ونَتْن الريح، وقُبْح الطعم.","قوله: لَا يَأْكُلُهُ إِلَّا الْخَاطِئُونَ الذين أخطأوا الصراط المستقيم مع توفير الأسباب من إرسال الرسل وإنزال الكتب، فاستحقوا دخولهم النار، ويكون هذا طعامهم تنكيلًا لهم."],"509":["قوله: ﴿فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ﴾ أراد مدة المسافة بين الأرض وسدرة المنتهى التي هي مقرّ جبريل، يسير جبريل ومن معه من الملائكة مسيرة خمسين ألف سنة في يوم واحد من أيام الدنيا كما سبق ذكره في تفسير سورة السجدة.","وقال بعض المفسرين: هو يوم القيامة، كما جاء في الصحيح."],"510":["أي: جمع المال، وأمسكه في الأوعية، وحبسه في الخزانات، ولم يؤد منه حق الله عز وجل من الزكاة ونحوها، وقد جاء في الصحيح."],"512":["أي: إن نوحا عليه السلام دعا قومه إلى الله عز وجل ليلا ونهارا، وبلَّغهم رسالة ربه سرا وجهارا، ولكنهم أعرضوا واستكبروا، ولم يؤمن معه إلا قليل، وهؤلاء المعرضون في الدنيا ينكرون يوم القيامة أمام الله دعوته إياهم إلى الله عز وجل، فيشهد له النبي صلى الله عليه وسلم وأمته، كما جاء في الصحيح."],"513":["أي: تارة بعد تارة، وحالا بعد حال، نطفة، ثم علقة، ثم مضغة، إلى تمام الخلق، قال تعالى: ﴿وَلَقَدْ خَلَقْنَا الْإِنْسَانَ مِنْ سُلَالَةٍ مِنْ طِينٍ ثُمَّ جَعَلْنَاهُ نُطْفَةً فِي قَرَارٍ مَكِينٍ ثُمَّ خَلَقْنَا النُّطْفَةَ عَلَقَةً فَخَلَقْنَا الْعَلَقَةَ مُضْغَةً فَخَلَقْنَا الْمُضْغَةَ عِظَامًا فَكَسَوْنَا الْعِظَامَ لَحْمًا ثُمَّ أَنْشَأْنَاهُ خَلْقًا آخَرَ فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ﴾ (14) [المؤمنون: ١٢-١٤]، وقد جاء في الصحيح."],"515":["قوله: دَيَّارًا من دار يدورُ أي: لا تترك كافرا حيث ما كان.","وقوله: ﴿وَلَا يَلِدُوا إِلَّا فَاجِرًا كَفَّارًا﴾ لقد علم نوح عليه السلام من تجربته الطويلة بأن هولاء المشركين لا يلدون إلا من ينشأ على دينهم فيكونون فجارا كفارا عند بلوغهم سن الرشد لأن المولود لا يوصف بالفاجر والكافر."],"516":["قوله: وَلِوَالِدَيَّ لأنهما كانا مؤمنين به، وكان اسم أبيه \" لامك \"، سمى ولده \" نوحًا \"، وهو اسم ساميٌّ معناه \" راحة \"، وكان نوح بارًّا بوالديه.","وقوله: ﴿وَلِمَنْ دَخَلَ بَيْتِيَ مُؤْمِنًا﴾ أريد به ظاهر معناه، وقيل: المراد منه مسجده الذي يتسع لجميع المؤمنين والمؤمنات، والأول أصح.","وقوله: ﴿وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ أي كل من آمن بالله وصدّق رسله.","دعوة نوح عليه السلام بالمغفرة كانت لأربعة أصناف من الناس:","1- لنفسه أوَّلًا.","2- ولوالديه.","3- ولمن دخل بيته مؤمنًا.","4- ولمن آمن بالله وصدَّق رسله من رجال ونساء إلى يوم القيامة، إذا كانت اللام للاستغراق، وإن كانت للعهد فالمراد بها المؤمنون والمؤمنات في عهده، والأول أصح ؛ لأنه أشمل.","قوله: وَلَا تَزِدِ الظَّالِمِينَ إِلَّا تَبَارًا أي هلاكا شاملا، فاستجاب الله دعاءه فأهلكهم بالطوفان الذي استمر أربعين يومًا وليلة، وغرق به كل من كان على وجه الأرض من بشر، ومن حيوانات، ما عدا من كان في السفينة، وبهذا صار نوح عليه السلام هو الأب الثاني للبشر بعد آدم عليه السلام.","إن قصة نوح عليه السلام ورد ذكرها في تراث أغلب الأمم القديمة مثل البابليين واليونان والرومان والهندوس مع اختلاف يسير في بعض الألفاظ والجزئيات، وأوسعها ذكرًا العهد القديم وذلك في سفر التكوين من الإصحاح السادس إلى العاشر.","وصدق الله سبحانه وتعالى : ﴿وَأَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ﴾ [المائدة: ٤٨]، والآيات في هذا المعنى كثيرة."],"519":["قوله: تَعَالَى جَدُّ رَبِّنَا أي: تعالت عظمته وجلاله وكماله.","وقوله: مَا اتَّخَذَ صَاحِبَةً وَلَا وَلَدًا أي: لكمال عظمته وجلاله وغناه، وقد جاء في الصحيح."],"520":["أي: الضر والنفع والرشد والهداية والنجاة كلها بيد الله عز وجل، وليس ذلك إلى أحد من الخلق حتى الرسول صلى الله عليه وسلم، مع كونه أحب الخلق إلى الله عز وجل، وقد جاء في الحديث."],"521":["المشركون كانوا يسألون رسول الله صلى الله عليه وسلم فيقولون كما قال الله عز وجل: مَتَى هَذَا الْوَعْدُ [النمل: 71] وقال تعالى: يَسْأَ﴿لُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْسَاهَا﴾ [النازعات: 42] فأمر الله نبيه صلى الله عليه وسلم أن يقول لهم بأنه لا علم له بوقت الساعة، وأنه لا يدري أقريب وقتها أم بعيد، فالساعة وقتها من أمور الغيب التي لا يعلمها إلا الله عز وجل."],"523":["قوله: يَا أَيُّهَا الْمُزَّمِّلُ قال بعض أهل العلم: كان هذا الخطاب للنبي صلى الله عليه وسلم في أول الوحي، قبل أن يؤمر بتبليغ الرسالة.","وقوله: قُمِ اللَّ﴿يْلَ إِلَّا قَلِيلًا نِصْفَهُ أَوِ انْقُصْ مِنْهُ قَلِيلًا أَوْ زِدْ عَلَيْهِ﴾"],"524":["أي: نوحي إليك هذا القرآن العظيم، ونزول الوحي كان يثقل على النبي صلى الله عليه وسلم حتى إنه كان يتحدر منه العرق في يوم شات، كما جاء في الصحيح."],"525":["ناشئة من النشئ وهو الإيجاد، والمراد منه الصلاة الناشئة التي ينشئها المصلي في الليل، وإذا كان بعد نوم فمعنى النشئ فيها أقوى.","وقال ابن عباس: صلاة الليل كلها ناشئة.","وقوله: هِيَ أَشَدُّ وَطْئًا بفتح الواو، وسكون الطاء، أي أشد على المصلي، وأثقل من صلاة النهار لأن الليل للنوم والراحة.","وقرأ ابن عامر وأبو عمرو: وِطاء بكسر الواو ممدودا بمعنى المواطأة والموافقة، وذلك أن مواطأة القلب والسمع والبصر واللسان بالليل تكون أكثر مما يكون بالنهار. ذكره البغوي في تفسيره (4/493). وقال: عبادة الليل أشد نشاطا، وأتم إصلاحا، وأكثر بركة، وأبلغ في الثواب من عبادة النهار.","وقوله: ﴿إِنَّ لَكَ فِي النَّهَارِ سَبْحًا طَوِيلًا﴾ أي تصرفا وتقلبا وإقبالا وإدبارا في حوائجك وأشغالك. وأصل \"السبح\" سرعة الذهاب، ومنه السباحة في الماء، ولذا فصلِّ في الليل."],"526":["قوله: وَاذْكُرِ اسْمَ رَبِّكَ أي: بالتوحيد والتعظيم.","وقوله: ﴿وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا﴾ أي: انقطع إليه، وتفرغ لعبادته وأخلص له فيها.","وأما التبتل بمعنى ترك النكاح والإعراض عن الزواج والانقطاع عن النساء فليس ذلك من سنن الأنبياء وشرائعهم.","قال تعالى: ﴿وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ وَجَعَلْنَا لَهُمْ أَزْوَاجًا وَذُرِّيَّةً﴾ [الرعد: 38] وقد جاء التحذير من ترك النكاح في الأحاديث والآثار منها."],"527":["قوله: ﴿وَأَقْرِضُوا اللَّهَ قَرْضًا حَسَنًا وَمَا تُقَدِّمُوا لِأَنْفُسِكُمْ مِنْ خَيْرٍ تَجِدُوهُ عِنْدَ اللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا﴾ أي: أمر الله عز وجل بالإنفاق، وهو يشمل الإنفاق الواجب والمستحب، والله عز وجل يعطي على ذلك أحسن الجزاء وأوفره، قال تعالى: ﴿مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ لَهُ أَضْعَافًا كَثِيرَةً﴾ [البقرة: 245] ومال الإنسان في هذه الدنيا هو ما قدَّمه منه لآخرته دون ما أخره للورثة، كما جاء في الصحيح."],"530":["قوله: النَّاقُورِ أي: الصور وهو على هيئة القرن، وقد وُكِّل به ملك، وقد التقمه منذ وُكِّلَ به، وهو ينتظر أمر الله عز وجل للنفخ فيه، كما جاء في الحديث."],"531":["قوله: ﴿ذَرْنِي وَمَنْ خَلَقْتُ وَحِيدًا﴾ هو الوليد بن المغيرة. قال صاحب البحر المحيط: لا خلاف أنها نزلت في الوليد بن المغيرة."],"532":["هؤلاء التسعة عشر هم خزنة جهنم العظام، ومعهم من الملائكة عدد لا يحصيهم إلا الله عز وجل، ولذلك عقَّب بقوله: ﴿وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ وقد﴾ جاء في الصحيح."],"535":["أي: ينظرون إلى الله عز وجل ويرونه سبحانه عيانا، وقد جاء في الصحيح:"],"536":["قوله: ﴿كَلَّا إِذَا بَلَغَتِ التَّرَاقِيَ﴾ التراقي جمع ترقوة، وهي العظام التي بين ثغرة النحر والعاتق، وهذا إخبار عن حالة الاحتضار وقرب وقت الوفاة، وهو كقوله تعالى: ﴿فَلَوْلَا إِذَا بَلَغَتِ الْحُلْقُومَ﴾ [الواقعة: 83]، وقد جاء في الحديث."],"537":["هذا وعيد على وعيد من الله عز وجل لأبي جهل، وهي كلمة موضوعة للتهديد والوعيد."],"540":["قوله: نُطْفَةٍ أَمْشَاجٍ يعني: ماء الرجل وماء المرأة إذا اجتمعا واختلطا، وماء الرجل يكون غليظا أبيض، وماء المرأة يكون رقيقا أصفر، وقد جاء في الصحيح."],"541":["أي: إن الله عز وجل بَيَّنَ له الطريق وما يؤدي إليه ذلك الطريق بيانا واضحا، وهذا مثل قوله تعالى: وَهَدَيْنَاهُ النَّجْدَيْنِ [البلد: 10] أي: بَيَّنَّا له طريق الخير والشكر وطريق الشر والكفر، فمنهم من سلك هذا الطريق، ومنهم من سلك ذاك الطريق، فانقسم الناس إلى شاكر لنعمة الله تعالى وقائم بحقوقه سبحانه، وإلى كافر لنعمة الله تعالى فلم يقم بحقه سبحانه بل كفر به وسلك الطريق الموصل إلى الهلاك، قال تعالى: ﴿وَأَمَّا ثَمُودُ فَهَدَيْنَاهُمْ فَاسْتَحَبُّوا الْعَمَى عَلَى الْهُدَى﴾[فصلت: 17]، وقد جاء في الحديث."],"542":["قوله: يُوفُونَ بِالنَّذْرِ أي: يوفون بما ألزموا به أنفسهم من الطاعات، وقد جاء في الصحيح."],"543":["أي: إنهم يطعمون الطعام مع حبهم إياه، وكذلك ينفقون ما ينفقون في سبيل الله ابتغاء وجه الله عز وجل، مع حاجتهم إليه ومحبتهم له، وقد جاء في الصحيح."],"545":["أقسم الله تعالى في هذه الآيات الكريمة على البعث بعد الموت للحساب والجزاء حسب الأعمال بالمرسلات والعاصفات والناشرات والفارقات، والمراد بها الملائكة الذين يرسلهم الله تعالى لتنفيذ ما يأمرهم به من الأمور المتعلقة بالكون، ولإيصال ما يرسلهم به من الوحي إلى الأنبياء والمرسلين ونحو ذلك من الأعمال والمهام، وهذا المعنى روي عن أبي هريرة وابن عباس وابن مسعود وغيرهم.","والمعنى الآخر أن المراد بها الرياح بأصنافها المختلفة، فالمرسلات: هي الرياح التي أرسلت متتابعة. والعاصفات: هي الرياح الشديدة الهبوب. والناشرات: هي الرياح اللينة، والفارقات: هي التي تفرق السحاب وتبدده. وهذا المعنى نقل عن مجاهد وقتادة والحسن وغيرهم من السلف، والله تعالى أعلم.","وقوله: فَالْمُلْقِيَاتِ ذِكْرًا أي: الملائكة التي تنزل بأمر الله عز وجل ووحيه على الأنبياء والمرسلين، وتلقي إليهم الوحي الذي يكون فيه ذكر وإعذار إلى الخلق، ويكون فيه إنذار لهم إن خالفوا أمر الله عز وجل."],"546":["يؤمر المكذبون يوم القيامة بالذهاب إلى جهنم، ويكون النار فيها بأحوالها الثلاث: الدخان والشرر واللهب، وهذا غاية أوصاف النار إذا اضطرمت واشتدت، وهذا الدخان لا يكون ظليلا في نفسه، ولا يقيهم من حر اللهب، وشررها يتطاير كالقصر، وهو البناء العظيم، مثل الحصون وغيرها.","وفي تفسير هذه الآيات أقوال أخرى، ومنها ما جاء عن ابن عباس."],"547":["قوله: ﴿وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ﴾ أي لا يقدرون على الكلام، ولا يؤذن لهم فيه فيعتذرون؛ لأن الحجة قد قامت عليهم بعد إرسال الرسل وإنزال الكتب.","إن القيامة تكون لها حالات، فالله تعالى يخبر عن حالة تارةً، وعن حالة أخرى تارة، لبيان شدة الأهوال والزلازل يومئذ، ولهذا يؤكد بعد كل حالة بقوله: ﴿وَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ﴾"],"548":["أي إن قدرتم على أن تتخلصوا من قبضتي، وتنجوا من حكمي فافعلوا، هذا فيه تهديد ووعيد شديدان، فإنهم في هذا اليوم لا حيلة لهم للنجاة من عذاب الله."],"550":["قوله: عَمَّ أصله: عن ما، فأدغمت النون في الميم، وحُذِفَتْ ألف \"ما\" كقوله: فِيْمَ، وبِمَ. لما دعا النبي صلى الله عليه وسلم قومه إلى التوحيد، وأخبرهم عن البعث بعد الموت، وتلا عليهم القرآن جعلوا يتساءلون فيما بينهم: ما هذا النبأ العظيم الذي يخبر به محمد وهو البعث. لأنهم كانوا مختلفين في البعث بعد الموت، كما قال الله تعالى: ﴿الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ﴾ فإن من المشركين مَن كانوا يؤمنون بالبعث ولكنهم كانوا يقولون: إن أصنامهم وأوثانهم يشفعون لهم يوم القيامة، ومنهم المنكرون للبعث أصلا، وكانوا يقولون: مَنْ يُحْيِ الْعِظَامَ وَهِيَ رَمِيمٌ [يس:٧8].","ثم سورة النبأ غالبها تتحدث عم يكون يوم القيامة من نفخ الصور، ودخول الجنة والنار، وصفة كل منهما، وهي قرينة صريحة واضحة بأن المراد بالنبأ العظيم هو البعث بعد الموت. ولذا أكَّد الله تعالى في قوله: ﴿كَلَّا سَيَعْلَمُونَ ثُمَّ كَلَّا سَيَعْلَمُونَ أي﴾: عند قيام الساعة."],"551":["قوله: وَالْجِبَالَ أَوْتَادًا أوتاد جمع وتد، وهو الثبوت، يقال: وَتَدَ يَتِدُ وَتْداً أي: ثبت. وأوتاد الأرض ما يجعل الأرض لا تميل، ولا تخرج عن مدارها، وإنما تتحرك في مستقرها، ومنه أوتاد البلاد- أي: رؤساؤهم الذين يُسَيِّرون أمور العامة.","وقوله: ﴿وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا﴾","أي: منقطعا عن الحركة، فإن معنى السبات: القطع، ليرتاح الجسم من عناء العمل."],"552":["قوله: ﴿وَجَعَلْنَا سِرَاجًا وَهَّاجًا والسراج﴾ هنا هو الشمس، ومعنى الوهاج: الذي يجمع النور والحرارة، وهو من الوهج، ومعناه حصول الضوء والحر من النار.","وقوله: ﴿وَأَنْزَلْنَا مِنَ الْمُعْصِرَاتِ مَاءً ثَجَّاجًا﴾ أي: الرياح ذوات الأعاصير التي تجر السحاب فتمطر في مكان، ولا تمطر في مكان. وثجاجا، أي: كثيرا."],"554":["قوله: ﴿إِنَّ لِلْمُتَّقِينَ مَفَازًا﴾ أي: فوزا ونجاة من النار. وقوله: وَكَوَاعِبَ أَتْرَابًا كواعب واحدها كاعب، وهي الجواري قد تكعبت ثُديُّهن، و أَتْرَابًا أي: مستويات في السن."],"555":["قوله: ﴿يَوْمَ يَقُومُ الرُّوحُ وَالْمَلَائِكَةُ صَفًّا﴾ الروح هو: روح القدس، أي: جبريل عليه السلام، أفرد ذكره عن الملائكة لعظم شأنه. وقيل: أرواح بني آدم والجن، ليصفَّ جميع المخلوقات من الإنس والجن والملائكة أمام الله متواضعين خاشعين يوم القيامة."],"556":["قوله: وَيَقُولُ الْكَافِرُ يَا لَيْتَنِي كُنْتُ تُرَابًا يتمنى الكافر يوم القيامة لما يلقى من العذاب فيقول: يا ليتني كنت ترابا ولم أُخْلق، ولم أُخْرج إلى الوجود.","وقيل: إنما يود ذلك حين يحكم الله بين الحيوانات التي كانت في الدنيا، حتى إنه ليقتص للشاة الجماء من القرناء، فإذا فرغ من الحكم بينها قال لها: كوني ترابا. فعند ذلك يقول الكافر: يَا لَيْتَنِي كُنْتُ تُرَابًا أي: كنت حيوانا فأرجع إلى التراب."],"558":["قوله: وَالنَّازِعَاتِ غَرْقًا هي الملائكة التي تنزع نفوس بني آدم، وهو قول أكثر المفسرين.","وقوله: وَالنَّاشِطَاتِ نَشْطًا قال ابن عباس: هي نفس المؤمن تنشط للخروج عند الموت، لما يرى من الكرامة، لأنه تعرض عليه الجنة قبل أن يموت.","وقوله: وَالسَّابِحَاتِ سَبْحًا قيل: هي النجوم والشمس والقمر تسبح في السماء، كما قال تعالى: كُلٌّ فِي فَلَكٍ يَسْبَحُونَ [الأنبياء: 33].","وقوله: فَالسَّابِقَاتِ سَبْقًا قيل: هي الخيل.","وقوله: فَالْمُدَبِّرَاتِ أَمْرًا قيل: هم الملائكة وُكِّلوا بتسيير أمور الدنيا من بداية الخلق إلى نهايته، وهو النفخ في الصور.","أقسم الله سبحانه وتعالى بهذه المخلوقات، وحذف جواب الشرط لتحقق وقوعه وهو الحساب يوم يبعثون بدلالة الآيات التي بعدها ولكن قال النحويون: لا يجوز حذف اللام في جواب اليمين، لأنها إذا حذفت لم يعرف موضعها.","قال ابن جرير في تفسيره (24/68): \"والصواب من القول في ذلك عندنا أن جواب القسم في هذا الموضع مما استغني عنه بدلالة الكلام، فترك ذكره\".","وقوله: ﴿يَوْمَ تَرْجُفُ الرَّاجِفَةُ﴾ النفخة الأولى، ويموت منها جميع الخلائق من في السموات والأرض.","وقوله: تَتْبَعُهَا الرَّادِفَةُ وهي النفخة الثانية، يحيى منها جميع الخلائق.","وهما الصيحتان، كما جاء في قوله تعالى: ﴿وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَنْ فِي السَّمَاوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَى فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ﴾ [الزمر: 68]."],"559":["عقوبة الآخرة على كلمته، وهي قوله: أَنَا رَبُّكُمُ الْأَعْلَى وعقوبة الأولى على كلمته وهي قوله: ﴿مَا عَلِمْتُ لَكُمْ مِنْ إِلَهٍ غَيْرِي﴾ [القصص: 38]، فأخذه الله بكلمتيه كلتيهما، فجعل نكال الآخرة العذاب بالنار، وجعل نكال الأولى الغرق في الدنيا، وقدَّم نكال الآخرة لشدتها وخلودها، وأخَّر نكال الأولى لخفتها.","وجرائم فرعون كثيرة، لكن دعواه للربوبية في قوله: أَنَا رَبُّكُمُ الْأَعْلَى أشد جرما من غيرها، فإن الله تعالى له الربوبية المطلقة، وهو غني عن الندّ والنظير والشريك، ولا يرضى أن يشرك به، ولا يغفره قال تعالى: ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَا﴾ءُ [النساء: 48]."],"560":["قوله: مُرْسَاهَا أي: قيامها مثل قيام العدل وقيام الحق، أي: يسألونك يا محمد، هؤلاء المكذبون بالبعث عن الساعة التي يبعث فيها الموتى من قبورهم، فليس عليك بيان ذلك، وإنما علمها عند الله، وما أنت إلا منذر، يوضح ذلك الحديث الآتي."],"562":["ذكر أن الأعمى الذي جاء ذكره في الآية هو ابن أم مكتوم، واسمه: عبدالله بن شريح بن مالك بن ربيعة الفهري من بني عامر بن لؤي، والمشهور أن اسمه: عمرو، أسلم قديما في مكة، وهاجر إلى المدينة قبل مقدم النبي صلى الله عليه وسلم، وقيل: بعده."],"563":["قوله: سَفَرَةٍ واحده سافر، ويقال: سفرت؛ أي: كتبتُ، ومنه قيل للكاتب: سافر، وللكتاب: سفر، وجمعه أسفار.","والمراد منه الملائكة الكرام الكاتبون، وقد جاء في الصحيح."],"564":["وقوله: وَعِنَبًا وَقَضْبًا والقضب هو الرطبة.","وقوله: وَحَدَائِقَ غُلْبًا أي: غلاظا، عني به أشجار في بساتين غلاظ. والغُلْبُ جمع أغلب، وهو الغليظ الرقبة من الرجال. قاله ابن جرير.","وقوله: وَفَاكِهَةً وَأَبًّا الفاكهة ما يأكله الناس، والأب ما يأكله الدواب، وهو قول ابن عباس وأصحابه وكثير من التابعين؛ لأن الله تعالى قال بعدها: مَتَاعًا لَكُمْ وَلِأَنْعَامِكُمْ أي: الفاكهة لكم، والأب لأنعامكم.","وقوله: فَإِذَا جَاءَتِ الصَّاخَّةُ أي: صيحة القيامة، والصاخَّة اسم من أسماء القيامة، سميت بها لأنها تصخُّ الأسماع، أي: تبالغ في الإسماع حتى تكاد تصمها.","وقوله: ﴿يَوْمَ يَفِرُّ الْمَرْءُ مِنْ أَخِيهِ وَأُمِّهِ وَأَبِيهِ وَصَاحِبَتِهِ وَبَنِيهِ﴾ (36) أي: لا يلتفت أحد إلى أحد منهم لشغله بنفسه، كما في قوله تعالى: ﴿لِكُلِّ امْرِئٍ مِنْهُمْ يَوْمَئِذٍ شَأْنٌ يُغْنِيهِ﴾"],"566":["أي: يجمع بعضها إلى بعض ويُلَفُّ، وكذلك القمر، فيختل تركيبهما ثم يختل نظام سيرهما، وقد جاء في الصحيح."],"567":["قوله: ﴿انْكَدَرَتْ أي: انتثرت، وهذا مثل قوله تعالى: وَإِذَا الْكَوَاكِبُ انْتَثَرَتْ﴾ [سورة الانفطار: 2]"],"568":["قوله: الْمَوْءُودَةُ هي البنت التي كان أهل الجاهلية يدسونها في التراب كراهيةً لها، قال تعالى: ﴿وَإِذَا بُشِّرَ أَحَدُهُمْ بِالْأُنْثَى ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ يَتَوَارَى مِنَ الْقَوْمِ مِنْ سُوءِ مَا بُشِّرَ بِهِ أَيُمْسِكُهُ عَلَى هُونٍ أَمْ يَدُسُّهُ فِي التُّرَابِ﴾[النحل: 58-59]","وكان الرجل من العرب إذا ولدتْ له بنتٌ، وأراد أن يستحييها ألبسها جُبّةً من صوفٍ أو شعرٍ، وتركها ترعى له الإبلَ والغنمَ في البادية، وإذا أراد أن يقتلها تركها حتى إذا صارتْ سداسية، قال لأمها: زَيِّنيها حتى أذهب بها إلى أحمائها، وقد حفر لها بئرًا في الصحراء، فإذا بلغ بها البئر قال لها: انظري إلى هذه البئر، فيدفعها من خلفها في البئر، ثم يهيل على رأسها الترابَ حتى يستوي البئر بالأرض، ذكره البغوي في تفسير سورة النحل.","والمؤودة تُسأل يوم القيامة بأنها على أي ذنب قتلت؟ ليكون ذلك تهديدًا وتقريعًا لقاتلها، فإنه إذا سئلَ المظلومُ فما الظنُّ بالظالم إذا؟ فهو يُسأل عن هذا الذنب من باب أولى، ويجازى عليه عند الله تعالى يوم القيامة."],"569":["أي: رأى النبي صلى الله عليه وسلم جبريل عليه السلام الذي كان يأتيه بالوحي من عند الله على الصورة التي خلقه الله عز وجل عليها، وقد جاء في الصحيح."],"571":["أي: جعلك سويا معتدل القامة، في أحسن الهيئات والأشكال، وقد جاء في الحديث."],"572":["أي: إن عليكم ملائكة كراما كاتبين يكتبون جميع أعمالكم ويحفظونها لكم، ويشهدون بها يوم القيامة، كما جاء في الصحيح."],"573":["وهذا كقوله تعالى: ﴿لِمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَاحِدِ الْقَهَّارِ﴾ [غافر: 16] وقوله تعالى: مَالِكِ يَوْمِ الدِّينِ [الفاتحة: 4] وقد جاء في الصحيح."],"575":["قوله: وَيْلٌ لِلْمُطَفِّفِينَ المطففين من طفّفَ، والطُّفاف –بضم الطاء- ما قصر عن ملأ الإناء من شراب أو طعام قليلا لا يُنتبه له."],"576":["أي يوم القيامة يقوم الناس من قبورهم، ويقفون بين يدي الله عز وجل للحساب والجزاء، ويكون ذلك الموقف صعبا للغاية، وقد جاء في الصحيح."],"580":["قوله: بِالشَّفَقِ هي حمرة الأفق بعد غروب الشمس، وقد جاء في الصحيح."],"585":["قوله: وَالطَّارِقِ من الطروق، وهو المجيء ليلا، وسمي النجم طارقا لأنه لا يُرى في النهار، وإنما يرى في الليل فقط."],"586":["قوله: مَاءٍ دَافِقٍ أي: خارج بقوة وسرعة، والأشهر أنه يطلق على نطفة الرجل.","وقوله: ﴿الصُّلْبِ وَالتَّرَائِبِ الصلب﴾ هو العمود العظمي الكائن في وسط الظهر وهو ذو فقرات.","والترائب جمع تريبة، وهي ضلوع الصدر."],"587":["أي: الكفار يريدون أن يصرفوا الناس عن دعوة الإسلام، ويكيدون لذلك بكل ما في وسعهم، والله عز وجل يرد عليهم كيدهم، فلا يصلون بكيدهم ومكرهم إلى تحقيق مآربهم الخبيثة البتة.","ونسبة الكيد إلى الله عز وجل جاء على وجه المقابلة، لا على وجه الإطلاق، فلا يوصف الله عز وجل به إلا على وجه المقابلة، لأنه في حال المقابلة يدل على القوة والكمال والغلبة لله عز وجل. وأما الوصف به ابتداء أو مطلقا فإنه يقتضي الذم والنقص، والله عز وجل منزه عن كل نقص.","فهذه الصفة وما شاكلها كالمكر والخداع لا تنسب إلى الله عز وجل على الإطلاق، وإنما تنسب إلى الله عز وجل على وجه المقابلة كما جاءت في النصوص."],"589":["أي: الكافر لا يموت في النار فيستريح، ولا يحيى فيها حياة تنفعه وتُسْعده، بل هم يبقون في عذابهم خالدين، قال تعالى: ﴿لَا يُقْضَى عَلَيْهِمْ فَيَمُوتُوا وَلَا يُخَفَّفُ عَنْهُمْ مِنْ عَذَابِهَا﴾ [فاطر: 36] وقال تعالى: وَنَادَوْا يَا مَالِ﴿كُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُمْ مَاكِثُونَ﴾ [الزخرف: 77]، وقد جاء في الصحيح."],"590":["أي: الدنيا ومتاعها زائلة، والآخرة وما فيها باقية، وهذا يقتضي إيثار الباقي على الفاني، وأن لا يضر المرء آخرته بدنياه، فلا يكون همه كله للدنيا، وقد جاء في الحديث."],"592":["نَبَّه الله بذكر هذه المخلوقات العظيمة التي يراها الناس دائما على عظيم قدرته تعالى، وأنه وحده هو المستحق للعبادة دون سواه، وقد جاء في الصحيح."],"594":["قوله: إِلَّا مَنْ تَوَلَّى وَكَفَرَ أي عن طاعة الله ورسوله."],"596":["قوله: وَلَيَالٍ عَشْرٍ المراد بها عشر ذي الحجة، وَالشَّفْعِ يوم النحر، وَالْوَتْرِ يوم عرفة، وقد جاء في الحديث."],"597":["هذه الآية الكريمة فيها ذم للذين لا يكرمون اليتيم، ولا يحسنون إليه، ولا يعطونه حقه، والذي يكرم اليتيم ويكفله موعود بالجنة، كما جاء في الصحيح."],"598":["قوله: وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ أي: يؤتى بجهنم يوم القيامة، يأتي بها جمع كبير من الملائكة، وقد جاء في الصحيح."],"600":["قوله: الْمُطْمَئِنَّةُ أي المصدقة بالثواب.","وقال الحسن البصري: ﴿يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ إذا﴾ أَرَادَ اللهُ عَزَّ وَجَلَّ قَبْضَهَا اطْمَأَنَّتْ إِلَى الله وَاطْمَأَنَّ اللهُ إِلَيْهَا، وَرَضِيَتْ عَنْ الله وَرَضِيَ اللهُ عَنْهَا، فَأَمَرَ بِقَبْضِ رُوحِهَا وَأَدْخَلَهَا اللهُ الْجَنَّةَ، وَجَعَلَهُ مِنْ عِبَادِهِ الصَّالِحِينَ.","ذكره البخاري في تفسير سورة الفجر."],"602":["قوله: بِهَذَا الْبَلَدِ المراد به مكة.","وقوله: ﴿وَأَنْتَ حِلٌّ بِهَذَا الْبَلَدِ﴾ فيه إخبار بهجرة النبي صلى الله عليه وسلم من مكة وخروجه منها، ثم عودته إليها مرة أخرى فاتحا لها، وقد تم هذا الوعد الإلهي في السنة الثامنة من الهجرة بدخول النبي صلى الله عليه وسلم مع عشرة آلاف من الصحابة فاتحا لها، ولأهل العلم في بيان معنى الآية أقوال أخرى، وهي مذكورة في كتب التفاسير."],"603":["أي: فكها من الرق بعتقها أو مساعدتها على حصول العتق، وقد جاء في الصحيح."],"604":["أي: يطعمون الطعام وقت الحاجة والشدة والجوع، وقد جاء في الصحيح."],"605":["قوله: ذِي مَسْغَبَةٍ ذي مجاعة، وقيل: في يوم يشتهى فيه الطعام.","وقوله: يَتِيمًا ذَا مَقْرَبَةٍ أي: هو يتيم وفقير وله قرابة أيضا، فإطعامه ومساعدته والإنفاق عليه أولى وأفضل من غيره، وقد جاء في الحديث."],"606":["أي ثم هو مع هذه الأوصاف الجميلة كان مؤمنا محتسبا ثواب ذلك عند الله عزوجل.","وقوله: ﴿وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ أي﴾ كان مع إيمانه بالله متصفا بالصبر على ما أصابه من الفقر والمسكنة، وموصيًا بالرحمة والشفقة على من كان هذا حاله، وقد جاء في الصحيح:"],"608":["قوله: وَنَفْسٍ وَمَا سَوَّاهَا أي: خلقها سوية على الفطرة، وهذا كقوله تعالى: ﴿فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا فِطْرَتَ اللَّهِ الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ اللَّهِ﴾ [الروم: 30]، وقد جاء في الصحيح."],"609":["أي قد أفلح من زكّى نفسه فأصلحها، وحملها على طاعة الله عزوجل، والأسباب التي تساعد على تزكية النفس كثيرة جدّا، أذكر منها بعضها:","1- الالتزام بقراءة كتاب الله عز وجل في أوقاتٍ يحدّدها المرءُ نفسه.","2- الالتزام بقراءة أذكار الصباح والمساء، وأذكار الليل والنهار، والأذكار التي دبر الصلوات المكتوبة وغيرها.","3- عدم الاشتغال بأمور الدنيا إلا بقدر الحاجة.","4- الإكثار من ذكر هاذم اللذّات في الخلوة، وزيارة القبور كلما تيسّر له ذلك.","5- مساعدة الفقراء والمحتاجين حسب الاستطاعة.","6- حضور مجالس دروس العلماء الصالحين العاملين بالكتاب والسنة، وحضور مجالس موعظتهم لترقيق القلوب، والابتعاد عن مجالس أهل البدع.","7- قراءة سيرة النبي صلى الله عليه وسلم، والصحابة الكرام، والصالحين، والابتعاد عن القصص والحكايات عن أصحاب الخانقاهات، لأنه تفسد التزكية المشروعة..","8- الإقلال من الضحك والمزاح، والإكثار من تذكّر الآخرة والعذاب والثواب.","9- الاجتناب من غيبة الناس.","10- النظر في عيوب نفسه، والاجتناب عن ذكر عيوب الناس.","11- الاجتناب عن قراءة الكتب التي ألّفها أهلُ البدع، والإقبالُ على الكتب التي ألّفها العلماء الراسخون في الكتاب والسنة.","12- الإكثار من الاستغفار، فإنّ النبي صلى الله عليه وسلم كان يستغفرُ اللهَ في اليوم أكثرَ من سبعين مرّةً.","فمن زكّى نفسَه بهذه الأسباب المشروعة وغيرها، لم يجد الوقتَ لإشغالِ نفسِه بالوظائفِ البدعيّةِ، والأعمالِ الشركيّةِ."],"614":["قوله: تَلَظَّى أي: تتوقَّد وتتوهَّج."],"615":["الذي يدخل هذه النار هو الأشقى الذي كذب ما جاء به الرسول صلى الله عليه وسلم من الوحي المتلوِّ والوحي غير المتلوِّ وهو سنته المطهرة.","وقوله: وَتَوَلَّى يعني عن العمل بالأوامر الإلهية والنبوية وعن اجتناب المنهيات."],"616":["ذكر كثير من المفسرين أن هذه الآيات نزلت في أبي بكر الصديق رضي الله عنه وهو الذي يتصف بهذه الصفات الجميلة والكاملة.","وقال غيرهم: هو عام لجميع المؤمنين والمؤمنات ويكون أبوبكر رضي الله عنه هو أول من يدخل في هذه الصفات."],"618":["وقوله: وَمَا قَلَى أي: ما أبغضك الله عز وجل."],"620":["أي: ﴿وجدك لا تدري ما الكتاب ولا الإيمان، فعلَّمك ما لم تكن تعلم، ووفَّقك لأحسن الأعمال والأخلاق، قال تعالى في آية أخرى: وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ رُوحًا مِنْ أَمْرِنَا مَا كُنْتَ تَدْرِي مَا الْكِتَابُ وَلَا الْإِيمَانُ وَلَكِنْ جَعَلْنَاهُ نُورًا نَهْدِي بِهِ مَنْ نَشَاءُ مِنْ عِبَادِنَا وَإِنَّكَ لَتَهْدِي إِلَى صِرَاطٍ مُسْتَقِيمٍ [الشورى: 52] ومثله ما جاء عن موسى عليه السلام في قوله: قَالَ فَعَلْتُهَا إِذًا وَأَنَا مِنَ الضَّالِّينَ﴾ [سورة الشعراء: ٢٠ ]","وليس المراد بالضلال هنا اتباع الباطل والوقوع في الكفر والشرك؛ فإن الأنبياء عليهم السلام معصومون من ذلك كله قبل النبوة وبعدها بالاتفاق.","ذكر الله سبحانه وتعالى في هذه السورة ثلاث منازل أو ثلاث حالات مرَّ بها النبي صلى الله عليه وسلم:","الأولى: اليتم؛ لأن أباه عبد الله توفي وهو حمل في بطن أمه، وقيل: إنه توفي بعد ولادته، ثم توفيت أمه آمنة، فكفله عمه أبو طالب بعد جده عبد المطلب.","الثانية: ضال: أي مررت بهذه المرحلة فهداك الله إلى الصراط المستقيم وآتاك الكتاب الحكيم الذي فيه الحكم والتشريع القويم.","الثالثة: عائل وهو الفقير، فأغناك الله من هذا الفقر بعد غزوة خيبر، فكان النبي صلى الله عليه وسلم يخرج نفقات زوجاته لمدة سنة كاملة.","وبعد ذكر هذه المراحل الثلاث يحث الله نبيه فيمنعه عن قهر اليتيم، ويأمره بحسن السلوك معه، كما يمنعه من نهر السائل، ويأمره أن يكون رفيقًا رقيقًا به، ويتذكر دائمًا نعمة الله عليه، ومن أكبر هذه النعم أن الله اجتباه لرسالته ونبوته."],"629":["قوله: أَنْزَلْنَاهُ الضمير \"هاء\" المراد به القرآن، وقوله: أَنْزَلْنَاهُ مخرج الجميع، والمنزّل هو الله تعالى، والعرب تؤكّدُ فعل الواحد فتجمعه بلفظ الجميع، ليكون أثبت وأوْكد. ذكره البخاري في كتاب التفسير.","وليلة القدر، وهي ليلة مباركة، كما في قوله: إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ [الدخان: 3] وليلة القدر في شهر رمضان، كما قال تعالى: ﴿شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ﴾ [البقرة: 185].","قال ابن عباس وغيره: أنزل الله القرآن جملة واحدة من اللوح المحفوظ إلى بيت العزة من السماء الدنيا، ثم نزل مفصلا بحسب الوقائع في ثلاث وعشرين سنة على رسول الله صلى الله عليه وسلم. وليلة القدر على الصحيح أنها في العشر الأواخر من شهر رمضان في ليالي الوتر."],"630":["أي: إن العمل الصالح في ليلة القدر خير من عمل ألف شهر في غير ليلة القدر، ومن العمل الصالح قراءة القرآن، وقيام الليل، والذكر والدعاء، والصدقة، وصلة الأرحام وغير ذلك. وجاء في الصحيح."],"631":["والروح المراد به جبريل عليه السلام، ويكون معه الملائكة، وهذا من باب عطف الخاص على العام.","وقوله: ﴿بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ﴾ أي: إن نزولهم إلى الأرض يكون فيه كل نوع من الخير والبركة. وقال قتادة وغيره: تقضى فيها الأمور، وتقدر الآجال والأرزاق، كما قال تعالى: ﴿فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ﴾[الدخان: 4].","وقوله: سَلَامٌ ﴿هِيَ حَتَّى مَطْلَعِ الْفَجْرِ﴾ أي: يسلمون على كل مصل، وجالس في المسجد للذكر، وعلى كل من يعمل عملا صالحا في هذه الليلة المباركة، وينتهي هذا النزول بطلوع الفجر."],"636":["قوله: ﴿وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا﴾ أي: ألقت ما فيها من موتاها وكنوزها، فتلقيها على ظهرها. وهو كقوله تعالى: ﴿وَإِذَا الْأَرْضُ مُدَّتْ وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ﴾ (4) [الانشقاق: ٣ – ٤]","وقد جاء في الصحيح:"],"637":["هذه الآية معدودة من جوامع الكلم، وقد وصفها النبي صلى الله عليه وسلم بالجامعة الفاذة، كما في الحديث الآتي:"]});